export const BOT_PRONTO_MAIN_PY = "# -*- coding: utf-8 -*-\n\"\"\"CAOS - bot de gerenciamento para Discord.\n\nRequer Python 3.11+, discord.py 2.x e PyNaCl para conexao a canais de voz.\nConfigure o arquivo .env e execute: python main.py\n\"\"\"\n\nfrom __future__ import annotations\n\nimport asyncio\nimport json\nimport io\nimport os\nimport re\nimport sqlite3\nimport shlex\nimport shutil\nimport subprocess\nimport tempfile\nimport logging\nimport importlib\nimport sys\nimport math\nimport random\nimport wave\nimport base64\nimport urllib.request\nimport urllib.error\nimport unicodedata\nfrom array import array\nfrom datetime import datetime, timezone, timedelta\nfrom zoneinfo import ZoneInfo\nfrom difflib import SequenceMatcher\nfrom pathlib import Path\nfrom typing import Optional\n\nimport discord\nfrom discord import app_commands\n\n# Discord now requires DAVE end-to-end voice encryption in ordinary voice\n# channels. discord.py 2.7.1+ uses the separate `davey` package for this.\ntry:\n    import davey as dave_runtime  # noqa: F401\n    DAVE_IMPORT_ERROR = None\nexcept Exception as _dave_exc: # pyright: ignore[reportUndefinedVariable]\n    dave_runtime = None\n    DAVE_IMPORT_ERROR = _dave_exc\nfrom discord.ext import commands\nfrom dotenv import load_dotenv\n\ntry:\n    import yt_dlp\nexcept ImportError: # type: ignore\n    yt_dlp = None\n\ntry:\n    import imageio_ffmpeg\nexcept Exception as _ffmpeg_import_error: # pyright: ignore[reportUndefinedVariable]\n    imageio_ffmpeg = None\n    logger = logging.getLogger(\"CAOS\")\n    logger.warning(\"imageio-ffmpeg não pôde ser carregado: %s\", _ffmpeg_import_error)\n\ntry:\n    import deno as deno_runtime\nexcept ImportError:\n    deno_runtime = None\n\n\ndef _resolve_ffmpeg_executable() -> str:\n    \"\"\"Encontra FFmpeg pelo pacote Python ou pelo PATH do sistema.\n\n    Usa o mesmo ambiente Python que iniciou o CAOS e fornece uma instrução\n    de instalação precisa quando a dependência não está disponível.\n    \"\"\"\n    global imageio_ffmpeg\n    if imageio_ffmpeg is None:\n        try:\n            imageio_ffmpeg = importlib.import_module(\"imageio_ffmpeg\")\n        except Exception as exc:\n            logger.warning(\"Não foi possível importar imageio_ffmpeg: %s\", exc)\n            imageio_ffmpeg = None\n\n    if imageio_ffmpeg is not None:\n        try:\n            candidate = imageio_ffmpeg.get_ffmpeg_exe()\n            if candidate and Path(candidate).is_file():\n                return str(candidate)\n        except Exception:\n            logger.exception(\"O pacote imageio-ffmpeg foi encontrado, mas não localizou o executável\")\n\n    system_ffmpeg = shutil.which(\"ffmpeg\") or shutil.which(\"ffmpeg.exe\")\n    if system_ffmpeg:\n        return system_ffmpeg\n\n    python_exe = sys.executable or \"python\"\n    requirements = ROOT / \"requirements.txt\"\n    install_command = f'\"{python_exe}\" -m pip install --upgrade -r \"{requirements}\"'\n    raise RuntimeError(\n        \"FFmpeg não foi encontrado no mesmo Python que está executando o CAOS. \"\n        f\"Execute este comando no mesmo computador: {install_command}. Depois reinicie o bot.\"\n    )\n\n\nlogging.basicConfig(level=logging.INFO, format=\"%(asctime)s | %(levelname)s | %(name)s | %(message)s\")\nlogger = logging.getLogger(\"CAOS\")\n\nROOT = Path(__file__).resolve().parent\nASSET_PATH = ROOT / \"assets\" / \"caos.png\"\nPANEL_ART_DIR = ROOT / \"assets\" / \"panels\"\nPANEL_ART = {\n    \"ticket\": \"ticket.jpg\", \"point\": \"point.jpg\", \"goals\": \"goals.jpg\",\n    \"recruitment\": \"recruitment.jpg\", \"rules_discord\": \"rules_discord.jpg\",\n    \"rules_team\": \"rules_team.jpg\", \"rules_rp\": \"rules_rp.jpg\",\n    \"orders\": \"orders.jpg\", \"partnerships\": \"partnerships.jpg\", \"requests\": \"requests.jpg\",\n    \"music\": \"music.jpg\",\n}\nDB_PATH = ROOT / \"caos.sqlite3\"\nload_dotenv(ROOT / \".env\")\n\nTOKEN = os.getenv(\"DISCORD_TOKEN\", \"\").strip()\nCAOS_AI_API_URL = os.getenv(\"CAOS_AI_API_URL\", \"https://black-zone-estudio.vercel.app/api/caos-ai\").strip()\nTEST_GUILD_ID = os.getenv(\"GUILD_ID\", \"\").strip()\n\n# Módulos configurados individualmente pelo produto Bot Pronto do Estúdio.\n# Sem CAOS_MODULES, preserva o comportamento original do pacote local.\n_raw_modules = os.getenv(\"CAOS_MODULES\", \"\").strip()\ntry:\n    ENABLED_MODULES = json.loads(_raw_modules) if _raw_modules else {}\n    if not isinstance(ENABLED_MODULES, dict):\n        ENABLED_MODULES = {}\nexcept (TypeError, ValueError):\n    logger.warning(\"CAOS_MODULES inválido; mantendo os recursos padrão ativos.\")\n    ENABLED_MODULES = {}\n    _raw_modules = \"\"\n\nMODULE_COMMAND_PREFIXES = {\n    \"tickets\": (\"painel_ticket\",),\n    \"attendance\": (\"painel_ponto\", \"meu_rank\", \"rank\", \"configurar_call_ponto\"),\n    \"goals\": (\"painel_metas\", \"cobrar_meta\"),\n    \"warnings\": (\"ver_adv\", \"aplicar_adv\"),\n    \"recruitment\": (\"painel_recrutamento\", \"configurar_recrutador\", \"configurar_cargo_aprovado\", \"recrutador_adicionar_cargo\"),\n    \"team\": (\"instalar\", \"c\", \"configurar_cargo_fac\", \"configurar_cargos_promocao\"),\n    \"logs\": (\"configurar_logs\",),\n    \"rules_discord\": (\"painel_regras_discord\",),\n    \"rules_team\": (\"painel_regras_equipe\",),\n    \"rules_rp\": (\"painel_regras_rp\",),\n    \"music\": (\"painel_musica\", \"musica\", \"pausar_musica\", \"retomar_musica\", \"pular_musica\", \"parar_musica\", \"fila_musica\", \"volume_musica\", \"teste_som\", \"diagnostico_audio\", \"entrar\", \"sair\"),\n    \"ai\": (\"painel_ia\", \"perguntar\", \"criar_imagem\"),\n    \"horror\": (\"configurar_susto\",),\n    \"copy\": (\"painel_copiar\",),\n}\n\ndef module_enabled(module: str) -> bool:\n    if not _raw_modules:\n        return True\n    return bool(ENABLED_MODULES.get(module, False))\n\ndef command_module(command_name: str) -> Optional[str]:\n    for module, command_names in MODULE_COMMAND_PREFIXES.items():\n        if command_name in command_names:\n            return module\n    return None\n\ndef apply_module_filter(tree: app_commands.CommandTree) -> None:\n    \"\"\"Remove comandos desativados antes de sincronizá-los no Discord.\"\"\"\n    panel_modules = (\n        \"tickets\", \"attendance\", \"goals\", \"recruitment\", \"orders\",\n        \"partnerships\", \"requests\", \"rules_discord\", \"rules_team\", \"rules_rp\", \"music\",\n    )\n    for command in list(tree.get_commands()):\n        name = command.name\n        if name == \"painel_encomendas\":\n            if not (module_enabled(\"orders\") or module_enabled(\"partnerships\")):\n                tree.remove_command(name)\n            continue\n        if name == \"gerar_paineis\":\n            if not any(module_enabled(key) for key in panel_modules):\n                tree.remove_command(name)\n            continue\n        module = command_module(name)\n        if module and not module_enabled(module):\n            tree.remove_command(name)\n            logger.info(\"Módulo desativado: removendo comando /%s\", name)\n\ndef panel_module_enabled(panel_key: str) -> bool:\n    panel_modules = {\n        \"ticket\": \"tickets\", \"point\": \"attendance\", \"goals\": \"goals\",\n        \"recruitment\": \"recruitment\", \"rules_discord\": \"rules_discord\",\n        \"rules_team\": \"rules_team\", \"rules_rp\": \"rules_rp\", \"music\": \"music\",\n    }\n    if panel_key == \"requests\":\n        return module_enabled(\"requests\") and (module_enabled(\"orders\") or module_enabled(\"partnerships\"))\n    module = panel_modules.get(panel_key)\n    return bool(module and module_enabled(module))\n\n\n# ---------------------------------------------------------------------------\n# Conteudo dos paineis e regras\n# ---------------------------------------------------------------------------\n\nRULES_DISCORD = \"\"\"📜 REGRAS DO DISCORD\n\nSeja bem-vindo ao Discord da nossa facção! Este servidor foi criado para organizar a comunicação, manter a disciplina e facilitar a convivência entre todos os integrantes.\n\nPara manter um ambiente organizado e evitar problemas, todos os membros devem conhecer e respeitar as regras abaixo.\n\n1. Respeito e postura\n• Respeite todos os integrantes, independentemente do cargo ou patente.\n• Não serão tolerados xingamentos, provocações, preconceito ou qualquer tipo de desrespeito.\n• Evite discussões desnecessárias e conflitos dentro dos canais.\n• Brincadeiras são permitidas, desde que não ultrapassem os limites.\n\n2. Organização dos canais\n• Utilize cada canal para sua finalidade.\n• Evite conversas paralelas em canais de avisos e informações.\n• Não envie mensagens repetidas, spam ou conteúdos desnecessários.\n• Não marque cargos ou superiores sem necessidade.\n\n3. Hierarquia\n• Respeite a hierarquia da facção.\n• Ordens e orientações dos superiores devem ser respeitadas.\n• Caso tenha alguma reclamação ou discordância, procure resolver diretamente com a liderança, sem criar discussões públicas.\n• É proibido desautorizar ou desrespeitar um superior na frente dos demais membros.\n\n4. Calls e comunicação\n• Mantenha uma postura adequada nas calls.\n• Evite gritaria, interrupções e conversas que atrapalhem a comunicação.\n• Durante reuniões e operações, mantenha o foco nas orientações.\n• Não entre em calls restritas sem autorização.\n\n5. Divulgação e conteúdos\n• É proibida a divulgação de outros servidores, facções ou comunidades sem autorização.\n• Não envie links suspeitos ou conteúdos inadequados.\n• É proibido compartilhar informações internas da facção com pessoas de fora.\n\n6. Comprometimento\n• Mantenha-se informado sobre os avisos e comunicados.\n• Cumpra suas responsabilidades dentro da facção.\n• Caso precise se ausentar, comunique a liderança.\n• Demonstre comprometimento e respeito com o grupo.\n\n7. Punições\nO descumprimento das regras poderá resultar em:\n• Advertência verbal.\n• Advertência formal.\n• Rebaixamento de cargo.\n• Suspensão.\n• Expulsão da facção.\n\nA gravidade da punição será definida pela liderança, considerando a situação e a reincidência.\n\n⚠️ CONSIDERAÇÕES FINAIS\nAo permanecer neste Discord, você declara estar ciente das regras e concordar em respeitá-las.\n\nLembre-se: representar uma facção não é apenas ter um cargo ou uma patente, mas também demonstrar postura, disciplina, lealdade e responsabilidade.\n\nA organização começa pelo respeito de cada integrante.\"\"\"\n\nRULES_TEAM = \"\"\"📜 REGRAS DA EQUIPE\n\nTodos os integrantes devem seguir as regras abaixo para manter a organização da facção dentro da city. As regras são válidas para todos, independentemente do cargo ou patente.\n\n1. COMUNICAÇÃO E RÁDIO\n• É obrigatório entrar na rádio da fac sempre que entrar na city.\n• Antes de entrar na favela, é obrigatório blipar na rádio e avisar sua chegada.\n• Mantenha a rádio ativa e fique atento aos comunicados.\n• Evite conversas paralelas durante comunicações importantes.\n• Não abandone a rádio sem necessidade ou sem avisar.\n• É proibido passar informações internas para pessoas de fora da fac.\n\n2. PADRÃO DA FACÇÃO\n• É obrigatório utilizar mochila para entrar na favela.\n• Todos devem respeitar o padrão de veículos estabelecido pela liderança.\n• Não é permitido entrar na favela com veículos fora do padrão.\n• Respeite a identidade visual definida pela organização.\n• Não altere o padrão sem autorização de um responsável.\n\n3. REGRAS DA FAVELA\n• É totalmente proibido atirar dentro da favela.\n• Não arrume confusão ou provoque outros integrantes dentro do território.\n• Respeite os espaços e veículos dos demais membros.\n• Não leve pessoas de fora para dentro da favela sem autorização.\n• Ao entrar ou sair, siga o procedimento de comunicação pela rádio.\n\n4. HIERARQUIA E RESPEITO\n• Respeite todos os integrantes, principalmente seus superiores.\n• Ordens da liderança devem ser cumpridas, desde que estejam de acordo com as regras do servidor.\n• Não questione ou discuta decisões da liderança na frente de todos. Caso discorde, procure conversar em particular.\n• É proibido causar intrigas ou criar conflitos entre membros.\n• Ter cargo não dá direito de desrespeitar ninguém.\n\n5. AÇÕES E ATIVIDADES\n• Respeite as regras de cada ação estabelecidas pelo Complexo MTA.\n• Siga as orientações dos responsáveis durante as atividades.\n• Não abandone ações sem comunicar o motivo.\n• É proibido atrapalhar atividades da própria facção.\n• Evite agir por conta própria quando a situação exigir organização ou autorização.\n\n6. CONDUTA DOS INTEGRANTES\n• Não utilize o nome da facção para resolver problemas pessoais.\n• É proibido prejudicar a própria organização por motivos particulares.\n• Não compartilhe prints, conversas ou informações internas sem autorização.\n• Mantenha uma postura adequada dentro e fora da favela.\n• Qualquer problema entre integrantes deve ser levado à liderança.\n\n7. ATIVIDADE E COMPROMISSO\n• Mantenha uma frequência de atividade na facção.\n• Caso precise ficar ausente, avise algum responsável.\n• Participe das reuniões e atividades quando convocado.\n• Fique atento aos avisos e mudanças nas regras.\n• Demonstre compromisso com a organização.\n\n8. PUNIÇÕES\nO descumprimento das regras poderá resultar em:\n• Advertência verbal.\n• Advertência formal.\n• Suspensão.\n• Rebaixamento de cargo.\n• Expulsão da facção.\n\nA punição será definida conforme a gravidade da situação e o histórico do integrante.\n\n⚠️ AVISO FINAL\nAs regras não são opcionais e devem ser respeitadas por todos. Não haverá privilégios por amizade, tempo de casa ou cargo.\n\nQuem escolhe fazer parte da fac também precisa respeitar sua organização.\n\nRespeite a hierarquia, cumpra seu papel e represente a facção da maneira correta.\"\"\"\n\nRULES_RP = \"\"\"🚔 REGRAS DE RP — RESUMO DE ORIENTAÇÃO\n\nEste painel resume regras das páginas oficiais do Complexo Roleplay indicadas pela liderança. O regulamento completo e eventuais atualizações devem ser consultados nos links ao final.\n\n1. ROLEPLAY E ANTI-RP\n• Roleplay é interpretar um personagem com história, personalidade e motivações próprias, agindo de forma coerente e respeitosa.\n• Anti-RP é agir fora do contexto do personagem ou quebrar intencionalmente a imersão e a narrativa.\n\n2. AMOR À VIDA\n• Preserve a vida do personagem. Evite riscos extremos sem justificativa plausível.\n• Em risco iminente, reaja de forma realista: fugir, esconder-se ou negociar pode ser mais coerente do que reagir impulsivamente.\n• Respeite ferimentos e consequências físicas ou psicológicas.\n\n3. RDM — RANDOM DEATHMATCH\n• Atacar, ferir ou matar sem motivo válido e sem construção narrativa pode caracterizar RDM.\n• Confrontos devem ter contexto coerente. O uso de armas precisa respeitar a lógica da cena.\n• O guia cita zonas neutras, como hospital, delegacia e spawn, como locais em que iniciar combates é proibido, salvo exceção narrativa forte descrita pela administração.\n\n4. VDM — VEHICLE DEATHMATCH\n• Não use veículos para atropelar, ferir, matar ou causar colisões intencionais sem justificativa válida de RP.\n• O guia inclui car grinding, ratão, PIT e bate-bate sem contexto entre os exemplos de condutas que podem configurar VDM.\n\n5. COMBAT LOGGING (CL)\n• Não saia, reinicie o jogo ou troque de personagem para evitar as consequências de uma cena em andamento.\n• O guia classifica sair após morrer como CL.\n• Se a desconexão for involuntária, retorne imediatamente, não interfira na cena e grave vídeo do momento da queda. O guia afirma que prints não são aceitos como prova de defesa; vídeos são válidos.\n\n6. POWERGAMING\n• Não explore mecânicas de forma irrealista para obter vantagens que não seriam possíveis na vida real.\n• O guia determina que, em tombamentos, capotamentos, manobras, saltos ou colisões em que três ou mais pneus estourem, o veículo deve parar para avaliação dos danos.\n\n7. METAGAMING\n• Não use informações obtidas fora do RP — lives, vídeos, mensagens ou aplicativos — para influenciar seu personagem.\n• Informações relevantes ao personagem devem vir das interações e meios existentes dentro da cidade.\n\n8. REVENGE KILL (RK)\n• Não procure vingança por uma morte usando informações que o personagem não deveria lembrar.\n• O guia determina esquecer os últimos 15 minutos anteriores à morte ou o contexto da ação, conforme a situação, salvo justificativa narrativa específica.\n\n9. COP BAIT\n• Não provoque ou crie armadilhas desonestas para atrair a polícia apenas em benefício próprio.\n• Atenção: o guia diz expressamente que não existe Cop Bait entre jogadores ilegais; essas interações seguem outras regras, como combate e RDM.\n\n10. FLAMING E DARK RP\n• Flaming — insultos, ameaças, humilhações, discriminação ou perseguição hostil — é proibido inclusive em plataformas externas.\n• O guia proíbe Dark RP envolvendo temas como assédio, estupro, racismo e outras ações preconceituosas ou invasivas, classificando a infração como gravíssima.\n\n11. PERSONAGEM E FORÇAR RP\n• Use nomes realistas e adequados ao contexto.\n• Não compartilhe informações entre personagens/slots quando o regulamento proíbe; após PD ou saída de uma facção, respeite as regras de memória descritas pelo servidor.\n• Não force situações artificiais nem obrigue outros jogadores a participar de um RP que não desejam.\n\n12. REGRAS DE AÇÕES\n• O guia proíbe utilizar comandos antes, durante ou depois de ações.\n• Em ações de rua, a situação deve terminar na rua; a página prevê exceção para Ilegal x Ilegal envolvendo QG/favela.\n• Em ações de registradora, caixa eletrônico, corrida ilegal, venda de drogas e veículos, o guia proíbe Cop Bait e exige fuga limpa. Durante a fuga limpa, não se pode trocar tiros nem usar armas de fogo ou brancas. O QRR só é permitido para continuar a fuga.\n• O guia estabelece limite geral de até quatro reféns e R$ 50.000 por refém. A página traz uma exceção restrita a ações não blipadas envolvendo cargo alto de organização e história sólida, sujeita à análise administrativa.\n• A prioridade do blip é de quem chega primeiro, desde que cumpra os pré-requisitos da ação.\n• Para guerras, a página indica mínimo de 15 e máximo de 30 participantes, além de igualdade numérica entre as organizações.\n• Cobranças de ações de rua/tretinhas: até 12 horas após o fato; para outros motivos, o guia menciona 24 horas. A cobrança deve dar voz e desenvolver o RP.\n• Invasões de favelas/casas do crime exigem RP prévio, história e contexto. Para invasão policial, o guia exige provas registradas.\n\n13. LOJINHAS — REGRAS ESPECÍFICAS\n• Bandidos: mínimo 2 e máximo 4. Polícia: mínimo 3 e máximo 5 (um policial a mais que a quantidade de bandidos).\n• Apenas pistolas; o armamento não é negociável. Todos os bandidos devem estar armados no local.\n• Limite de 1 refém. A negociação é obrigatória.\n• Os bandidos devem permanecer 20 minutos no local após o assalto concluído.\n• É permitido negociar fuga; nesse caso, os bandidos podem ter apenas 1 carro.\n• A polícia aguarda do lado de fora para negociar; os bandidos ficam do lado de dentro, com o refém na porta, se houver.\n• O guia permite rush para fora após 8 minutos de FF, restrito ao perímetro da frente e laterais da loja; não pode avançar para áreas afastadas ou fundos.\n• Não é permitido que a polícia chegue atirando nem que os bandidos disparem antes do início da ação.\n• O dinheiro só pode ser guardado após finalizar a ação, caso a polícia não compareça em 20 minutos.\n• A página permite utilitários (energético, kit médico e colete) e PowerGaming leve.\n\nFONTES OFICIAIS CONSULTADAS\n• Regras de Roleplay: https://complexo-rp.gitbook.io/complexo-roleplay/regras/regras-de-roleplay\n• Regras de ações: https://complexo-rp.gitbook.io/complexo-roleplay/regras-de-acoes\n• Lojinhas: https://complexo-rp.gitbook.io/complexo-roleplay/acoes-pequeno-porte/lojinhas\n\nIMPORTANTE: este texto é um resumo de estudo, não substitui a leitura do regulamento oficial. A administração do Complexo RP pode atualizar as regras.\"\"\"\n\nRULES_TEXT = {\n    \"discord\": (\"「📜」ʀᴇɢʀᴀꜱ ᴅᴏ ᴅɪꜱᴄᴏʀᴅ\", RULES_DISCORD),\n    \"equipe\": (\"「👥」ʀᴇɢʀᴀꜱ ᴅᴀ ᴇǫᴜɪᴘᴇ\", RULES_TEAM),\n    \"rp\": (\"「🚔」ʀᴇɢʀᴀꜱ ᴅᴇ ʀᴘ\", RULES_RP),\n}\n\nRECRUITMENT_QUESTIONS = [\n    \"1/23 — O que é Roleplay (RP)? Explique com suas próprias palavras.\",\n    \"2/23 — O que é Anti-RP? Dê um exemplo de atitude que quebra a imersão.\",\n    \"3/23 — O que significa Amor à Vida e como você agiria se seu personagem estivesse sob ameaça armada?\",\n    \"4/23 — O que é RDM e por que é errado iniciar um combate sem contexto?\",\n    \"5/23 — O que é VDM? Cite um exemplo de uso indevido de veículo.\",\n    \"6/23 — O que é Combat Logging (CL)? O que você deve fazer se cair do servidor involuntariamente durante uma ação?\",\n    \"7/23 — O que é Powergaming? Dê um exemplo.\",\n    \"8/23 — O que é Metagaming? Por que informações de lives ou conversas externas não devem ser usadas pelo personagem?\",\n    \"9/23 — O que é Revenge Kill (RK)? O que o personagem deve esquecer após morrer, conforme o regulamento?\",\n    \"10/23 — O que é Cop Bait? Existe Cop Bait entre jogadores ilegais segundo o guia?\",\n    \"11/23 — O que é Flaming e em quais meios de comunicação essa regra se aplica?\",\n    \"12/23 — O que é Dark RP e por que os temas citados no regulamento são proibidos?\",\n    \"13/23 — O que significa Forçar RP? Como respeitar a liberdade de interpretação dos outros jogadores?\",\n    \"14/23 — Cite duas regras importantes que devem ser respeitadas antes, durante ou depois de uma ação.\",\n    \"15/23 — O que é uma fuga limpa? O que é proibido fazer durante uma QRU de fuga limpa?\",\n    \"16/23 — Qual é o limite geral de reféns por ação e qual o valor máximo por refém indicado no regulamento?\",\n    \"17/23 — Quem tem prioridade no blip de uma ação e quais condições precisam ser cumpridas para manter essa prioridade?\",\n    \"18/23 — Em uma lojinha, qual é o mínimo e o máximo de bandidos e policiais permitidos?\",\n    \"19/23 — Quais armamentos são permitidos em uma lojinha e qual é o limite de reféns?\",\n    \"20/23 — A negociação na lojinha é obrigatória? Quanto tempo os bandidos devem permanecer no local após o assalto concluído?\",\n    \"21/23 — Depois de 8 minutos de FF, onde pode acontecer o rush para fora em uma lojinha? Quais áreas não podem ser avançadas?\",\n    \"22/23 — Qual é o seu ID no jogo?\",\n    \"23/23 — Qual é o seu nome?\",\n]\n\n# ---------------------------------------------------------------------------\n# Banco SQLite e funcoes utilitarias\n# ---------------------------------------------------------------------------\n\n\ndef db() -> sqlite3.Connection:\n    con = sqlite3.connect(DB_PATH)\n    con.row_factory = sqlite3.Row\n    return con\n\n\ndef init_db() -> None:\n    with db() as con:\n        con.executescript(\n            \"\"\"\n            CREATE TABLE IF NOT EXISTS config (\n                guild_id INTEGER NOT NULL, key TEXT NOT NULL, value TEXT NOT NULL,\n                PRIMARY KEY (guild_id, key)\n            );\n            CREATE TABLE IF NOT EXISTS active_points (\n                guild_id INTEGER NOT NULL, user_id INTEGER NOT NULL,\n                started_at TEXT NOT NULL, PRIMARY KEY (guild_id, user_id)\n            );\n            CREATE TABLE IF NOT EXISTS point_sessions (\n                id INTEGER PRIMARY KEY AUTOINCREMENT, guild_id INTEGER NOT NULL,\n                user_id INTEGER NOT NULL, started_at TEXT NOT NULL,\n                ended_at TEXT NOT NULL, duration_seconds INTEGER NOT NULL\n            );\n            CREATE TABLE IF NOT EXISTS rooms (\n                channel_id INTEGER PRIMARY KEY, guild_id INTEGER NOT NULL,\n                user_id INTEGER NOT NULL, kind TEXT NOT NULL,\n                status TEXT NOT NULL DEFAULT 'open', created_at TEXT NOT NULL\n            );\n            CREATE TABLE IF NOT EXISTS goals (\n                id INTEGER PRIMARY KEY AUTOINCREMENT, guild_id INTEGER NOT NULL,\n                user_id INTEGER NOT NULL, member_id TEXT NOT NULL,\n                member_name TEXT NOT NULL, goal_name TEXT NOT NULL,\n                quantity INTEGER NOT NULL, channel_id INTEGER NOT NULL,\n                image_url TEXT, status TEXT NOT NULL DEFAULT 'aguardando_imagem',\n                created_at TEXT NOT NULL\n            );\n            CREATE TABLE IF NOT EXISTS recruitments (\n                id INTEGER PRIMARY KEY AUTOINCREMENT, guild_id INTEGER NOT NULL,\n                user_id INTEGER NOT NULL, channel_id INTEGER NOT NULL,\n                answers_json TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'enviado',\n                created_at TEXT NOT NULL\n            );\n            CREATE TABLE IF NOT EXISTS recruitment_sessions (\n                channel_id INTEGER PRIMARY KEY, guild_id INTEGER NOT NULL,\n                user_id INTEGER NOT NULL, question_index INTEGER NOT NULL DEFAULT 0,\n                answers_json TEXT NOT NULL DEFAULT '[]'\n            );\n            CREATE TABLE IF NOT EXISTS point_presence (\n                guild_id INTEGER NOT NULL, user_id INTEGER NOT NULL,\n                channel_id INTEGER NOT NULL, last_confirmed_at TEXT NOT NULL,\n                pending_since TEXT, PRIMARY KEY (guild_id, user_id)\n            );\n            CREATE TABLE IF NOT EXISTS weekly_promotion_runs (\n                guild_id INTEGER NOT NULL, user_id INTEGER NOT NULL, week_start TEXT NOT NULL,\n                role_id INTEGER, created_at TEXT NOT NULL,\n                PRIMARY KEY (guild_id, user_id, week_start)\n            );\n            CREATE TABLE IF NOT EXISTS promotions (\n                id INTEGER PRIMARY KEY AUTOINCREMENT, guild_id INTEGER NOT NULL,\n                user_id INTEGER NOT NULL, role_id INTEGER NOT NULL,\n                week_start TEXT NOT NULL, hours_seconds INTEGER NOT NULL,\n                created_at TEXT NOT NULL\n            );\n            CREATE TABLE IF NOT EXISTS adv_state (\n                guild_id INTEGER NOT NULL, user_id INTEGER NOT NULL,\n                adv_count INTEGER NOT NULL DEFAULT 0, last_adv_at TEXT,\n                next_adv_at TEXT, source_week_start TEXT,\n                ticket_channel_id INTEGER, PRIMARY KEY (guild_id, user_id)\n            );\n            CREATE TABLE IF NOT EXISTS adv_week_checks (\n                guild_id INTEGER NOT NULL, user_id INTEGER NOT NULL,\n                week_start TEXT NOT NULL, handled_at TEXT NOT NULL,\n                PRIMARY KEY (guild_id, user_id, week_start)\n            );\n            CREATE TABLE IF NOT EXISTS goal_obligations (\n                id INTEGER PRIMARY KEY AUTOINCREMENT, guild_id INTEGER NOT NULL,\n                user_id INTEGER NOT NULL, created_by INTEGER NOT NULL,\n                description TEXT NOT NULL, deadline_at TEXT NOT NULL,\n                status TEXT NOT NULL DEFAULT 'pendente', created_at TEXT NOT NULL\n            );\n            CREATE TABLE IF NOT EXISTS adv_events (\n                id INTEGER PRIMARY KEY AUTOINCREMENT, guild_id INTEGER NOT NULL,\n                user_id INTEGER NOT NULL, actor_id INTEGER, adv_count INTEGER NOT NULL,\n                event_type TEXT NOT NULL, note TEXT NOT NULL DEFAULT '',\n                created_at TEXT NOT NULL\n            );\n            CREATE TABLE IF NOT EXISTS ai_history (\n                id INTEGER PRIMARY KEY AUTOINCREMENT, guild_id INTEGER NOT NULL,\n                channel_id INTEGER NOT NULL, user_id INTEGER NOT NULL,\n                role TEXT NOT NULL, content TEXT NOT NULL, created_at TEXT NOT NULL\n            );\n            CREATE INDEX IF NOT EXISTS idx_ai_history_lookup\n                ON ai_history(guild_id, channel_id, user_id, id DESC);\n            \"\"\"\n        )\n        # Migra colunas sem apagar histórico existente.\n        for migration in (\n            \"ALTER TABLE recruitments ADD COLUMN ai_flag INTEGER NOT NULL DEFAULT 0\",\n            \"ALTER TABLE recruitments ADD COLUMN ai_reasons TEXT NOT NULL DEFAULT ''\",\n            \"ALTER TABLE recruitments ADD COLUMN reviewed_by INTEGER\",\n        ):\n            try:\n                con.execute(migration)\n            except sqlite3.OperationalError as exc:\n                if \"duplicate column name\" not in str(exc).lower():\n                    raise\n        # Migração de remoção do assistente antigo: elimina apenas configuração e\n        # histórico exclusivos da IA, mantendo ponto, metas, tickets e recrutamento.\n        con.execute(\"DELETE FROM config WHERE key='ai_channel_id'\")\n        con.execute(\"DROP TABLE IF EXISTS ai_sessions\")\n        con.execute(\"DROP TABLE IF EXISTS ai_usage\")\n\n\ndef config_get(guild_id: int, key: str) -> Optional[str]:\n    with db() as con:\n        row = con.execute(\n            \"SELECT value FROM config WHERE guild_id=? AND key=?\", (guild_id, key)\n        ).fetchone()\n    return row[\"value\"] if row else None\n\n\ndef config_set(guild_id: int, key: str, value: str | int) -> None:\n    with db() as con:\n        con.execute(\n            \"INSERT INTO config(guild_id,key,value) VALUES(?,?,?) \"\n            \"ON CONFLICT(guild_id,key) DO UPDATE SET value=excluded.value\",\n            (guild_id, key, str(value)),\n        )\n\n\ndef _caos_ai_post_sync(payload: dict) -> dict:\n    \"\"\"Envia uma solicitação à API privada do CAOS sem expor a chave do Gateway.\"\"\"\n    if not TOKEN:\n        raise RuntimeError(\"O token do Discord não está disponível para autenticar a IA.\")\n    request = urllib.request.Request(\n        CAOS_AI_API_URL,\n        data=json.dumps(payload, ensure_ascii=False).encode(\"utf-8\"),\n        headers={\n            \"Content-Type\": \"application/json\",\n            \"Authorization\": \"Bot \" + TOKEN,\n            \"Accept\": \"application/json\",\n        },\n        method=\"POST\",\n    )\n    try:\n        with urllib.request.urlopen(request, timeout=80) as response:\n            raw = response.read(9 * 1024 * 1024)\n            data = json.loads(raw.decode(\"utf-8\")) if raw else {}\n    except urllib.error.HTTPError as exc:\n        raw = exc.read(16000).decode(\"utf-8\", errors=\"replace\")\n        try:\n            detail = json.loads(raw).get(\"error\", \"\")\n        except Exception:\n            detail = \"\"\n        if exc.code == 402:\n            raise RuntimeError(\"A cota gratuita da IA está sem saldo no momento. Nenhuma recarga será feita automaticamente.\") from exc\n        if exc.code == 429:\n            raise RuntimeError(detail or \"A IA atingiu o limite temporário de uso. Tente mais tarde.\") from exc\n        if exc.code in (401, 403):\n            raise RuntimeError(\"O CAOS não está autorizado na API da IA. Confira a configuração no ADM.\") from exc\n        raise RuntimeError(detail or f\"A API da IA respondeu com HTTP {exc.code}.\") from exc\n    except (urllib.error.URLError, TimeoutError) as exc:\n        raise RuntimeError(\"Não consegui conectar ao serviço de IA. Tente novamente mais tarde.\") from exc\n    if not isinstance(data, dict):\n        raise RuntimeError(\"A API de IA retornou uma resposta inválida.\")\n    if data.get(\"ok\") is not True:\n        raise RuntimeError(str(data.get(\"error\") or \"A IA não conseguiu concluir o pedido.\"))\n    return data\n\n\nasync def caos_ai_post(payload: dict) -> dict:\n    return await asyncio.to_thread(_caos_ai_post_sync, payload)\n\n\ndef ai_history_get(guild_id: int, channel_id: int, user_id: int, limit: int = 8) -> list[dict]:\n    with db() as con:\n        rows = con.execute(\n            \"SELECT role,content FROM ai_history WHERE guild_id=? AND channel_id=? AND user_id=? ORDER BY id DESC LIMIT ?\",\n            (guild_id, channel_id, user_id, max(1, min(12, int(limit)))),\n        ).fetchall()\n    return [{\"role\": row[\"role\"], \"content\": row[\"content\"]} for row in reversed(rows)]\n\n\ndef ai_history_add(guild_id: int, channel_id: int, user_id: int, role: str, content: str) -> None:\n    clean = str(content or \"\").strip()[:1400]\n    if not clean:\n        return\n    with db() as con:\n        con.execute(\n            \"INSERT INTO ai_history(guild_id,channel_id,user_id,role,content,created_at) VALUES(?,?,?,?,?,?)\",\n            (guild_id, channel_id, user_id, role if role in {\"user\", \"assistant\"} else \"user\", clean, utc_now()),\n        )\n        con.execute(\n            \"DELETE FROM ai_history WHERE guild_id=? AND channel_id=? AND user_id=? AND id NOT IN (SELECT id FROM ai_history WHERE guild_id=? AND channel_id=? AND user_id=? ORDER BY id DESC LIMIT 12)\",\n            (guild_id, channel_id, user_id, guild_id, channel_id, user_id),\n        )\n\n\ndef _normalize_ai_text(value: str) -> str:\n    value = unicodedata.normalize(\"NFKD\", str(value or \"\"))\n    return \"\".join(char for char in value if not unicodedata.combining(char)).lower().strip()\n\n\ndef _is_form_already_done(value: str) -> bool:\n    text = _normalize_ai_text(value)\n    return bool(re.search(r\"\\bja\\s+fiz\\b|\\bfiz\\s+la\\b|\\bfiz\\s+o\\s+formulario\\b|\\bformulario\\s+ja\\s+feito\\b\", text))\n\n\ndef _is_recruitment_question(value: str) -> bool:\n    text = _normalize_ai_text(value)\n    return bool(re.search(r\"\\brec\\b|recrut\\w*|\\binscri\\w*|\\bvagas?\\b|\\b(entrar|quero entrar|como entro) na (equipe|fac\\w*)\\b|\\bcomo participar\\b|\\btem vaga\\b|\\bquero (me )?recrutar\\b|\\bposso entrar\\b|\\bcomo faco para entrar\\b\", text))\n\ndef _is_image_request(value: str) -> bool:\n    # No canal exclusivo de imagens, basta um verbo claro de criação: \"cria um panda\".\n    text = _normalize_ai_text(value)\n    return bool(re.search(r\"\\b(cria|criar|gere|gerar|gera|faz|faca|desenha|desenhar|monta|produz|produzir)\\b\", text))\n\n\ndef _ai_image_bytes(data: dict) -> bytes:\n    encoded = str(data.get(\"imageBase64\") or \"\").strip()\n    if not encoded:\n        raise RuntimeError(\"A IA não retornou uma imagem compatível.\")\n    try:\n        result = base64.b64decode(encoded, validate=True)\n    except Exception as exc:\n        raise RuntimeError(\"A imagem retornada pela IA está inválida.\") from exc\n    if not result or len(result) > 7 * 1024 * 1024:\n        raise RuntimeError(\"A imagem gerada é muito grande para enviar ao Discord.\")\n    return result\n\n\nasync def configured_ai_chat(message: discord.Message) -> None:\n    prompt = message.content.strip()[:1400]\n    if not prompt:\n        return\n    history = ai_history_get(message.guild.id, message.channel.id, message.author.id)\n    ai_history_add(message.guild.id, message.channel.id, message.author.id, \"user\", prompt)\n    try:\n        async with message.channel.typing():\n            result = await caos_ai_post({\n                \"action\": \"chat\", \"guildId\": str(message.guild.id), \"userId\": str(message.author.id),\n                \"prompt\": prompt, \"history\": history,\n            })\n        answer = str(result.get(\"text\") or \"\").strip()[:1800]\n        if not answer:\n            raise RuntimeError(\"A IA retornou uma resposta vazia.\")\n        ai_history_add(message.guild.id, message.channel.id, message.author.id, \"assistant\", answer)\n        await message.reply(answer, mention_author=False, allowed_mentions=discord.AllowedMentions.none())\n    except Exception as exc:\n        logger.warning(\"Falha na IA de perguntas (guild=%s): %s\", message.guild.id, str(exc)[:300])\n        await message.reply(f\"⚠️ {str(exc)[:350]}\", mention_author=False, allowed_mentions=discord.AllowedMentions.none())\n\n\nasync def configured_ai_image(channel, guild_id: int, user_id: int, prompt: str, reply_to=None) -> None:\n    prompt = str(prompt or \"\").strip()[:1000]\n    if len(prompt) < 3:\n        if reply_to:\n            await reply_to.reply(\"Descreva a imagem que você quer criar.\", mention_author=False)\n        else:\n            await channel.send(\"Descreva a imagem que você quer criar.\")\n        return\n    try:\n        async with channel.typing():\n            result = await caos_ai_post({\n                \"action\": \"image\", \"guildId\": str(guild_id), \"userId\": str(user_id), \"prompt\": prompt,\n            })\n        image_data = _ai_image_bytes(result)\n        file = discord.File(io.BytesIO(image_data), filename=\"caos-ia.png\")\n        caption = f\"🎨 Imagem criada para <@{user_id}> — {prompt[:220]}\"\n        if reply_to:\n            await reply_to.reply(content=caption, file=file, mention_author=False, allowed_mentions=discord.AllowedMentions.none())\n        else:\n            await channel.send(content=caption, file=file, allowed_mentions=discord.AllowedMentions.none())\n    except Exception as exc:\n        logger.warning(\"Falha na geração de imagem (guild=%s): %s\", guild_id, str(exc)[:300])\n        message = f\"⚠️ Não consegui criar a imagem: {str(exc)[:300]}\"\n        if reply_to:\n            await reply_to.reply(message, mention_author=False, allowed_mentions=discord.AllowedMentions.none())\n        else:\n            await channel.send(message, allowed_mentions=discord.AllowedMentions.none())\n\n\ndef configured_role(guild: discord.Guild, key: str) -> Optional[discord.Role]:\n    role_id = config_get(guild.id, key)\n    return guild.get_role(int(role_id)) if role_id and str(role_id).isdigit() else None\n\n\nasync def recruiter_role(guild: discord.Guild) -> Optional[discord.Role]:\n    role = configured_role(guild, \"recruiter_role_id\")\n    return role or discord.utils.get(guild.roles, name=\"[REC-OFC] Recrutador oficial\")\n\n\ndef is_recruiter(member: discord.Member, guild: discord.Guild) -> bool:\n    role = configured_role(guild, \"recruiter_role_id\") or discord.utils.get(\n        guild.roles, name=\"[REC-OFC] Recrutador oficial\"\n    )\n    return bool(member.guild_permissions.administrator or (role and role in member.roles))\n\n\ndef is_staff_reviewer(member: discord.Member, guild: discord.Guild) -> bool:\n    staff = configured_role(guild, \"staff_role_id\")\n    return bool(\n        member.guild_permissions.administrator\n        or member.id == guild.owner_id\n        or (staff and member.top_role.position >= staff.position)\n    )\n\n\ndef room_get(channel_id: int):\n    with db() as con:\n        return con.execute(\"SELECT * FROM rooms WHERE channel_id=?\", (channel_id,)).fetchone()\n\n\ndef room_add(channel_id: int, guild_id: int, user_id: int, kind: str) -> None:\n    with db() as con:\n        con.execute(\n            \"INSERT OR REPLACE INTO rooms(channel_id,guild_id,user_id,kind,status,created_at) VALUES(?,?,?,?,?,?)\",\n            (channel_id, guild_id, user_id, kind, \"open\", utc_now()),\n        )\n\n\ndef utc_now() -> str:\n    return datetime.now(timezone.utc).isoformat()\n\n\ndef parse_dt(value: str) -> datetime:\n    return datetime.fromisoformat(value)\n\n\ndef safe_slug(value: str) -> str:\n    value = value.lower().strip()\n    value = re.sub(r\"[^a-z0-9-]+\", \"-\", value)\n    value = re.sub(r\"-+\", \"-\", value).strip(\"-\")\n    return (value or \"membro\")[:24]\n\n\ndef format_duration(seconds: int) -> str:\n    seconds = max(0, int(seconds))\n    hours, rem = divmod(seconds, 3600)\n    minutes, _ = divmod(rem, 60)\n    return f\"{hours}h {minutes}min\"\n\n\ndef rank_rows(guild_id: int) -> list[tuple[int, int]]:\n    with db() as con:\n        rows = con.execute(\n            \"SELECT user_id, SUM(duration_seconds) AS total FROM point_sessions \"\n            \"WHERE guild_id=? GROUP BY user_id\", (guild_id,)\n        ).fetchall()\n        active = con.execute(\n            \"SELECT user_id, started_at FROM active_points WHERE guild_id=?\", (guild_id,)\n        ).fetchall()\n    totals = {int(r[\"user_id\"]): int(r[\"total\"] or 0) for r in rows}\n    now = datetime.now(timezone.utc)\n    for row in active:\n        uid = int(row[\"user_id\"])\n        totals[uid] = totals.get(uid, 0) + max(0, int((now - parse_dt(row[\"started_at\"])).total_seconds()))\n    return sorted(totals.items(), key=lambda item: item[1], reverse=True)\n\n\nasync def get_role(guild: discord.Guild, key: str) -> Optional[discord.Role]:\n    role_id = config_get(guild.id, key)\n    if role_id:\n        return guild.get_role(int(role_id))\n    return None\n\n\nasync def ensure_role(guild: discord.Guild, name: str, key: str, color: discord.Colour) -> discord.Role:\n    saved = await get_role(guild, key)\n    if saved:\n        # Atualiza os cargos existentes com os novos nomes e cores decorados.\n        if saved.name != name or saved.colour != color:\n            try:\n                await saved.edit(name=name, colour=color, reason=\"Atualização visual dos cargos CAOS\")\n            except discord.Forbidden:\n                pass\n        return saved\n    existing = discord.utils.get(guild.roles, name=name)\n    if existing is None:\n        existing = await guild.create_role(name=name, colour=color, reason=\"Configuração inicial do bot CAOS\")\n    config_set(guild.id, key, existing.id)\n    return existing\n\n\nasync def ensure_category(guild: discord.Guild, name: str, key: str, staff_role: discord.Role) -> discord.CategoryChannel:\n    saved_id = config_get(guild.id, key)\n    existing = guild.get_channel(int(saved_id)) if saved_id else None\n    if not isinstance(existing, discord.CategoryChannel):\n        existing = discord.utils.get(guild.categories, name=name)\n    if isinstance(existing, discord.CategoryChannel):\n        # Mantem a categoria existente, mas atualiza nome e permissoes do CAOS.\n        try:\n            if existing.name != name:\n                await existing.edit(name=name, reason=\"Atualizacao visual das categorias CAOS\")\n            await existing.set_permissions(guild.default_role, view_channel=False)\n            for role in guild.roles:\n                if role != guild.default_role and role.position >= staff_role.position:\n                    await existing.set_permissions(role, view_channel=True, send_messages=True, read_message_history=True, manage_messages=True)\n            if guild.me:\n                await existing.set_permissions(guild.me, view_channel=True, send_messages=True, manage_channels=True, read_message_history=True)\n        except discord.Forbidden:\n            pass\n        return existing\n    overwrites = {\n        guild.default_role: discord.PermissionOverwrite(view_channel=False),\n    }\n    for role in guild.roles:\n        if role != guild.default_role and role.position >= staff_role.position:\n            overwrites[role] = discord.PermissionOverwrite(\n                view_channel=True, send_messages=True, read_message_history=True, manage_messages=True\n            )\n    if guild.me:\n        overwrites[guild.me] = discord.PermissionOverwrite(view_channel=True, send_messages=True, manage_channels=True, read_message_history=True)\n    return await guild.create_category(name=name, overwrites=overwrites, reason=\"Categorias privadas do CAOS\")\n\n\nasync def staff_role(guild: discord.Guild) -> Optional[discord.Role]:\n    return await get_role(guild, \"staff_role_id\")\n\n\ndef is_staff_or_higher(member: discord.Member, base_role: Optional[discord.Role]) -> bool:\n    \"\"\"Retorna verdadeiro para o cargo-base configurado e todos os cargos acima dele.\"\"\"\n    return base_role is not None and member.top_role.position >= base_role.position\n\n\nasync def create_private_room(\n    guild: discord.Guild,\n    member: discord.Member,\n    kind: str,\n    category_key: str,\n    channel_prefix: str,\n    display_title: str,\n) -> discord.TextChannel:\n    cat_id = config_get(guild.id, category_key)\n    category = guild.get_channel(int(cat_id)) if cat_id else None\n    staff = await staff_role(guild)\n    overwrites: dict[discord.abc.Snowflake, discord.PermissionOverwrite] = {\n        guild.default_role: discord.PermissionOverwrite(view_channel=False),\n        member: discord.PermissionOverwrite(view_channel=True, send_messages=True, read_message_history=True, attach_files=True, embed_links=True),\n    }\n    if staff:\n        for role in guild.roles:\n            if role != guild.default_role and role.position >= staff.position:\n                overwrites[role] = discord.PermissionOverwrite(\n                    view_channel=True, send_messages=True, read_message_history=True, manage_messages=True\n                )\n    if kind == \"recruit\":\n        rec_role = await recruiter_role(guild)\n        if rec_role:\n            overwrites[rec_role] = discord.PermissionOverwrite(\n                view_channel=True, send_messages=True, read_message_history=True, manage_messages=True\n            )\n    if guild.me:\n        overwrites[guild.me] = discord.PermissionOverwrite(view_channel=True, send_messages=True, manage_channels=True, read_message_history=True, attach_files=True)\n    channel = await guild.create_text_channel(\n        name=f\"{channel_prefix}-{safe_slug(member.display_name)}-{str(member.id)[-4:]}\",\n        category=category if isinstance(category, discord.CategoryChannel) else None,\n        overwrites=overwrites,\n        topic=f\"CAOS | {display_title} | membro: {member} ({member.id})\",\n        reason=f\"Abertura de {display_title} pelo bot CAOS\",\n    )\n    room_add(channel.id, guild.id, member.id, kind)\n    return channel\n\n\ndef panel_art_path(panel: Optional[str] = None) -> Optional[Path]:\n    \"\"\"Retorna a arte individual do painel, com a marca CAOS como reserva.\"\"\"\n    if panel and panel in PANEL_ART:\n        candidate = PANEL_ART_DIR / PANEL_ART[panel]\n        if candidate.exists():\n            return candidate\n    return ASSET_PATH if ASSET_PATH.exists() else None\n\n\nasync def send_artifact(\n    destination,\n    content: Optional[str] = None,\n    embed: Optional[discord.Embed] = None,\n    view=None,\n    panel: Optional[str] = None,\n):\n    \"\"\"Envia o painel com sua imagem própria, sem reutilizar a mesma arte em tudo.\"\"\"\n    art_path = panel_art_path(panel)\n    if art_path:\n        filename = f\"caos_{panel or 'marca'}{art_path.suffix}\"\n        file = discord.File(art_path, filename=filename)\n        if embed is not None:\n            embed.set_image(url=f\"attachment://{filename}\")\n        return await destination.send(content=content, embed=embed, view=view, file=file)\n    return await destination.send(content=content, embed=embed, view=view)\n\n\nasync def send_rules_dm(member: discord.Member, key: str) -> bool:\n    title, text = RULES_TEXT[key]\n    chunks = []\n    current = \"\"\n    for line in text.splitlines():\n        candidate = (current + \"\\n\" + line).strip() if current else line\n        if len(candidate) > 1850:\n            chunks.append(current)\n            current = line\n        else:\n            current = candidate\n    if current:\n        chunks.append(current)\n    try:\n        for index, chunk in enumerate(chunks, start=1):\n            embed = discord.Embed(\n                title=title if index == 1 else f\"{title} — continuação {index}\",\n                description=chunk,\n                colour=discord.Colour.from_rgb(22, 126, 220),\n            )\n            embed.set_author(name=\"♛ ᴄᴀᴏꜱ  •  ᴄᴇɴᴛʀᴀʟ ᴅᴇ ʀᴇɢʀᴀꜱ\")\n            embed.set_footer(text=f\"「 CAOS 」 • ᴘáɢɪɴᴀ {index}/{len(chunks)}\")\n            art_key = {\"discord\": \"rules_discord\", \"equipe\": \"rules_team\", \"rp\": \"rules_rp\"}.get(key)\n            art_path = panel_art_path(art_key)\n            if index == 1 and art_path:\n                filename = f\"caos_{art_key or 'regras'}{art_path.suffix}\"\n                file = discord.File(art_path, filename=filename)\n                embed.set_image(url=f\"attachment://{filename}\")\n                embed.set_author(name=\"♛ ᴄᴀᴏꜱ  •  ᴄᴇɴᴛʀᴀʟ ᴅᴇ ʀᴇɢʀᴀꜱ\")\n                await member.send(embed=embed, file=file)\n            else:\n                await member.send(embed=embed)\n        return True\n    except discord.Forbidden:\n        return False\n\n\nasync def notify_staff(guild: discord.Guild, message: str) -> None:\n    channel_id = config_get(guild.id, \"logs_channel_id\")\n    channel = guild.get_channel(int(channel_id)) if channel_id else None\n    if isinstance(channel, discord.TextChannel):\n        await channel.send(message)\n        return\n    role = await staff_role(guild)\n    if role:\n        # Sem canal de logs configurado, a notificação ficará dentro do canal privado.\n        return\n\n\n# ---------------------------------------------------------------------------\n# Views e modals\n# ---------------------------------------------------------------------------\n\nclass TicketPanelView(discord.ui.View):\n    def __init__(self):\n        super().__init__(timeout=None)\n\n    @discord.ui.button(label=\"ᴀʙʀɪʀ ᴛɪᴄᴋᴇᴛ\", emoji=\"🎫\", style=discord.ButtonStyle.danger, custom_id=\"caos:ticket\")\n    async def ticket(self, interaction: discord.Interaction, button: discord.ui.Button):\n        await create_ticket(interaction)\n\nclass GoalPanelView(discord.ui.View):\n    def __init__(self):\n        super().__init__(timeout=None)\n\n    @discord.ui.button(label=\"ᴇɴᴛʀᴇɢᴀʀ ᴍᴇᴛᴀ\", emoji=\"🎯\", style=discord.ButtonStyle.primary, custom_id=\"caos:goal\")\n    async def goal(self, interaction: discord.Interaction, button: discord.ui.Button):\n        await interaction.response.send_modal(GoalModal())\n\n\nclass RecruitmentPanelView(discord.ui.View):\n    def __init__(self):\n        super().__init__(timeout=None)\n\n    @discord.ui.button(label=\"ɪɴɪᴄɪᴀʀ ɪɴꜱᴄʀɪçãᴏ\", emoji=\"📝\", style=discord.ButtonStyle.success, custom_id=\"caos:recruit\")\n    async def recruit(self, interaction: discord.Interaction, button: discord.ui.Button):\n        await start_recruitment(interaction)\n\n\nclass RequestPanelView(discord.ui.View):\n    def __init__(self):\n        super().__init__(timeout=None)\n        self.add_item(RequestTypeSelect())\n\n\nclass RulesPanelView(discord.ui.View):\n    def __init__(self, key: str):\n        super().__init__(timeout=None)\n        self.key = key\n        button = discord.ui.Button(\n            label=\"ᴀʙʀɪʀ ʀᴇɢʀᴀꜱ ɴᴏ ᴘᴠ\",\n            emoji=\"📖\",\n            style=discord.ButtonStyle.danger,\n            custom_id=f\"caos:rules:{key}\",\n        )\n        button.callback = self.open_rules\n        self.add_item(button)\n\n    async def open_rules(self, interaction: discord.Interaction):\n        await deliver_rule(interaction, self.key)\n\n\nclass PointControlView(discord.ui.View):\n    def __init__(self):\n        super().__init__(timeout=None)\n\n    @discord.ui.button(label=\"ɪɴɪᴄɪᴀʀ ᴘᴏɴᴛᴏ\", emoji=\"🟢\", style=discord.ButtonStyle.success, custom_id=\"caos:point:start\")\n    async def start(self, interaction: discord.Interaction, button: discord.ui.Button):\n        guild = interaction.guild\n        member = interaction.user\n        if guild is None or not isinstance(member, discord.Member):\n            return await interaction.response.send_message(\"Use este botão dentro do servidor.\", ephemeral=True)\n        configured = config_get(guild.id, \"point_voice_channel_id\")\n        if configured and (not member.voice or not member.voice.channel or member.voice.channel.id != int(configured)):\n            return await interaction.response.send_message(\"Entre na call monitorada: o ponto começa automaticamente quando você entrar nela.\", ephemeral=True)\n        started = await start_point_for_member(\n            guild, member, member.voice.channel.id if member.voice and member.voice.channel else None,\n            reason=\"Iniciou ponto pelo painel CAOS\",\n        )\n        if not started:\n            return await interaction.response.send_message(\"Você já está com o ponto aberto.\", ephemeral=True)\n        await interaction.response.send_message(\"🟢 Ponto iniciado e registrado. O CAOS contará o tempo em tempo real.\", ephemeral=True)\n\n    @discord.ui.button(label=\"ғᴇᴄʜᴀʀ ᴘᴏɴᴛᴏ\", emoji=\"🔴\", style=discord.ButtonStyle.danger, custom_id=\"caos:point:stop\")\n    async def stop(self, interaction: discord.Interaction, button: discord.ui.Button):\n        guild = interaction.guild\n        member = interaction.user\n        if guild is None or not isinstance(member, discord.Member):\n            return await interaction.response.send_message(\"Use este botão dentro do servidor.\", ephemeral=True)\n        duration = await stop_point_for_member(guild, member, reason=\"Fechou ponto pelo painel CAOS\")\n        if duration is None:\n            return await interaction.response.send_message(\"Você não tem um ponto aberto.\", ephemeral=True)\n        await interaction.response.send_message(\n            f\"🔴 Ponto fechado. Tempo desta sessão: **{format_duration(duration)}**.\", ephemeral=True\n        )\n\n    @discord.ui.button(label=\"ᴍᴇᴜ ʀᴀɴᴋ\", emoji=\"🏆\", style=discord.ButtonStyle.primary, custom_id=\"caos:point:my_rank\")\n    async def my_rank(self, interaction: discord.Interaction, button: discord.ui.Button):\n        await send_rank(interaction, interaction.user.id, self_only=True)\n\n    @discord.ui.button(label=\"ᴄᴏɴꜱᴜʟᴛᴀʀ ʀᴀɴᴋ\", emoji=\"🔎\", style=discord.ButtonStyle.secondary, custom_id=\"caos:point:other_rank\")\n    async def other_rank(self, interaction: discord.Interaction, button: discord.ui.Button):\n        await interaction.response.send_modal(RankLookupModal())\n\n\nclass RankLookupModal(discord.ui.Modal, title=\"🏆 ᴄᴏɴꜱᴜʟᴛᴀʀ ʀᴀɴᴋ\"):\n    member_id = discord.ui.TextInput(label=\"ID ou menção do membro\", placeholder=\"Ex.: 123456789012345678 ou @membro\", max_length=40)\n\n    async def on_submit(self, interaction: discord.Interaction):\n        raw = self.member_id.value.strip()\n        match = re.search(r\"\\d{15,22}\", raw)\n        if not match:\n            return await interaction.response.send_message(\"Não reconheci um ID válido. Tente novamente.\", ephemeral=True)\n        await send_rank(interaction, int(match.group(0)), self_only=False)\n\n\nclass GoalModal(discord.ui.Modal, title=\"🎯 ᴇɴᴛʀᴇɢᴀ ᴅᴇ ᴍᴇᴛᴀ\"):\n    # FileUpload em modal é suportado pelo discord.py 2.7+.\n    # A imagem é obrigatória: o membro não consegue enviar o formulário sem anexá-la.\n    member_id = discord.ui.Label(\n        text=\"ɪᴅ ᴅᴏ ᴍᴇᴍʙʀᴏ\",\n        component=discord.ui.TextInput(\n            placeholder=\"ID Discord ou ID usado na cidade\", max_length=40\n        ),\n    )\n    member_name = discord.ui.Label(\n        text=\"ɴᴏᴍᴇ ᴅᴏ ᴍᴇᴍʙʀᴏ\",\n        component=discord.ui.TextInput(\n            placeholder=\"Nome completo ou nome no RP\", max_length=100\n        ),\n    )\n    goal_name = discord.ui.Label(\n        text=\"ɴᴏᴍᴇ ᴅᴀ ᴍᴇᴛᴀ\",\n        component=discord.ui.TextInput(placeholder=\"Nome da meta\", max_length=100),\n    )\n    quantity = discord.ui.Label(\n        text=\"ǫᴜᴀɴᴛɪᴅᴀᴅᴇ\",\n        component=discord.ui.TextInput(placeholder=\"Ex.: 5\", max_length=10),\n    )\n    proof = discord.ui.Label(\n        text=\"ᴜᴘʟᴏᴀᴅ ᴏʙʀɪɢᴀᴛóʀɪᴏ • ꜰᴏᴛᴏ ᴅᴀ ᴍᴇᴛᴀ\",\n        description=\"Anexe uma imagem da meta ou o comprovante antes de enviar.\",\n        component=discord.ui.FileUpload(\n            custom_id=\"caos_goal_proof\",\n            min_values=1,\n            max_values=1,\n            required=True,\n        ),\n    )\n\n    async def on_submit(self, interaction: discord.Interaction):\n        guild = interaction.guild\n        member = interaction.user\n        if guild is None or not isinstance(member, discord.Member):\n            return await interaction.response.send_message(\n                \"Use este formulário dentro do servidor.\", ephemeral=True\n            )\n\n        # Os campos de texto estão dentro de Labels no modal novo do Discord.\n        member_id = self.member_id.component.value.strip()\n        member_name = self.member_name.component.value.strip()\n        goal_name = self.goal_name.component.value.strip()\n        try:\n            quantity = int(self.quantity.component.value.strip())\n            if quantity <= 0:\n                raise ValueError\n        except ValueError:\n            return await interaction.response.send_message(\n                \"A quantidade precisa ser um número inteiro maior que zero. Abra o formulário novamente.\",\n                ephemeral=True,\n            )\n\n        uploads = self.proof.component.values\n        if not uploads:\n            return await interaction.response.send_message(\n                \"A foto da meta é obrigatória. Abra o formulário novamente e anexe a imagem.\",\n                ephemeral=True,\n            )\n        photo = uploads[0]\n        allowed_extensions = {\".png\", \".jpg\", \".jpeg\", \".webp\", \".gif\", \".bmp\"}\n        extension = Path(photo.filename or \"\").suffix.lower()\n        content_type = (photo.content_type or \"\").lower()\n        if not (content_type.startswith(\"image/\") or extension in allowed_extensions):\n            return await interaction.response.send_message(\n                \"O arquivo precisa ser uma imagem (PNG, JPG, WEBP ou GIF). Abra o formulário e envie uma foto válida.\",\n                ephemeral=True,\n            )\n\n        await interaction.response.defer(ephemeral=True, thinking=True)\n        try:\n            image_data = await photo.read()\n            if not image_data:\n                raise ValueError(\"arquivo vazio\")\n        except (discord.HTTPException, OSError, ValueError):\n            return await interaction.followup.send(\n                \"Não consegui receber a imagem. Tente enviar a entrega novamente.\", ephemeral=True\n            )\n\n        channel = await create_private_room(\n            guild, member, \"goal\", \"goals_category_id\", \"meta\", \"Entrega de meta\"\n        )\n        upload_name = f\"comprovante_meta_{interaction.id}{extension or '.png'}\"\n        with db() as con:\n            con.execute(\n                \"INSERT INTO goals(guild_id,user_id,member_id,member_name,goal_name,quantity,channel_id,image_url,status,created_at) \"\n                \"VALUES(?,?,?,?,?,?,?,?,?,?)\",\n                (\n                    guild.id, member.id, member_id, member_name, goal_name, quantity,\n                    channel.id, photo.url, \"enviada\", utc_now(),\n                ),\n            )\n            con.execute(\n                \"UPDATE goal_obligations SET status='em_analise' WHERE guild_id=? AND user_id=? AND status IN ('pendente','em_adv')\",\n                (guild.id, member.id),\n            )\n\n        # Banner visual do painel e, em seguida, a entrega com a foto anexada.\n        banner = discord.Embed(\n            title=\"「🎯」ᴇɴᴛʀᴇɢᴀ ᴅᴇ ᴍᴇᴛᴀ\",\n            description=\"A entrega foi registrada. A foto enviada no formulário está anexada abaixo para conferência da equipe.\",\n            colour=discord.Colour.from_rgb(22, 126, 220),\n        )\n        staff = await staff_role(guild)\n        await send_artifact(\n            channel,\n            content=f\"{member.mention} • {staff.mention if staff else 'equipe responsável'}\",\n            embed=banner,\n            view=GoalSubmissionReviewView(),\n            panel=\"goals\",\n        )\n\n        def build_goal_embed(*, image_filename: str, include_channel: bool) -> discord.Embed:\n            embed = discord.Embed(\n                title=\"🎯 Nova entrega de meta\",\n                colour=discord.Colour.from_rgb(22, 126, 220),\n                timestamp=discord.utils.utcnow(),\n            )\n            embed.add_field(name=\"Enviado por\", value=member.mention, inline=True)\n            embed.add_field(name=\"ID do membro\", value=member_id, inline=True)\n            embed.add_field(name=\"Nome\", value=member_name, inline=True)\n            embed.add_field(name=\"Meta\", value=goal_name, inline=False)\n            embed.add_field(name=\"Quantidade\", value=str(quantity), inline=True)\n            if include_channel:\n                embed.add_field(name=\"Canal\", value=channel.mention, inline=True)\n            embed.set_image(url=f\"attachment://{image_filename}\")\n            embed.set_footer(text=\"「 CAOS 」 • ᴄᴏɴꜰᴇʀêɴᴄɪᴀ ᴅᴇ ᴍᴇᴛᴀ\")\n            return embed\n\n        uploaded_message = await channel.send(\n            embed=build_goal_embed(image_filename=upload_name, include_channel=False),\n            file=discord.File(io.BytesIO(image_data), filename=upload_name),\n        )\n        await channel.send(\"A equipe pode aprovar ou solicitar correção da entrega pelos botões acima. O canal pode ser fechado pela equipe quando terminar.\", view=CloseRoomView())\n        if uploaded_message.attachments:\n            with db() as con:\n                con.execute(\n                    \"UPDATE goals SET image_url=? WHERE channel_id=?\",\n                    (uploaded_message.attachments[0].url, channel.id),\n                )\n\n        log_id = config_get(guild.id, \"logs_channel_id\")\n        log_channel = guild.get_channel(int(log_id)) if log_id else None\n        if isinstance(log_channel, discord.TextChannel):\n            await log_channel.send(\n                content=staff.mention if staff else None,\n                embed=build_goal_embed(image_filename=upload_name, include_channel=True),\n                file=discord.File(io.BytesIO(image_data), filename=upload_name),\n            )\n\n        await interaction.followup.send(\n            f\"✅ Sua entrega foi enviada com a foto da meta! O canal privado é {channel.mention}.\",\n            ephemeral=True,\n        )\n\n\nasync def build_room_transcript(channel: discord.TextChannel) -> bytes:\n    \"\"\"Monta uma cópia em texto do histórico antes de apagar um canal temporário.\"\"\"\n    lines = [\n        f\"Transcrição do canal #{channel.name}\",\n        f\"ID do canal: {channel.id}\",\n        f\"Servidor: {channel.guild.name} ({channel.guild.id})\",\n        \"=\" * 72,\n    ]\n    truncated = False\n    async for message in channel.history(limit=500, oldest_first=True):\n        timestamp = message.created_at.strftime(\"%Y-%m-%d %H:%M:%S UTC\")\n        author = f\"{message.author} ({message.author.id})\"\n        body = message.clean_content or \"\"\n        extras = []\n        for attachment in message.attachments:\n            extras.append(f\"[Anexo: {attachment.filename}] {attachment.url}\")\n        for embed in message.embeds:\n            if embed.title:\n                extras.append(f\"[Embed: {embed.title}]\")\n            if embed.description:\n                extras.append(embed.description[:1500])\n        content = \"\\n\".join(part for part in [body, *extras] if part)\n        if not content:\n            content = \"[Mensagem sem texto]\"\n        lines.append(f\"\\n[{timestamp}] {author}\\n{content}\")\n        if sum(len(line) for line in lines) > 1_500_000:\n            truncated = True\n            break\n    if truncated:\n        lines.append(\"\\n[Transcrição limitada para respeitar o tamanho máximo do arquivo.]\")\n    if len(lines) <= 4:\n        lines.append(\"\\nNenhuma mensagem encontrada no histórico.\")\n    return \"\\n\".join(lines).encode(\"utf-8\", errors=\"replace\")\n\n\nclass CloseRoomView(discord.ui.View):\n    \"\"\"Botão persistente: apenas equipe configurada, admins e dono podem apagar.\"\"\"\n    def __init__(self):\n        super().__init__(timeout=None)\n\n    @discord.ui.button(\n        label=\"ғᴇᴄʜᴀʀ ᴄᴀɴᴀʟ\",\n        emoji=\"🔒\",\n        style=discord.ButtonStyle.danger,\n        custom_id=\"caos:close_room_staff_only\",\n    )\n    async def close(self, interaction: discord.Interaction, button: discord.ui.Button):\n        await close_room_from_button(interaction)\n\n\nasync def close_room_from_button(interaction: discord.Interaction):\n    \"\"\"Valida a hierarquia e apaga o canal temporário após arquivar a transcrição.\"\"\"\n    guild = interaction.guild\n    channel = interaction.channel\n    member = interaction.user\n\n    if guild is None or not isinstance(channel, discord.TextChannel) or not isinstance(member, discord.Member):\n        return await interaction.response.send_message(\n            \"Este botão só funciona dentro de um canal temporário do CAOS.\", ephemeral=True\n        )\n\n    room = room_get(channel.id)\n    if not room or room[\"status\"] != \"open\" or int(room[\"guild_id\"]) != guild.id:\n        return await interaction.response.send_message(\n            \"Este canal não é um atendimento aberto gerenciado pelo CAOS.\", ephemeral=True\n        )\n\n    staff = await staff_role(guild)\n    is_staff = is_staff_or_higher(member, staff)\n    is_authorized = member.id == guild.owner_id or member.guild_permissions.administrator or is_staff\n    if not is_authorized:\n        return await interaction.response.send_message(\n            \"⛔ Somente o cargo de equipe configurado no `/instalar` e os cargos acima dele, administradores ou o dono do servidor podem fechar este canal.\",\n            ephemeral=True,\n        )\n\n    await interaction.response.defer(ephemeral=True, thinking=True)\n\n    # Arquiva a conversa antes de excluir o canal, quando houver logs configurados.\n    log_note = \"\"\n    log_id = config_get(guild.id, \"logs_channel_id\")\n    log_channel = guild.get_channel(int(log_id)) if log_id and str(log_id).isdigit() else None\n    if isinstance(log_channel, discord.TextChannel) and log_channel.id != channel.id:\n        try:\n            transcript = await build_room_transcript(channel)\n            archive = discord.Embed(\n                title=\"「🗄️」 ᴀᴛᴇɴᴅɪᴍᴇɴᴛᴏ ᴇɴᴄᴇʀʀᴀᴅᴏ\",\n                description=\"O canal foi fechado pelo botão do CAOS. A transcrição está anexada para consulta da equipe.\",\n                colour=discord.Colour.from_rgb(22, 126, 220),\n                timestamp=discord.utils.utcnow(),\n            )\n            archive.add_field(name=\"Canal\", value=f\"#{channel.name} (`{channel.id}`)\", inline=False)\n            archive.add_field(name=\"Tipo\", value=str(room[\"kind\"]).upper(), inline=True)\n            archive.add_field(name=\"Aberto por\", value=f\"<@{room['user_id']}> (`{room['user_id']}`)\", inline=True)\n            archive.add_field(name=\"Fechado por\", value=f\"{member.mention} (`{member.id}`)\", inline=True)\n            await log_channel.send(\n                embed=archive,\n                file=discord.File(io.BytesIO(transcript), filename=f\"transcricao-{channel.id}.txt\"),\n            )\n            log_note = \" A transcrição foi salva no canal de logs.\"\n        except (discord.Forbidden, discord.HTTPException, OSError) as exc:\n            return await interaction.followup.send(\n                f\"⚠️ Não consegui salvar a transcrição ({type(exc).__name__}). O canal foi mantido para não perder o histórico. Verifique as permissões do canal de logs e tente novamente.\",\n                ephemeral=True,\n            )\n    else:\n        log_note = \" ⚠️ Nenhum canal de logs está configurado; o histórico será perdido quando o canal for apagado.\"\n\n    channel_name = channel.name\n    try:\n        await channel.delete(reason=f\"Canal CAOS fechado pelo botão por {member} ({member.id})\")\n    except discord.Forbidden:\n        return await interaction.followup.send(\n            \"❌ Não consegui apagar o canal. Dê ao CAOS a permissão **Gerenciar canais** e tente novamente.\",\n            ephemeral=True,\n        )\n    except discord.HTTPException as exc:\n        return await interaction.followup.send(\n            f\"❌ O Discord não permitiu apagar o canal ({type(exc).__name__}). Tente novamente.\",\n            ephemeral=True,\n        )\n\n    # Remove os cargos temporários associados ao atendimento.\n    try:\n        owner = guild.get_member(int(room[\"user_id\"]))\n        if owner is None:\n            owner = await guild.fetch_member(int(room[\"user_id\"]))\n        role_key = {\n            \"ticket\": \"role_support_id\",\n            \"order\": \"role_order_id\",\n            \"partner\": \"role_partner_id\",\n        }.get(room[\"kind\"])\n        if owner and role_key:\n            role = await get_role(guild, role_key)\n            if role and role in owner.roles:\n                await owner.remove_roles(role, reason=\"Canal CAOS fechado por membro autorizado\")\n    except (discord.Forbidden, discord.HTTPException):\n        pass\n\n    with db() as con:\n        con.execute(\"UPDATE rooms SET status='closed' WHERE channel_id=?\", (channel.id,))\n        if room[\"kind\"] == \"goal\":\n            con.execute(\"UPDATE goals SET status='closed' WHERE channel_id=?\", (channel.id,))\n        if room[\"kind\"] == \"recruit\":\n            con.execute(\"DELETE FROM recruitment_sessions WHERE channel_id=?\", (channel.id,))\n\n    await interaction.followup.send(\n        f\"✅ Canal **#{channel_name}** apagado. Os cargos temporários foram removidos quando aplicável.{log_note}\",\n        ephemeral=True,\n    )\n\n\nclass RequestTypeSelect(discord.ui.Select):\n    def __init__(self):\n        super().__init__(\n            placeholder=\"↓ ᴇꜱᴄᴏʟʜᴀ ᴜᴍᴀ ꜱᴏʟɪᴄɪᴛᴀçãᴏ\",\n            min_values=1,\n            max_values=1,\n            options=[\n                *([discord.SelectOption(label=\"ᴇɴᴄᴏᴍᴇɴᴅᴀ\", value=\"order\", emoji=\"📦\", description=\"Abrir canal privado de encomenda\")] if module_enabled(\"orders\") else []),\n                *([discord.SelectOption(label=\"ᴘᴀʀᴄᴇʀɪᴀ\", value=\"partner\", emoji=\"🤝\", description=\"Abrir canal privado de parceria\")] if module_enabled(\"partnerships\") else []),\n            ],\n            custom_id=\"caos:request_select_alt\",\n        )\n\n    async def callback(self, interaction: discord.Interaction):\n        await create_request_room(interaction, self.values[0])\n\n\n# ---------------------------------------------------------------------------\n# Operacoes do bot\n# ---------------------------------------------------------------------------\n\nasync def create_ticket(interaction: discord.Interaction):\n    if not module_enabled(\"tickets\"):\n        return await interaction.response.send_message(\"O módulo de tickets está desativado neste bot.\", ephemeral=True)\n    guild = interaction.guild\n    member = interaction.user\n    if guild is None or not isinstance(member, discord.Member):\n        return await interaction.response.send_message(\"Use este botão dentro do servidor.\", ephemeral=True)\n    with db() as con:\n        old = con.execute(\"SELECT channel_id FROM rooms WHERE guild_id=? AND user_id=? AND kind='ticket' AND status='open'\", (guild.id, member.id)).fetchone()\n    if old and guild.get_channel(int(old[\"channel_id\"])):\n        return await interaction.response.send_message(f\"Você já tem um ticket aberto: <#{old['channel_id']}>.\", ephemeral=True)\n    await interaction.response.defer(ephemeral=True, thinking=True)\n    channel = await create_private_room(guild, member, \"ticket\", \"ticket_category_id\", \"ticket\", \"Suporte\")\n    role = await get_role(guild, \"role_support_id\")\n    if role:\n        try:\n            await member.add_roles(role, reason=\"Abriu ticket no CAOS\")\n        except discord.Forbidden:\n            pass\n    embed = discord.Embed(\n        title=\"「🎫」ᴄᴇɴᴛʀᴀʟ ᴅᴇ ꜱᴜᴘᴏʀᴛᴇ\",\n        description=f\"Olá, {member.mention}! Explique com detalhes como a equipe pode ajudar.\\n\\nEste canal é privado e visível apenas para você, equipe autorizada e administração do servidor.\\n\\n🔒 Para encerrar, somente o cargo de equipe configurado e os cargos acima dele, administradores ou o dono do servidor podem usar o botão **FECHAR CANAL**.\",\n        colour=discord.Colour.from_rgb(22, 126, 220),\n    )\n    await send_artifact(channel, content=f\"{member.mention} • {role.mention if role else 'Equipe de suporte'}\", embed=embed, view=CloseRoomView(), panel=\"ticket\")\n    await interaction.followup.send(f\"Seu ticket foi aberto: {channel.mention}. Você recebeu o cargo de aguardando suporte, se configurado.\", ephemeral=True)\n\n\nasync def create_request_room(interaction: discord.Interaction, kind: str):\n    required_module = \"orders\" if kind == \"order\" else \"partnerships\"\n    if not module_enabled(required_module):\n        return await interaction.response.send_message(\"Este tipo de solicitação está desativado neste bot.\", ephemeral=True)\n    guild = interaction.guild\n    member = interaction.user\n    if guild is None or not isinstance(member, discord.Member):\n        return await interaction.response.send_message(\"Use este menu dentro do servidor.\", ephemeral=True)\n    if kind not in {\"order\", \"partner\"}:\n        return await interaction.response.send_message(\"Opção inválida.\", ephemeral=True)\n    with db() as con:\n        old = con.execute(\"SELECT channel_id FROM rooms WHERE guild_id=? AND user_id=? AND kind=? AND status='open'\", (guild.id, member.id, kind)).fetchone()\n    if old and guild.get_channel(int(old[\"channel_id\"])):\n        return await interaction.response.send_message(f\"Você já tem um canal aberto: <#{old['channel_id']}>.\", ephemeral=True)\n    await interaction.response.defer(ephemeral=True, thinking=True)\n    is_order = kind == \"order\"\n    role_key = \"role_order_id\" if is_order else \"role_partner_id\"\n    category_key = \"order_category_id\"\n    prefix = \"encomenda\" if is_order else \"parceria\"\n    title = \"「📦」ᴇɴᴄᴏᴍᴇɴᴅᴀ\" if is_order else \"「🤝」ᴘᴀʀᴄᴇʀɪᴀ\"\n    channel = await create_private_room(guild, member, kind, category_key, prefix, title)\n    role = await get_role(guild, role_key)\n    if role:\n        try:\n            await member.add_roles(role, reason=f\"Abriu canal de {prefix} no CAOS\")\n        except discord.Forbidden:\n            pass\n    embed = discord.Embed(\n        title=title,\n        description=f\"{member.mention}, descreva sua solicitação. A equipe responsável responderá por aqui.\\n\\n🔒 Para encerrar, somente o cargo de equipe configurado e os cargos acima dele, administradores ou o dono do servidor podem usar o botão **FECHAR CANAL**. O canal será apagado após o registro da transcrição.\",\n        colour=discord.Colour.from_rgb(22, 126, 220),\n    )\n    await send_artifact(channel, content=f\"{member.mention} • {role.mention if role else 'Equipe responsável'}\", embed=embed, view=CloseRoomView(), panel=\"orders\" if is_order else \"partnerships\")\n    await interaction.followup.send(f\"Canal criado: {channel.mention}.\", ephemeral=True)\n\n\nasync def start_recruitment(interaction: discord.Interaction):\n    guild = interaction.guild\n    member = interaction.user\n    if guild is None or not isinstance(member, discord.Member):\n        return await interaction.response.send_message(\"Use este botão dentro do servidor.\", ephemeral=True)\n    with db() as con:\n        old = con.execute(\"SELECT channel_id FROM rooms WHERE guild_id=? AND user_id=? AND kind='recruit' AND status='open'\", (guild.id, member.id)).fetchone()\n    if old and guild.get_channel(int(old[\"channel_id\"])):\n        return await interaction.response.send_message(f\"Você já tem uma inscrição em andamento: <#{old['channel_id']}>.\", ephemeral=True)\n    await interaction.response.defer(ephemeral=True, thinking=True)\n    channel = await create_private_room(guild, member, \"recruit\", \"recruitment_category_id\", \"recrutamento\", \"Recrutamento\")\n    with db() as con:\n        con.execute(\"INSERT OR REPLACE INTO recruitment_sessions(channel_id,guild_id,user_id,question_index,answers_json) VALUES(?,?,?,?,?)\", (channel.id, guild.id, member.id, 0, \"[]\"))\n    embed = discord.Embed(\n        title=\"「📝」ʀᴇᴄʀᴜᴛᴀᴍᴇɴᴛᴏ ᴄᴀᴏꜱ\",\n        description=f\"Olá, {member.mention}! Responda às **23 perguntas**, uma por mensagem, com suas próprias palavras.\\n\\nAguarde o bot enviar a próxima pergunta. A liderança analisará suas respostas ao final.\\n\\n🔒 Somente o cargo de equipe configurado e os cargos acima dele, administradores ou o dono do servidor podem usar o botão **FECHAR CANAL**.\",\n        colour=discord.Colour.from_rgb(22, 126, 220),\n    )\n    await send_artifact(channel, embed=embed, view=CloseRoomView(), panel=\"recruitment\")\n    await channel.send(f\"**{RECRUITMENT_QUESTIONS[0]}**\")\n    await interaction.followup.send(f\"Sua inscrição foi iniciada em {channel.mention}. Responda uma pergunta por mensagem.\", ephemeral=True)\n\n\nasync def deliver_rule(interaction: discord.Interaction, key: str):\n    member = interaction.user\n    if not isinstance(member, discord.Member):\n        return await interaction.response.send_message(\"Use o painel dentro do servidor.\", ephemeral=True)\n    await interaction.response.defer(ephemeral=True, thinking=True)\n    ok = await send_rules_dm(member, key)\n    if ok:\n        await interaction.followup.send(\"📩 Enviei as regras no seu privado (DM).\", ephemeral=True)\n    else:\n        await interaction.followup.send(\"Não consegui enviar DM. Ative as mensagens diretas deste servidor nas configurações de privacidade e tente novamente.\", ephemeral=True)\n\n\nasync def send_rank(interaction: discord.Interaction, user_id: int, self_only: bool):\n    guild = interaction.guild\n    if guild is None:\n        return await interaction.response.send_message(\"Use este recurso dentro do servidor.\", ephemeral=True)\n    await interaction.response.defer(ephemeral=True, thinking=True)\n    ranking = rank_rows(guild.id)\n    if not ranking:\n        return await interaction.followup.send(\"Ainda não há pontos fechados ou em andamento para formar o ranking.\", ephemeral=True)\n    position = next((i + 1 for i, (uid, _) in enumerate(ranking) if uid == user_id), None)\n    total = next((seconds for uid, seconds in ranking if uid == user_id), 0)\n    member = guild.get_member(user_id)\n    display = member.mention if member else f\"ID {user_id}\"\n    if position is None:\n        return await interaction.followup.send(f\"{display} ainda não tem tempo registrado no ranking.\", ephemeral=True)\n    embed = discord.Embed(title=\"「🏆」ʀᴀɴᴋɪɴɢ ᴅᴇ ᴘᴏɴᴛᴏ\", colour=discord.Colour.from_rgb(22, 126, 220))\n    embed.add_field(name=\"Membro\", value=display, inline=True)\n    embed.add_field(name=\"Posição\", value=f\"#{position}\", inline=True)\n    embed.add_field(name=\"Tempo total\", value=format_duration(total), inline=True)\n    if self_only:\n        embed.description = \"Seu rank é calculado pelo tempo total registrado em ponto.\"\n    else:\n        embed.description = f\"Consulta solicitada por {interaction.user.mention}.\"\n    top = []\n    for idx, (uid, seconds) in enumerate(ranking[:10], start=1):\n        m = guild.get_member(uid)\n        name = m.display_name if m else f\"Membro {str(uid)[-4:]}\"\n        top.append(f\"**{idx}.** {name} — {format_duration(seconds)}\")\n    embed.add_field(name=\"Top 10\", value=\"\\n\".join(top), inline=False)\n    await interaction.followup.send(embed=embed, ephemeral=True)\n\n\n# ---------------------------------------------------------------------------\n# Música: busca no YouTube, seleção por miniatura e reprodução em voz\n# ---------------------------------------------------------------------------\n\nMUSIC_QUEUES: dict[int, list[dict]] = {}\nMUSIC_CURRENT: dict[int, dict] = {}\nMUSIC_VOLUME: dict[int, float] = {}\nMUSIC_LOCKS: dict[int, asyncio.Lock] = {}\nMUSIC_SEARCH_LIMIT = 5\nMUSIC_QUEUE_LIMIT = 30\n\n\ndef _music_deno_path() -> Optional[str]:\n    \"\"\"Localiza Deno instalado pelo pacote Python ou no PATH do sistema.\"\"\"\n    global deno_runtime\n    if deno_runtime is None:\n        try:\n            deno_runtime = importlib.import_module(\"deno\")\n        except Exception:\n            deno_runtime = None\n    if deno_runtime is not None:\n        try:\n            path = deno_runtime.find_deno_bin()\n            if path and Path(path).is_file():\n                return str(path)\n        except Exception:\n            logger.debug(\"Não consegui localizar Deno pelo pacote Python\", exc_info=True)\n    return shutil.which(\"deno\") or shutil.which(\"deno.exe\")\n\n\ndef _music_ytdlp_options(*, flat: bool = False) -> dict:\n    \"\"\"Opções conservadoras do yt-dlp. O extra [default] instala EJS compatível.\"\"\"\n    options = {\n        \"quiet\": True,\n        \"no_warnings\": True,\n        \"noplaylist\": True,\n        \"skip_download\": True,\n        # Não ocultar falhas do YouTube: com ignoreerrors=True a busca pode\n        # retornar uma lista vazia e parecer que simplesmente não encontrou faixas.\n        \"ignoreerrors\": False,\n        # Não usar extract_flat: precisamos de título, thumbnail e URL completos\n        # para montar os cartões de seleção no Discord.\n        \"extract_flat\": False,\n        \"socket_timeout\": 30,\n        \"retries\": 5,\n        \"extractor_retries\": 3,\n        \"fragment_retries\": 5,\n        \"file_access_retries\": 2,\n        \"concurrent_fragment_downloads\": 1,\n        \"cachedir\": False,\n    }\n    deno_path = _music_deno_path()\n    if deno_path:\n        # A API Python do yt-dlp aceita caminho explícito por runtime.\n        options[\"js_runtimes\"] = {\"deno\": {\"path\": deno_path}}\n    return options\n\n\ndef _youtube_search_sync(query_text: str) -> list[dict]:\n    \"\"\"Pesquisa primeiro no YouTube e usa SoundCloud se o YouTube bloquear a busca.\n\n    Não utiliza cookies, sessões autenticadas ou credenciais do usuário.\n    \"\"\"\n    if yt_dlp is None:\n        raise RuntimeError(\"yt-dlp não está instalado. Atualize as dependências do bot.\")\n    query_text = re.sub(r\"\\s+\", \" \", query_text).strip()\n    if not query_text:\n        return []\n    options = _music_ytdlp_options(flat=False)\n    options.update({\"playlistend\": MUSIC_SEARCH_LIMIT, \"extract_flat\": False})\n\n    sources = [\n        (f\"ytsearch{MUSIC_SEARCH_LIMIT}:{query_text}\", \"YouTube\"),\n        (f\"scsearch{MUSIC_SEARCH_LIMIT}:{query_text}\", \"SoundCloud\"),\n    ]\n    errors = []\n    for search_query, source_name in sources:\n        try:\n            with yt_dlp.YoutubeDL(options) as ydl:\n                data = ydl.extract_info(search_query, download=False)\n            entries = (data or {}).get(\"entries\") or []\n            results = []\n            for entry in entries:\n                if not entry:\n                    continue\n                video_id = entry.get(\"id\")\n                url = entry.get(\"webpage_url\") or entry.get(\"original_url\")\n                if not url and video_id and source_name == \"YouTube\":\n                    url = f\"https://www.youtube.com/watch?v={video_id}\"\n                if not url and str(entry.get(\"url\", \"\")).startswith((\"http://\", \"https://\")):\n                    url = entry[\"url\"]\n                if not url:\n                    continue\n                thumbnails = entry.get(\"thumbnails\") or []\n                thumbnail = entry.get(\"thumbnail\")\n                if not thumbnail and thumbnails:\n                    valid = [t for t in thumbnails if isinstance(t, dict) and t.get(\"url\")]\n                    if valid:\n                        thumbnail = max(valid, key=lambda t: (t.get(\"width\") or 0) * (t.get(\"height\") or 0)).get(\"url\")\n                duration_seconds = entry.get(\"duration\")\n                results.append({\n                    \"id\": str(video_id or url),\n                    \"title\": str(entry.get(\"title\") or \"Faixa sem título\")[:240],\n                    \"url\": str(url),\n                    \"thumbnail\": thumbnail,\n                    \"duration\": int(duration_seconds) if duration_seconds else None,\n                    \"uploader\": str(entry.get(\"uploader\") or entry.get(\"channel\") or entry.get(\"channel_name\") or source_name)[:100],\n                    \"source\": source_name,\n                })\n            if results:\n                return results\n        except Exception as exc:\n            errors.append(f\"{source_name}: {type(exc).__name__}: {str(exc)[:220]}\")\n            logger.warning(\"Busca de música falhou em %s; tentando próxima fonte\", source_name, exc_info=True)\n\n    if errors:\n        raise RuntimeError(\"Nenhuma fonte de música respondeu. \" + \" | \".join(errors))\n    return []\n\n\ndef _download_youtube_audio_sync(url: str) -> dict:\n    \"\"\"Baixa o áudio temporariamente usando o próprio yt-dlp.\n\n    O player antigo entregava a URL assinada do YouTube diretamente ao FFmpeg.\n    Isso falhava em alguns formatos/clientes porque as URLs são temporárias e\n    exigem cabeçalhos/assinaturas que o extractor do yt-dlp administra melhor.\n    Aqui o yt-dlp faz a transferência; o FFmpeg lê um arquivo local durante a\n    reprodução. O diretório temporário é apagado quando a faixa termina.\n    \"\"\"\n    if yt_dlp is None:\n        raise RuntimeError(\"yt-dlp não está instalado. Atualize requirements.txt.\")\n\n    temp_dir = tempfile.mkdtemp(prefix=\"caos_music_\")\n    options = _music_ytdlp_options(flat=False)\n    options.update({\n        \"format\": \"bestaudio[acodec!=none]/bestaudio/best\",\n        \"noplaylist\": True,\n        \"geo_bypass\": True,\n        \"skip_download\": False,\n        \"continuedl\": False,\n        \"overwrites\": True,\n        \"outtmpl\": str(Path(temp_dir) / \"track.%(ext)s\"),\n        \"retries\": 8,\n        \"fragment_retries\": 10,\n        \"extractor_retries\": 5,\n        \"concurrent_fragment_downloads\": 2,\n        \"nopart\": True,\n        \"writethumbnail\": False,\n        \"writeinfojson\": False,\n        \"writesubtitles\": False,\n        \"writeautomaticsub\": False,\n    })\n\n    try:\n        with yt_dlp.YoutubeDL(options) as ydl:\n            info = ydl.extract_info(url, download=True)\n            if not info:\n                raise RuntimeError(\"O YouTube não retornou dados para essa faixa.\")\n            requested = info.get(\"requested_downloads\") or []\n            candidates = []\n            for entry in requested:\n                filepath = entry.get(\"filepath\") or entry.get(\"_filename\")\n                if filepath:\n                    path = Path(filepath)\n                    if path.is_file() and path.stat().st_size > 0:\n                        candidates.append(path)\n            if not candidates:\n                prepared = Path(ydl.prepare_filename(info))\n                if prepared.is_file() and prepared.stat().st_size > 0:\n                    candidates.append(prepared)\n            if not candidates:\n                candidates = [p for p in Path(temp_dir).glob(\"*\") if p.is_file() and not p.name.endswith((\".part\", \".ytdl\")) and p.stat().st_size > 0]\n            if not candidates:\n                raise RuntimeError(\"O yt-dlp terminou sem salvar um arquivo de áudio. Tente outra música ou atualize yt-dlp.\")\n            audio_path = max(candidates, key=lambda p: p.stat().st_size)\n\n        return {\n            \"file_path\": str(audio_path),\n            \"temp_dir\": temp_dir,\n            \"title\": str(info.get(\"title\") or \"Faixa sem título\")[:240],\n            \"thumbnail\": info.get(\"thumbnail\"),\n            \"duration\": int(info[\"duration\"]) if info.get(\"duration\") else None,\n            \"webpage_url\": info.get(\"webpage_url\") or url,\n            \"format_id\": str(info.get(\"format_id\") or \"audio\"),\n            \"file_size\": audio_path.stat().st_size,\n        }\n    except Exception:\n        shutil.rmtree(temp_dir, ignore_errors=True)\n        raise\n\n\ndef _duration_label(value: Optional[int]) -> str:\n    if value is None:\n        return \"Duração não informada\"\n    minutes, seconds = divmod(max(0, int(value)), 60)\n    hours, minutes = divmod(minutes, 60)\n    return f\"{hours}:{minutes:02d}:{seconds:02d}\" if hours else f\"{minutes}:{seconds:02d}\"\n\n\nasync def _music_search_response(interaction: discord.Interaction, query_text: str) -> None:\n    query_text = query_text.strip()\n    if len(query_text) < 2:\n        return await interaction.response.send_message(\"Digite pelo menos duas letras para pesquisar.\", ephemeral=True)\n    await interaction.response.defer(ephemeral=True, thinking=True)\n    try:\n        results = await asyncio.to_thread(_youtube_search_sync, query_text)\n    except Exception as exc:\n        logger.exception(\"Falha na busca de música\")\n        detail = str(exc).replace(\"`\", \"'\")[:650]\n        if \"Sign in to confirm\" in detail or \"not a bot\" in detail.lower():\n            hint = \"O YouTube bloqueou a pesquisa e a fonte alternativa também não respondeu. O bot não usa cookies nem senhas; tente novamente mais tarde ou use um link direto compatível.\"\n        elif \"Unsupported URL\" in detail:\n            hint = \"Esse link não é compatível. Pesquise pelo nome da música e artista.\"\n        else:\n            hint = f\"Detalhe técnico: `{type(exc).__name__}: {detail}`\"\n        return await interaction.followup.send(\n            f\"❌ Não consegui pesquisar a música. {hint}\",\n            ephemeral=True,\n        )\n    if not results:\n        return await interaction.followup.send(\"Não encontrei resultados. Tente outro nome ou artista.\", ephemeral=True)\n\n    # Um cartão por mensagem: capa, dados e botão ficam juntos visualmente.\n    for index, item in enumerate(results[:MUSIC_SEARCH_LIMIT], start=1):\n        embed = discord.Embed(\n            title=f\"{index:02d} • {item['title'][:220]}\",\n            url=item[\"url\"],\n            description=(f\"**Artista/canal:** {item['uploader']}\\n\"\n                         f\"**Duração:** {_duration_label(item['duration'])}\\n\"\n                         \"Selecione o botão abaixo para colocar esta faixa na fila.\"),\n            colour=discord.Colour.from_rgb(22, 126, 220),\n        )\n        if item.get(\"thumbnail\"):\n            # Usar imagem grande no card em vez de miniatura lateral.\n            embed.set_image(url=item[\"thumbnail\"])\n        embed.set_author(name=\"♛ CAOS • CENTRAL DE MÚSICA\")\n        embed.set_footer(text=f\"Resultado {index}/{min(len(results), MUSIC_SEARCH_LIMIT)} • a escolha expira em 4 minutos\")\n        await interaction.followup.send(\n            content=\"🎵 **RESULTADO DA PESQUISA**\" if index == 1 else None,\n            embed=embed,\n            view=MusicSingleResultView(item, interaction.user.id),\n            ephemeral=True,\n        )\n\n\nasync def _set_voice_mode_normal(guild: discord.Guild, channel: discord.VoiceChannel) -> None:\n    \"\"\"Confere mute; só envia atualização ao Gateway se o bot estiver self-muted.\n\n    Não reenviar VOICE_STATE_UPDATE em toda reprodução: o connect()/move_to()\n    já negocia a sessão de voz. Auto-deafen não bloqueia o envio de áudio.\n    \"\"\"\n    bot_member = guild.me or (guild.get_member(bot.user.id) if bot.user else None)\n    state = bot_member.voice if bot_member else None\n    if state and state.mute:\n        raise RuntimeError(\n            \"O CAOS está com mute aplicado pelo servidor. Um administrador precisa remover o silenciamento.\"\n        )\n    if not state or not state.channel or state.channel.id != channel.id:\n        raise RuntimeError(\"O Discord ainda não confirmou a conexão de voz do CAOS. Tente novamente.\")\n\n    # Corrige somente um auto-mute real. Não altera o estado self_deaf.\n    if state.self_mute:\n        await guild.change_voice_state(\n            channel=channel,\n            self_mute=False,\n            self_deaf=state.self_deaf,\n        )\n        for _ in range(12):\n            await asyncio.sleep(0.25)\n            bot_member = guild.me or (guild.get_member(bot.user.id) if bot.user else None)\n            state = bot_member.voice if bot_member else None\n            if state and state.mute:\n                raise RuntimeError(\n                    \"O CAOS está com mute aplicado pelo servidor. Um administrador precisa remover o silenciamento.\"\n                )\n            if state and state.channel and state.channel.id == channel.id and not state.self_mute:\n                return\n        raise RuntimeError(\"O Discord manteve o auto-mute do CAOS. Verifique o estado de voz do bot.\")\n\n\ndef _voice_stack_issue() -> Optional[str]:\n    \"\"\"Retorna um diagnóstico acionável se a pilha DAVE obrigatória estiver ausente.\"\"\"\n    match = re.match(r\"^(\\d+)\\.(\\d+)\\.(\\d+)\", getattr(discord, \"__version__\", \"0.0.0\"))\n    version = tuple(int(part) for part in match.groups()) if match else (0, 0, 0)\n    if version != (2, 7, 1):\n        return (\n            f\"discord.py {getattr(discord, '__version__', 'desconhecido')} não é a versão travada para esta correção. \"\n            \"Este pacote usa discord.py[voice]==2.7.1 junto com davey==0.1.7; execute o INICIAR_CAOS.bat atualizado.\"\n        )\n    if dave_runtime is None:\n        detail = f\" ({type(DAVE_IMPORT_ERROR).__name__}: {DAVE_IMPORT_ERROR})\" if DAVE_IMPORT_ERROR else \"\"\n        return (\n            \"A dependência obrigatória `davey` (criptografia DAVE do Discord) não está carregada\" + detail + \". \"\n            \"Feche o bot e execute o INICIAR_CAOS.bat atualizado para instalar `davey==0.1.7`.\"\n        )\n    # discord.py 2.7.1 ainda não dirige a nova sequência de transição de chaves\n    # introduzida em davey 0.2.0. Essa combinação faz o bot entrar na call,\n    # mas os pacotes de voz não serem decifrados pelos outros participantes.\n    try:\n        from importlib.metadata import version as package_version\n        dave_version = package_version(\"davey\")\n    except Exception as exc:\n        return (\n            \"Não consegui confirmar a versão instalada de `davey` \"\n            f\"({type(exc).__name__}: {exc}). Reinstale `davey==0.1.7`.\"\n        )\n    dave_match = re.match(r\"^(\\d+)\\.(\\d+)\\.(\\d+)\", dave_version)\n    dave_tuple = tuple(int(part) for part in dave_match.groups()) if dave_match else (0, 0, 0)\n    if dave_tuple != (0, 1, 7):\n        return (\n            f\"A versão instalada de `davey` é {dave_version}; para discord.py 2.7.1, \"\n            \"este CAOS exige `davey==0.1.7`. Feche o bot e execute INICIAR_CAOS.bat \"\n            \"atualizado para substituir a versão incompatível.\"\n        )\n    return None\n\n\nasync def _ensure_music_voice(interaction: discord.Interaction):\n    stack_issue = _voice_stack_issue()\n    if stack_issue:\n        return None, f\"❌ O áudio do CAOS não pode iniciar: {stack_issue}\"\n    guild = interaction.guild\n    member = interaction.user\n    if guild is None or not isinstance(member, discord.Member):\n        return None, \"Use a música dentro de um servidor.\"\n    if not member.voice or not member.voice.channel:\n        return None, \"Entre em um canal de voz antes de escolher a música.\"\n    target = member.voice.channel\n    me = guild.me\n    permissions = target.permissions_for(me) if me else None\n    if not permissions or not permissions.connect or not permissions.speak:\n        return None, \"Preciso das permissões **Conectar** e **Falar** nesse canal.\"\n    voice = guild.voice_client\n    bot_member = guild.me\n    if bot_member and bot_member.voice and bot_member.voice.mute:\n        return None, \"O CAOS está silenciado pelo servidor. Um administrador precisa retirar o mute aplicado ao membro do bot.\"\n    try:\n        if voice and voice.is_connected():\n            if voice.channel != target:\n                occupants = [m for m in voice.channel.members if not bot.user or m.id != bot.user.id]\n                if occupants:\n                    return None, \"Já estou tocando em outra call que tem pessoas. Entre na mesma call para usar a música.\"\n                await voice.move_to(target)\n        else:\n            # Importante: entra sem auto-mute E sem auto-deafen.\n            voice = await target.connect(self_mute=False, self_deaf=False)\n\n        # Normaliza também conexões antigas que tenham entrado mutadas/deafened.\n        await _set_voice_mode_normal(guild, target)\n    except discord.Forbidden:\n        return None, \"Não tenho permissão para entrar nessa call. Confira **Conectar** e **Falar**.\"\n    except Exception as exc:\n        logger.exception(\"Falha ao conectar/normalizar a call\")\n        return None, f\"Não consegui liberar o áudio na call: {str(exc)[:220]}\"\n    return voice, None\n\n\nclass _ManagedOpusSource(discord.AudioSource):\n    \"\"\"Entrega somente quadros Opus de áudio ao AudioPlayer do Discord.\n\n    FFmpegOpusAudio lê um fluxo Ogg. Os dois primeiros pacotes são metadados\n    (`OpusHead` e `OpusTags`), não quadros de áudio RTP. Enviá-los como se fossem\n    áudio pode produzir silêncio/decodificação inválida. Eles são descartados\n    aqui; o AudioPlayer recebe apenas quadros Opus reais, em sua thread normal.\n    \"\"\"\n    _OGG_METADATA_PREFIXES = (b\"OpusHead\", b\"OpusTags\")\n\n    def __init__(self, source: discord.AudioSource, temp_dir: Optional[str] = None):\n        self._source = source\n        self._temp_dir = temp_dir\n        self._closed = False\n        self.ogg_headers_skipped = 0\n        self.audio_frames_read = 0\n        self.audio_bytes_read = 0\n\n    def read(self) -> bytes:\n        while True:\n            packet = self._source.read()\n            if not packet:\n                # FFmpegAudio guarda aqui o erro de processo/decodificação. Se houve\n                # falha, transforma EOF silencioso em erro reportável no callback.\n                source_error = getattr(self._source, \"_current_error\", None)\n                if source_error:\n                    raise RuntimeError(f\"FFmpeg falhou durante a reprodução: {source_error}\")\n                return b\"\"\n\n            if packet.startswith(self._OGG_METADATA_PREFIXES):\n                self.ogg_headers_skipped += 1\n                continue\n\n            self.audio_frames_read += 1\n            self.audio_bytes_read += len(packet)\n            return packet\n\n    def is_opus(self) -> bool:\n        return True\n\n    def cleanup(self) -> None:\n        if self._closed:\n            return\n        self._closed = True\n        try:\n            self._source.cleanup()\n        finally:\n            if self._temp_dir:\n                shutil.rmtree(self._temp_dir, ignore_errors=True)\n                self._temp_dir = None\n\n\nasync def _start_next_music(guild: discord.Guild) -> None:\n    lock = MUSIC_LOCKS.setdefault(guild.id, asyncio.Lock())\n    async with lock:\n        voice = guild.voice_client\n        if not voice or not voice.is_connected() or voice.is_playing() or voice.is_paused():\n            return\n        queue = MUSIC_QUEUES.setdefault(guild.id, [])\n        while queue:\n            item = queue.pop(0)\n            temp_dir = None\n            raw_source = None\n            audio_source = None\n            try:\n                # Baixa com yt-dlp para arquivo temporário: evita entregar ao\n                # FFmpeg uma URL assinada/efêmera do YouTube, que vinha retornando\n                # zero pacotes mesmo com FFmpeg, Deno e EJS corretos.\n                download_task = asyncio.create_task(asyncio.to_thread(_download_youtube_audio_sync, item[\"url\"]))\n                try:\n                    info = await asyncio.wait_for(asyncio.shield(download_task), timeout=300)\n                except asyncio.TimeoutError:\n                    # to_thread não interrompe uma transferência já iniciada;\n                    # recolhe a pasta assim que o worker terminar, evitando lixo temporário.\n                    def cleanup_late_download(done_task):\n                        try:\n                            late_result = done_task.result()\n                            late_dir = late_result.get(\"temp_dir\") if isinstance(late_result, dict) else None\n                            if late_dir:\n                                shutil.rmtree(late_dir, ignore_errors=True)\n                        except Exception:\n                            logger.debug(\"Download de áudio terminou após timeout\", exc_info=True)\n                    download_task.add_done_callback(cleanup_late_download)\n                    raise\n                temp_dir = info.pop(\"temp_dir\", None)                local_audio = info.get(\"file_path\")\n                if not local_audio or not Path(local_audio).is_file() or Path(local_audio).stat().st_size <= 0:\n                    raise RuntimeError(\"O download temporário não produziu um arquivo de áudio válido.\")\n\n                ffmpeg_path = _resolve_ffmpeg_executable()\n                volume = max(0.0, min(1.5, float(MUSIC_VOLUME.get(guild.id, 0.80))))\n\n                # O FFmpeg produz áudio Opus (sem vídeo) diretamente. O\n                # VoiceClient envia os pacotes Opus sem depender de uma DLL\n                # libopus instalada no Windows.\n                raw_source = discord.FFmpegOpusAudio(\n                    local_audio,\n                    executable=ffmpeg_path,\n                    bitrate=128,\n                    options=f\"-vn -af volume={volume:.3f}\",\n                )\n                audio_source = _ManagedOpusSource(raw_source, temp_dir=temp_dir)\n                raw_source = None\n                temp_dir = None  # a fonte gerenciada limpa download e processo ao terminar\n\n                def after_playback(error):\n                    async def finish_and_continue():\n                        current = MUSIC_CURRENT.get(guild.id)\n                        if current and current.get(\"id\") == item.get(\"id\"):\n                            MUSIC_CURRENT.pop(guild.id, None)\n                        if error:\n                            logger.warning(\"Erro no player de voz do CAOS: %s\", error, exc_info=error)\n                            failed_channel = guild.get_channel(int(item.get(\"text_channel_id\") or 0))\n                            if isinstance(failed_channel, discord.TextChannel):\n                                try:\n                                    detail = str(error).replace(\"`\", \"'\")[:320]\n                                    await failed_channel.send(\n                                        f\"⚠️ O áudio de **{item.get('title', 'uma faixa')}** foi interrompido. \"\n                                        f\"Detalhe: `{type(error).__name__}: {detail}`. Vou tentar a próxima música da fila.\"\n                                    )\n                                except discord.HTTPException:\n                                    logger.debug(\"Não consegui publicar o erro de reprodução\", exc_info=True)\n                        await _start_next_music(guild)\n                    try:\n                        future = asyncio.run_coroutine_threadsafe(finish_and_continue(), bot.loop)\n                        def consume_result(done):\n                            try:\n                                done.result()\n                            except Exception:\n                                logger.exception(\"Falha ao avançar fila de música\")\n                        future.add_done_callback(consume_result)\n                    except RuntimeError:\n                        logger.debug(\"Loop do CAOS encerrado antes do avanço da fila\")\n\n                try:\n                    voice.play(audio_source, after=after_playback, signal_type=\"music\")\n                except Exception:\n                    audio_source.cleanup()\n                    audio_source = None\n                    raise\n                audio_source = None  # o AudioPlayer agora é dono da fonte e chama cleanup()\n                logger.info(\n                    \"Reprodução de áudio iniciada no Discord: guild=%s canal=%s faixa=%s\",\n                    guild.id, getattr(voice.channel, \"id\", \"desconhecido\"), item.get(\"title\", \"sem título\"),\n                )\n                current = {**item, **info, \"requested_by\": item.get(\"requested_by\"), \"started_at\": utc_now()}\n                current.pop(\"file_path\", None)\n                MUSIC_CURRENT[guild.id] = current\n                channel = guild.get_channel(int(item.get(\"text_channel_id\") or 0))\n                if isinstance(channel, discord.TextChannel):\n                    embed = discord.Embed(\n                        title=\"「🎵」ɴᴏ ᴀʀ • ᴄᴀᴏꜱ ᴍᴜꜱɪᴄ\",\n                        description=f\"**[{info['title']}]({info.get('webpage_url') or item['url']})**\\nSolicitada por <@{item.get('requested_by')}>\",\n                        colour=discord.Colour.from_rgb(22, 126, 220),\n                    )\n                    if info.get(\"thumbnail\"):\n                        embed.set_thumbnail(url=info[\"thumbnail\"])\n                    embed.add_field(name=\"Duração\", value=_duration_label(info.get(\"duration\")), inline=True)\n                    embed.add_field(name=\"Volume\", value=f\"{int(volume * 100)}%\", inline=True)\n                    embed.set_footer(text=\"「 CAOS 」 • use os controles do painel de música\")\n                    try:\n                        await channel.send(embed=embed)\n                    except discord.HTTPException:\n                        logger.debug(\"Não consegui publicar o aviso de faixa atual\", exc_info=True)\n                return\n            except asyncio.TimeoutError:\n                logger.exception(\"Timeout ao baixar áudio do YouTube\")\n                if audio_source:\n                    audio_source.cleanup()\n                if raw_source:\n                    raw_source.cleanup()\n                if temp_dir:\n                    shutil.rmtree(temp_dir, ignore_errors=True)\n                channel = guild.get_channel(int(item.get(\"text_channel_id\") or 0))\n                if isinstance(channel, discord.TextChannel):\n                    try:\n                        await channel.send(\n                            f\"⚠️ O download de **{item.get('title', 'a faixa')}** demorou mais de 5 minutos. \"\n                            \"A faixa foi pulada; tente novamente ou escolha outra versão.\"\n                        )\n                    except discord.HTTPException:\n                        pass\n            except Exception as exc:\n                if audio_source:\n                    audio_source.cleanup()\n                if raw_source:\n                    raw_source.cleanup()\n                if temp_dir:\n                    shutil.rmtree(temp_dir, ignore_errors=True)\n                logger.exception(\"Falha ao iniciar faixa da fila\")\n                channel = guild.get_channel(int(item.get(\"text_channel_id\") or 0))\n                if isinstance(channel, discord.TextChannel):\n                    try:\n                        detail = str(exc).replace(\"`\", \"'\")[:350]\n                        await channel.send(\n                            f\"⚠️ Não consegui tocar **{item.get('title', 'a faixa')}**. \"\n                            f\"Erro: `{type(exc).__name__}: {detail}`. Vou tentar a próxima música da fila.\"\n                        )\n                    except discord.HTTPException:\n                        pass\n        MUSIC_CURRENT.pop(guild.id, None)\n\n\nasync def _enqueue_music(interaction: discord.Interaction, item: dict) -> None:\n    if not interaction.response.is_done():\n        await interaction.response.defer(ephemeral=True, thinking=True)\n    voice, error = await _ensure_music_voice(interaction)\n    if error:\n        return await interaction.followup.send(error, ephemeral=True)\n    queue = MUSIC_QUEUES.setdefault(interaction.guild_id, [])\n    if len(queue) >= MUSIC_QUEUE_LIMIT:\n        return await interaction.followup.send(f\"A fila já atingiu o limite de {MUSIC_QUEUE_LIMIT} músicas.\", ephemeral=True)\n    queued = {\n        **item,\n        \"requested_by\": interaction.user.id,\n        \"text_channel_id\": interaction.channel_id,\n    }\n    was_idle = not voice.is_playing() and not voice.is_paused() and not queue\n    queue.append(queued)\n    await _start_next_music(interaction.guild)\n    current = MUSIC_CURRENT.get(interaction.guild_id) or {}\n    if current.get(\"id\") == item.get(\"id\"):\n        message = f\"▶️ Começando agora: **{item['title']}**.\"\n    else:\n        queued_ids = [entry.get(\"id\") for entry in MUSIC_QUEUES.get(interaction.guild_id, [])]\n        if item.get(\"id\") in queued_ids:\n            position = queued_ids.index(item.get(\"id\")) + 1\n            if voice.is_playing() or voice.is_paused():\n                position += 1\n            message = f\"➕ Adicionada à fila na posição **{position}**: **{item['title']}**.\"\n        else:\n            message = (f\"⚠️ Não consegui iniciar **{item['title']}**. \"\n                       \"Confira a mensagem de erro publicada no canal e execute `/diagnostico_audio`.\")\n    await interaction.followup.send(message, ephemeral=True)\n\n\nasync def _music_control_check(interaction: discord.Interaction):\n    guild = interaction.guild\n    member = interaction.user\n    if guild is None or not isinstance(member, discord.Member) or not member.voice or not member.voice.channel:\n        await interaction.response.send_message(\"Entre na mesma call do CAOS para controlar a música.\", ephemeral=True)\n        return None\n    voice = guild.voice_client\n    if not voice or not voice.is_connected() or voice.channel != member.voice.channel:\n        await interaction.response.send_message(\"Você precisa estar na mesma call que o CAOS.\", ephemeral=True)\n        return None\n    return voice\n\n\nasync def _pause_resume(interaction: discord.Interaction):\n    voice = await _music_control_check(interaction)\n    if voice is None:\n        return\n    if voice.is_playing():\n        voice.pause()\n        text = \"⏸️ Música pausada.\"\n    elif voice.is_paused():\n        voice.resume()\n        text = \"▶️ Música retomada.\"\n    else:\n        text = \"Não há música tocando neste momento.\"\n    await interaction.response.send_message(text, ephemeral=True)\n\n\nasync def _skip_music(interaction: discord.Interaction):\n    voice = await _music_control_check(interaction)\n    if voice is None:\n        return\n    if not (voice.is_playing() or voice.is_paused()):\n        return await interaction.response.send_message(\"Não há faixa para pular.\", ephemeral=True)\n    voice.stop()\n    await interaction.response.send_message(\"⏭️ Faixa pulada. A próxima música da fila vai começar.\", ephemeral=True)\n\n\nasync def _stop_music(interaction: discord.Interaction):\n    voice = await _music_control_check(interaction)\n    if voice is None:\n        return\n    MUSIC_QUEUES[interaction.guild_id] = []\n    MUSIC_CURRENT.pop(interaction.guild_id, None)\n    if voice.is_playing() or voice.is_paused():\n        voice.stop()\n    await interaction.response.send_message(\"⏹️ Reprodução parada e fila limpa.\", ephemeral=True)\n\n\nasync def _show_music_queue(interaction: discord.Interaction):\n    voice = await _music_control_check(interaction)\n    if voice is None:\n        return\n    current = MUSIC_CURRENT.get(interaction.guild_id)\n    queue = MUSIC_QUEUES.get(interaction.guild_id, [])\n    lines = []\n    if current:\n        lines.append(f\"**Tocando:** {current.get('title', 'Faixa desconhecida')}\")\n    if queue:\n        lines.append(\"\\n**Próximas:**\")\n        lines.extend(f\"{index}. {item['title']} — pedido por <@{item['requested_by']}>\" for index, item in enumerate(queue[:15], 1))\n        if len(queue) > 15:\n            lines.append(f\"… e mais {len(queue) - 15} músicas\")\n    embed = discord.Embed(\n        title=\"「🎶」ꜰɪʟᴀ ᴅᴇ ᴍúꜱɪᴄᴀ\",\n        description=\"\\n\".join(lines) or \"A fila está vazia.\",\n        colour=discord.Colour.from_rgb(22, 126, 220),\n    )\n    await interaction.response.send_message(embed=embed, ephemeral=True)\n\n\nclass MusicSearchModal(discord.ui.Modal, title=\"🎵 ᴘᴇꜱǫᴜɪꜱᴀʀ ᴍúꜱɪᴄᴀ\"):\n    search = discord.ui.TextInput(\n        label=\"Nome da música ou artista\",\n        placeholder=\"Ex.: nome da faixa • artista\",\n        max_length=100,\n    )\n\n    async def on_submit(self, interaction: discord.Interaction):\n        await _music_search_response(interaction, self.search.value)\n\n\nclass MusicSingleResultView(discord.ui.View):\n    \"\"\"Um botão sob cada capa, vinculado à música exata daquele cartão.\"\"\"\n    def __init__(self, item: dict, requester_id: int):\n        super().__init__(timeout=240)\n        self.item = item\n        self.requester_id = requester_id\n\n    @discord.ui.button(label=\"TOCAR AGORA\", emoji=\"▶️\", style=discord.ButtonStyle.success)\n    async def play_selected(self, interaction: discord.Interaction, button: discord.ui.Button):\n        if interaction.user.id != self.requester_id:\n            return await interaction.response.send_message(\n                \"Só quem fez a pesquisa pode escolher esse resultado.\", ephemeral=True\n            )\n        await _enqueue_music(interaction, self.item)\n\n\nclass MusicPanelView(discord.ui.View):\n    def __init__(self):\n        super().__init__(timeout=None)\n\n    @discord.ui.button(label=\"ᴘᴇꜱǫᴜɪꜱᴀʀ ᴍúꜱɪᴄᴀ\", emoji=\"🔎\", style=discord.ButtonStyle.danger, custom_id=\"caos:music:search\")\n    async def search(self, interaction: discord.Interaction, button: discord.ui.Button):\n        await interaction.response.send_modal(MusicSearchModal())\n\n    @discord.ui.button(label=\"ᴘᴀᴜꜱᴀʀ / ʀᴇᴛᴏᴍᴀʀ\", emoji=\"⏯️\", style=discord.ButtonStyle.secondary, custom_id=\"caos:music:pause\")\n    async def pause(self, interaction: discord.Interaction, button: discord.ui.Button):\n        await _pause_resume(interaction)\n\n    @discord.ui.button(label=\"ᴘᴜʟᴀʀ\", emoji=\"⏭️\", style=discord.ButtonStyle.secondary, custom_id=\"caos:music:skip\")\n    async def skip(self, interaction: discord.Interaction, button: discord.ui.Button):\n        await _skip_music(interaction)\n\n    @discord.ui.button(label=\"ᴠᴇʀ ꜰɪʟᴀ\", emoji=\"📜\", style=discord.ButtonStyle.secondary, custom_id=\"caos:music:queue\")\n    async def queue(self, interaction: discord.Interaction, button: discord.ui.Button):\n        await _show_music_queue(interaction)\n\n    @discord.ui.button(label=\"ᴘᴀʀᴀʀ\", emoji=\"⏹️\", style=discord.ButtonStyle.danger, custom_id=\"caos:music:stop\")\n    async def stop(self, interaction: discord.Interaction, button: discord.ui.Button):\n        await _stop_music(interaction)\n\n\n# ---------------------------------------------------------------------------\n# Recrutamento, ponto automático, promoções semanais e ADV\n# ---------------------------------------------------------------------------\n\ntry:\n    BAHIA_TZ = ZoneInfo(\"America/Bahia\")\nexcept Exception:\n    BAHIA_TZ = timezone(timedelta(hours=-3))\n\nPROMOTION_ROLE_KEYS = (\n    \"promotion_olheiro_role_id\",\n    \"promotion_aviao_role_id\",\n    \"promotion_vapor_role_id\",\n    \"promotion_traficante_role_id\",\n)\nPROMOTION_ROLE_NAMES = (\n    \"「👺」Olheiro\",\n    \"「👺」Aviãozinho\",\n    \"「👺」Vapor\",\n    \"「👺」Traficante\",\n)\nPOINT_REMINDER_SECONDS = 3 * 60 * 60\nPOINT_CONFIRM_GRACE_SECONDS = 3 * 60\nWEEKLY_POINT_GOAL_SECONDS = 5 * 60 * 60\nADV_GRACE_DAYS = 5\n\n\ndef _aware_utc(value: str | datetime) -> datetime:\n    dt = parse_dt(value) if isinstance(value, str) else value\n    if dt.tzinfo is None:\n        return dt.replace(tzinfo=timezone.utc)\n    return dt.astimezone(timezone.utc)\n\n\ndef current_week_bounds(now: Optional[datetime] = None) -> tuple[datetime, datetime]:\n    local = (now or datetime.now(timezone.utc)).astimezone(BAHIA_TZ)\n    start = local.replace(hour=0, minute=0, second=0, microsecond=0) - timedelta(days=local.weekday())\n    end = start + timedelta(days=7)\n    return start.astimezone(timezone.utc), end.astimezone(timezone.utc)\n\n\ndef seconds_worked_in_window(guild_id: int, user_id: int, start: datetime, end: datetime) -> int:\n    \"\"\"Soma somente a interseção das sessões com a semana consultada.\"\"\"\n    total = 0\n    with db() as con:\n        rows = con.execute(\n            \"SELECT started_at, ended_at FROM point_sessions WHERE guild_id=? AND user_id=?\",\n            (guild_id, user_id),\n        ).fetchall()\n        active = con.execute(\n            \"SELECT started_at FROM active_points WHERE guild_id=? AND user_id=?\",\n            (guild_id, user_id),\n        ).fetchone()\n    for row in rows:\n        a, b = _aware_utc(row[\"started_at\"]), _aware_utc(row[\"ended_at\"])\n        total += max(0, int((min(b, end) - max(a, start)).total_seconds()))\n    if active:\n        a = _aware_utc(active[\"started_at\"])\n        total += max(0, int((min(datetime.now(timezone.utc), end) - max(a, start)).total_seconds()))\n    return total\n\n\ndef analyze_ai_signals(answers: list[dict]) -> list[str]:\n    \"\"\"Triagem textual simples; nunca comprova autoria por IA.\"\"\"\n    texts = [str(item.get(\"answer\", \"\")).strip() for item in answers if item.get(\"answer\")]\n    reasons: list[str] = []\n    all_text = \"\\n\".join(texts).lower()\n    explicit_patterns = (\n        \"como modelo de linguagem\", \"sou uma inteligência artificial\",\n        \"aqui está uma resposta\", \"espero que esta resposta\",\n        \"posso ajudar com mais alguma coisa\",\n    )\n    found = [phrase for phrase in explicit_patterns if phrase in all_text]\n    if found:\n        reasons.append(\"Foram encontradas expressões típicas de resposta de assistente textual.\")\n    openings: dict[str, int] = {}\n    for value in texts:\n        words = re.findall(r\"[a-záàâãéêíóôõúç0-9]+\", value.lower())\n        if len(words) >= 8:\n            key = \" \".join(words[:8])\n            openings[key] = openings.get(key, 0) + 1\n    if any(count >= 3 for count in openings.values()):\n        reasons.append(\"Três ou mais respostas repetem a mesma estrutura inicial.\")\n    duplicate_found = False\n    normalized = [re.sub(r\"\\s+\", \" \", value.lower()) for value in texts]\n    for i in range(len(normalized)):\n        for j in range(i + 1, len(normalized)):\n            if len(normalized[i]) > 100 and len(normalized[j]) > 100:\n                if SequenceMatcher(None, normalized[i], normalized[j]).ratio() >= 0.90:\n                    duplicate_found = True\n                    break\n        if duplicate_found:\n            break\n    if duplicate_found:\n        reasons.append(\"Duas respostas apresentam semelhança textual muito alta.\")\n    template_phrases = (\"é importante destacar\", \"vale ressaltar\", \"em suma\", \"em conclusão\")\n    template_hits = sum(all_text.count(phrase) for phrase in template_phrases)\n    if template_hits >= 5:\n        reasons.append(\"Há repetição elevada de expressões genéricas e padronizadas.\")\n    return reasons\n\n\nasync def start_point_for_member(\n    guild: discord.Guild, member: discord.Member, channel_id: Optional[int] = None,\n    *, send_dm: bool = True, reason: str = \"Entrada na call monitorada\",\n) -> bool:\n    if member.bot:\n        return False\n    now = utc_now()\n    with db() as con:\n        existing = con.execute(\n            \"SELECT 1 FROM active_points WHERE guild_id=? AND user_id=?\", (guild.id, member.id)\n        ).fetchone()\n        if existing:\n            return False\n        con.execute(\n            \"INSERT INTO active_points(guild_id,user_id,started_at) VALUES(?,?,?)\",\n            (guild.id, member.id, now),\n        )\n        con.execute(\n            \"INSERT OR REPLACE INTO point_presence(guild_id,user_id,channel_id,last_confirmed_at,pending_since) VALUES(?,?,?,?,NULL)\",\n            (guild.id, member.id, int(channel_id or (member.voice.channel.id if member.voice and member.voice.channel else 0)), now),\n        )\n    online = await get_role(guild, \"role_online_id\")\n    offline = await get_role(guild, \"role_offline_id\")\n    try:\n        if offline and offline in member.roles:\n            await member.remove_roles(offline, reason=reason)\n        if online and online not in member.roles:\n            await member.add_roles(online, reason=reason)\n    except discord.Forbidden:\n        logger.warning(\"Ponto iniciado, mas não foi possível atualizar cargos de %s\", member.id)\n    if send_dm:\n        try:\n            await member.send(\n                embed=discord.Embed(\n                    title=\"🟢 Bate-ponto iniciado automaticamente\",\n                    description=(\"Seu ponto começou quando você entrou na call monitorada. \"\n                                 \"O tempo está sendo contado em tempo real. Você receberá uma confirmação a cada 3 horas.\"),\n                    colour=discord.Colour.green(),\n                    timestamp=discord.utils.utcnow(),\n                )\n            )\n        except discord.Forbidden:\n            logger.info(\"Não foi possível enviar DM de início de ponto para %s\", member.id)\n    await notify_staff(guild, f\"🟢 Ponto iniciado automaticamente: {member.mention} entrou na call monitorada.\")\n    return True\n\n\nasync def stop_point_for_member(\n    guild: discord.Guild, member: discord.Member, *, reason: str = \"Saída da call monitorada\",\n    send_dm: bool = True,\n) -> Optional[int]:\n    with db() as con:\n        active = con.execute(\n            \"SELECT started_at FROM active_points WHERE guild_id=? AND user_id=?\", (guild.id, member.id)\n        ).fetchone()\n    if not active:\n        return None\n    ended = datetime.now(timezone.utc)\n    started = _aware_utc(active[\"started_at\"])\n    duration = max(0, int((ended - started).total_seconds()))\n    with db() as con:\n        con.execute(\n            \"INSERT INTO point_sessions(guild_id,user_id,started_at,ended_at,duration_seconds) VALUES(?,?,?,?,?)\",\n            (guild.id, member.id, active[\"started_at\"], ended.isoformat(), duration),\n        )\n        con.execute(\"DELETE FROM active_points WHERE guild_id=? AND user_id=?\", (guild.id, member.id))\n        con.execute(\"DELETE FROM point_presence WHERE guild_id=? AND user_id=?\", (guild.id, member.id))\n    online = await get_role(guild, \"role_online_id\")\n    offline = await get_role(guild, \"role_offline_id\")\n    try:\n        if online and online in member.roles:\n            await member.remove_roles(online, reason=reason)\n        if offline and offline not in member.roles:\n            await member.add_roles(offline, reason=reason)\n    except discord.Forbidden:\n        logger.warning(\"Ponto encerrado, mas não foi possível atualizar cargos de %s\", member.id)\n    if send_dm:\n        try:\n            await member.send(\n                embed=discord.Embed(\n                    title=\"🔴 Bate-ponto encerrado\",\n                    description=f\"Seu ponto foi encerrado automaticamente.\\nTempo desta sessão: **{format_duration(duration)}**.\",\n                    colour=discord.Colour.red(), timestamp=discord.utils.utcnow(),\n                )\n            )\n        except discord.Forbidden:\n            logger.info(\"Não foi possível enviar DM de encerramento para %s\", member.id)\n    await notify_staff(guild, f\"🔴 Ponto encerrado: {member.mention} — **{format_duration(duration)}**. Motivo: {reason}.\")\n    return duration\n\n\nclass PointPresenceConfirmView(discord.ui.View):\n    def __init__(self):\n        super().__init__(timeout=None)\n\n    @discord.ui.button(\n        label=\"Sim, estou aqui!\", emoji=\"✅\", style=discord.ButtonStyle.success,\n        custom_id=\"caos:point:presence_confirm\",\n    )\n    async def confirm(self, interaction: discord.Interaction, button: discord.ui.Button):\n        with db() as con:\n            row = con.execute(\n                \"SELECT guild_id, pending_since FROM point_presence WHERE user_id=? AND pending_since IS NOT NULL ORDER BY pending_since DESC LIMIT 1\",\n                (interaction.user.id,),\n            ).fetchone()\n        if not row:\n            return await interaction.response.send_message(\n                \"Não há uma confirmação de presença pendente para você.\", ephemeral=True\n            )\n        pending = _aware_utc(row[\"pending_since\"])\n        if (datetime.now(timezone.utc) - pending).total_seconds() > POINT_CONFIRM_GRACE_SECONDS:\n            return await interaction.response.send_message(\n                \"O prazo de 3 minutos terminou. O ponto está sendo encerrado; entre novamente na call monitorada para iniciar outro.\",\n                ephemeral=True,\n            )\n        now = utc_now()\n        with db() as con:\n            con.execute(\n                \"UPDATE point_presence SET last_confirmed_at=?, pending_since=NULL WHERE guild_id=? AND user_id=?\",\n                (now, int(row[\"guild_id\"]), interaction.user.id),\n            )\n        await interaction.response.send_message(\n            \"✅ Presença confirmada! Seu ponto continua ativo. O próximo lembrete será em 3 horas.\",\n            ephemeral=True,\n        )\n\n\ndef extract_recruitment_identity(answers_json: str) -> tuple[str, str]:\n    \"\"\"Extrai ID do jogo e nome das perguntas finais do recrutamento.\n\n    Usa os índices 22/23 do questionário atual e, como compatibilidade,\n    procura os rótulos das perguntas caso o formato da lista tenha mudado.\n    Retorna (game_id, game_name) normalizados.\n    \"\"\"\n    try:\n        answers = json.loads(answers_json) if isinstance(answers_json, str) else answers_json\n    except (TypeError, ValueError, json.JSONDecodeError):\n        answers = []\n\n    game_id = \"\"\n    game_name = \"\"\n    if isinstance(answers, list):\n        # Questionário atual: pergunta 22 = ID no jogo; pergunta 23 = nome.\n        if len(answers) >= 23:\n            id_item = answers[21] if isinstance(answers[21], dict) else {}\n            name_item = answers[22] if isinstance(answers[22], dict) else {}\n            game_id = str(id_item.get(\"answer\", \"\")).strip()\n            game_name = str(name_item.get(\"answer\", \"\")).strip()\n\n        # Compatibilidade com respostas salvas em outra ordem/versão.\n        if not game_id or not game_name:\n            for item in answers:\n                if not isinstance(item, dict):\n                    continue\n                question = str(item.get(\"question\", \"\")).casefold()\n                answer = str(item.get(\"answer\", \"\")).strip()\n                if not answer:\n                    continue\n                if not game_id and \"id no jogo\" in question:\n                    game_id = answer\n                elif not game_name and \"qual é o seu nome\" in question:\n                    game_name = answer\n\n    game_id = re.sub(r\"\\s+\", \" \", game_id).strip()\n    game_name = re.sub(r\"\\s+\", \" \", game_name).strip()\n    # Nomes/IDs não devem conter novas linhas nem menções que possam notificar cargos.\n    game_id = discord.utils.escape_mentions(game_id)\n    game_name = discord.utils.escape_mentions(game_name)\n    return game_id, game_name\n\n\ndef build_recruitment_nickname(game_name: str, game_id: str) -> str:\n    \"\"\"Monta o formato pedido sem ultrapassar o limite de 32 caracteres do Discord.\"\"\"\n    prefix = \"EQP.C |• \"\n    game_id = str(game_id).strip()\n    game_name = re.sub(r\"\\s+\", \" \", str(game_name)).strip()\n    # Preserva o ID completo em casos normais e reserva ao menos um caractere para nome.\n    max_id_length = max(1, 32 - len(prefix) - len(\" 「」\") - 1)\n    game_id = game_id[:max_id_length]\n    suffix = f\" 「{game_id}」\"\n    available_name_length = 32 - len(prefix) - len(suffix)\n    if available_name_length < 1:\n        raise ValueError(\"O ID informado é longo demais para o apelido do Discord.\")\n    game_name = game_name[:available_name_length]\n    if not game_name or not game_id:\n        raise ValueError(\"Nome e ID do jogo são obrigatórios para montar o apelido.\")\n    return f\"{prefix}{game_name}{suffix}\"\n\n\nclass RecruitmentReviewView(discord.ui.View):\n    def __init__(self):\n        super().__init__(timeout=None)\n\n    async def _review(self, interaction: discord.Interaction, approved: bool):\n        guild, channel, reviewer = interaction.guild, interaction.channel, interaction.user\n        if guild is None or not isinstance(channel, discord.TextChannel) or not isinstance(reviewer, discord.Member):\n            return await interaction.response.send_message(\"Use este botão no canal de recrutamento.\", ephemeral=True)\n        if not is_recruiter(reviewer, guild):\n            return await interaction.response.send_message(\n                \"⛔ Apenas o cargo **[REC-OFC] Recrutador oficial** ou um administrador pode decidir este recrutamento.\",\n                ephemeral=True,\n            )\n        with db() as con:\n            recruitment = con.execute(\n                \"SELECT * FROM recruitments WHERE guild_id=? AND channel_id=? ORDER BY id DESC LIMIT 1\",\n                (guild.id, channel.id),\n            ).fetchone()\n        if not recruitment:\n            return await interaction.response.send_message(\"Não encontrei uma inscrição vinculada a este canal.\", ephemeral=True)\n        if recruitment[\"status\"] in {\"aprovado\", \"reprovado\"}:\n            return await interaction.response.send_message(f\"Este candidato já foi {recruitment['status']}.\", ephemeral=True)\n\n        applicant = guild.get_member(int(recruitment[\"user_id\"]))\n        if applicant is None:\n            try:\n                applicant = await guild.fetch_member(int(recruitment[\"user_id\"]))\n            except (discord.NotFound, discord.HTTPException):\n                applicant = None\n\n        assigned_role = None\n        nickname_applied = False\n        new_nick = None\n\n        if approved:\n            if applicant is None:\n                return await interaction.response.send_message(\n                    \"Não consegui encontrar o candidato no servidor. Ele precisa estar no servidor para concluir a aprovação.\",\n                    ephemeral=True,\n                )\n\n            # Pré-valida os dados antes de alterar cargos/apelido.\n            game_id, game_name = extract_recruitment_identity(recruitment[\"answers_json\"])\n            if not game_id or not game_name:\n                return await interaction.response.send_message(\n                    \"Não consegui localizar o ID do jogo e o nome nas respostas 22 e 23. \"\n                    \"Peça ao candidato para confirmar esses dois dados no canal antes de aprovar.\",\n                    ephemeral=True,\n                )\n            try:\n                new_nick = build_recruitment_nickname(game_name, game_id)\n            except ValueError as exc:\n                return await interaction.response.send_message(f\"Não consegui montar o apelido: {exc}\", ephemeral=True)\n\n            me = guild.me or (guild.get_member(bot.user.id) if bot.user else None)\n            if me is None:\n                return await interaction.response.send_message(\n                    \"Não consegui verificar as permissões do bot. Tente novamente após o bot reconectar.\",\n                    ephemeral=True,\n                )\n            if not me.guild_permissions.manage_nicknames:\n                return await interaction.response.send_message(\n                    \"⚠️ Não aprovei ainda: falta ao bot a permissão **Gerenciar apelidos**. \"\n                    \"Ative essa permissão no cargo do CAOS e tente novamente.\",\n                    ephemeral=True,\n                )\n            if me.top_role <= applicant.top_role:\n                return await interaction.response.send_message(\n                    \"⚠️ Não aprovei ainda: o cargo mais alto do CAOS precisa ficar acima do cargo mais alto do candidato. \"\n                    \"Mova o cargo do bot para cima na hierarquia do servidor e tente novamente.\",\n                    ephemeral=True,\n                )\n\n            role_id = config_get(guild.id, \"recruitment_approved_role_id\")\n            role = guild.get_role(int(role_id)) if role_id and str(role_id).isdigit() else None\n            if role is None:\n                return await interaction.response.send_message(\n                    \"⚠️ O cargo de aprovado ainda não foi configurado. Um administrador deve executar \"\n                    \"`/configurar_cargo_aprovado` antes de aprovar candidatos.\",\n                    ephemeral=True,\n                )\n            if not me.guild_permissions.manage_roles or me.top_role <= role:\n                return await interaction.response.send_message(\n                    \"⚠️ Não aprovei ainda: falta **Gerenciar cargos** ou o cargo do CAOS está abaixo do cargo de aprovado. \"\n                    \"Ajuste a permissão/hierarquia e tente novamente.\",\n                    ephemeral=True,\n                )\n\n            # Primeiro confirma as permissões; depois aplica o cargo e o apelido.\n            # Se uma etapa falhar, desfaz o cargo recém-adicionado e mantém a inscrição pendente.\n            role_was_added = False\n            try:\n                if role not in applicant.roles:\n                    await applicant.add_roles(role, reason=f\"Recrutamento aprovado por {reviewer}\")\n                    assigned_role = role\n                    role_was_added = True\n                else:\n                    assigned_role = role\n                await applicant.edit(nick=new_nick, reason=f\"Identificação FAC após aprovação por {reviewer}\")\n                nickname_applied = True\n            except discord.Forbidden:\n                if role_was_added:\n                    try:\n                        await applicant.remove_roles(role, reason=\"Reversão: falha ao atualizar apelido no recrutamento\")\n                    except discord.HTTPException:\n                        logger.exception(\"Falha ao reverter cargo após erro de apelido\")\n                return await interaction.response.send_message(\n                    \"⚠️ O Discord recusou a alteração. Confira **Gerenciar cargos**, **Gerenciar apelidos** e se o cargo do CAOS está acima do candidato e do cargo de aprovado. A inscrição continua pendente.\",\n                    ephemeral=True,\n                )\n            except discord.HTTPException as exc:\n                if role_was_added:\n                    try:\n                        await applicant.remove_roles(role, reason=\"Reversão: falha ao atualizar apelido no recrutamento\")\n                    except discord.HTTPException:\n                        logger.exception(\"Falha ao reverter cargo após erro HTTP no apelido\")\n                logger.warning(\"Falha ao aprovar/atualizar candidato %s: %s\", applicant.id, exc, exc_info=True)\n                return await interaction.response.send_message(\n                    f\"⚠️ O Discord não concluiu a aprovação ({type(exc).__name__}). A inscrição continua pendente; tente novamente após verificar as permissões.\",\n                    ephemeral=True,\n                )\n\n        status = \"aprovado\" if approved else \"reprovado\"\n        with db() as con:\n            con.execute(\n                \"UPDATE recruitments SET status=?, reviewed_by=? WHERE id=?\",\n                (status, reviewer.id, int(recruitment[\"id\"])),\n            )\n\n        result = \"✅ Candidato aprovado!\" if approved else \"❌ Candidato reprovado.\"\n        if applicant:\n            try:\n                dm_text = f\"{result} Sua inscrição na FAC foi analisada por um superior.\"\n                if approved and assigned_role:\n                    dm_text += f\" Cargo atribuído: {assigned_role.name}.\"\n                if approved and nickname_applied and new_nick:\n                    dm_text += f\" Seu apelido foi atualizado para: `{new_nick}`.\"\n                await applicant.send(dm_text)\n            except discord.Forbidden:\n                pass\n\n        for child in self.children:\n            child.disabled = True\n        try:\n            await interaction.message.edit(view=self)\n        except discord.HTTPException:\n            pass\n        await interaction.response.send_message(result, ephemeral=True)\n        await notify_staff(guild, f\"📋 Recrutamento de <@{int(recruitment['user_id'])}> **{status}** por {reviewer.mention}.\")\n\n    @discord.ui.button(label=\"Aprovado\", emoji=\"✅\", style=discord.ButtonStyle.success, custom_id=\"caos:recruitment:approve\")\n    async def approve(self, interaction: discord.Interaction, button: discord.ui.Button):\n        await self._review(interaction, True)\n\n    @discord.ui.button(label=\"Reprovado\", emoji=\"❌\", style=discord.ButtonStyle.danger, custom_id=\"caos:recruitment:reject\")\n    async def reject(self, interaction: discord.Interaction, button: discord.ui.Button):\n        await self._review(interaction, False)\n\n\nclass GoalSubmissionReviewView(discord.ui.View):\n    def __init__(self):\n        super().__init__(timeout=None)\n\n    async def _decide(self, interaction: discord.Interaction, accept: bool):\n        guild, channel, reviewer = interaction.guild, interaction.channel, interaction.user\n        if guild is None or not isinstance(channel, discord.TextChannel) or not isinstance(reviewer, discord.Member):\n            return await interaction.response.send_message(\"Use este botão dentro do canal de entrega de meta.\", ephemeral=True)\n        room = room_get(channel.id)\n        if not room or room[\"kind\"] != \"goal\" or room[\"status\"] != \"open\":\n            return await interaction.response.send_message(\"Este canal não é uma entrega de meta aberta.\", ephemeral=True)\n        if not is_staff_reviewer(reviewer, guild):\n            return await interaction.response.send_message(\"Somente a equipe responsável pode avaliar esta entrega.\", ephemeral=True)\n        with db() as con:\n            goal = con.execute(\n                \"SELECT * FROM goals WHERE guild_id=? AND channel_id=? ORDER BY id DESC LIMIT 1\",\n                (guild.id, channel.id),\n            ).fetchone()\n        if not goal or goal[\"status\"] not in {\"enviada\", \"aguardando_imagem\"}:\n            return await interaction.response.send_message(\"Esta entrega já foi avaliada ou não foi encontrada.\", ephemeral=True)\n        user_id = int(goal[\"user_id\"])\n        with db() as con:\n            if accept:\n                con.execute(\"UPDATE goals SET status='aprovada' WHERE id=?\", (int(goal[\"id\"]),))\n                state = con.execute(\n                    \"SELECT adv_count,ticket_channel_id FROM adv_state WHERE guild_id=? AND user_id=?\",\n                    (guild.id, user_id),\n                ).fetchone()\n                con.execute(\n                    \"UPDATE goal_obligations SET status='regularizada' WHERE guild_id=? AND user_id=? AND status IN ('pendente','em_adv','em_analise')\",\n                    (guild.id, user_id),\n                )\n                con.execute(\n                    \"INSERT INTO adv_state(guild_id,user_id,adv_count,last_adv_at,next_adv_at,source_week_start,ticket_channel_id) VALUES(?,?,0,NULL,NULL,NULL,NULL) \"\n                    \"ON CONFLICT(guild_id,user_id) DO UPDATE SET adv_count=0,last_adv_at=NULL,next_adv_at=NULL,source_week_start=NULL,ticket_channel_id=NULL\",\n                    (guild.id, user_id),\n                )\n                if state and int(state[\"adv_count\"] or 0) > 0:\n                    con.execute(\n                        \"INSERT INTO adv_events(guild_id,user_id,actor_id,adv_count,event_type,note,created_at) VALUES(?,?,?,?,?,?,?)\",\n                        (guild.id, user_id, reviewer.id, 0, \"regularizado\", \"Entrega de meta aprovada por superior\", utc_now()),\n                    )\n            else:\n                con.execute(\"UPDATE goals SET status='rejeitada' WHERE id=?\", (int(goal[\"id\"]),))\n                con.execute(\n                    \"UPDATE goal_obligations SET status=CASE WHEN EXISTS(SELECT 1 FROM adv_state a WHERE a.guild_id=? AND a.user_id=? AND a.adv_count>0) THEN 'em_adv' ELSE 'pendente' END WHERE guild_id=? AND user_id=? AND status='em_analise'\",\n                    (guild.id, user_id, guild.id, user_id),\n                )\n        member = guild.get_member(user_id)\n        if member is None:\n            try:\n                member = await guild.fetch_member(user_id)\n            except discord.NotFound:\n                member = None\n        if member:\n            try:\n                await member.send(\n                    \"✅ Sua entrega de meta foi aprovada. Sua cobrança foi regularizada e todas as ADVs foram zeradas (0/3).\" if accept\n                    else \"⚠️ Sua entrega de meta não foi aprovada. Confira as orientações da equipe e envie uma nova comprovação.\"\n                )\n            except discord.Forbidden:\n                pass\n        for child in self.children:\n            child.disabled = True\n        try:\n            await interaction.message.edit(view=self)\n        except discord.HTTPException:\n            pass\n        if accept:\n            await interaction.response.send_message(\n                f\"✅ Entrega aprovada por {reviewer.mention}. A cobrança foi regularizada e as ADVs do membro foram zeradas (0/3).\",\n                ephemeral=False,\n            )\n        else:\n            await interaction.response.send_message(\n                f\"❌ Entrega reprovada por {reviewer.mention}. A meta continua pendente para correção.\",\n                ephemeral=False,\n            )\n        await notify_staff(guild, f\"🎯 Entrega de meta de <@{user_id}> {'aprovada' if accept else 'reprovada'} por {reviewer.mention}.\")\n\n    @discord.ui.button(label=\"Aprovar entrega\", emoji=\"✅\", style=discord.ButtonStyle.success, custom_id=\"caos:goal:approve\")\n    async def approve(self, interaction: discord.Interaction, button: discord.ui.Button):\n        await self._decide(interaction, True)\n\n    @discord.ui.button(label=\"Reprovar entrega\", emoji=\"❌\", style=discord.ButtonStyle.danger, custom_id=\"caos:goal:reject\")\n    async def reject(self, interaction: discord.Interaction, button: discord.ui.Button):\n        await self._decide(interaction, False)\n\n\nclass ADVRegularizationView(discord.ui.View):\n    def __init__(self):\n        super().__init__(timeout=None)\n\n    async def _decide(self, interaction: discord.Interaction, accept: bool):\n        guild = interaction.guild\n        channel = interaction.channel\n        staff = interaction.user\n        if guild is None or not isinstance(channel, discord.TextChannel) or not isinstance(staff, discord.Member):\n            return await interaction.response.send_message(\"Use este botão dentro do ticket de ADV.\", ephemeral=True)\n        room = room_get(channel.id)\n        if not room or room[\"kind\"] != \"adv\" or room[\"status\"] != \"open\":\n            return await interaction.response.send_message(\"Este ticket de regularização não está aberto.\", ephemeral=True)\n        if not is_staff_reviewer(staff, guild):\n            return await interaction.response.send_message(\"Somente a equipe responsável pode validar a regularização.\", ephemeral=True)\n        user_id = int(room[\"user_id\"])\n        if not accept:\n            await interaction.response.send_message(\"Regularização não aprovada. Peça ao membro um comprovante válido.\", ephemeral=True)\n            try:\n                member = guild.get_member(user_id) or await guild.fetch_member(user_id)\n                await member.send(\"⚠️ Sua regularização de ADV ainda não foi aprovada. Confira o comprovante enviado no ticket e fale com um superior.\")\n            except (discord.NotFound, discord.Forbidden):\n                pass\n            return\n        with db() as con:\n            con.execute(\n                \"INSERT INTO adv_state(guild_id,user_id,adv_count,last_adv_at,next_adv_at,source_week_start,ticket_channel_id) VALUES(?,?,0,NULL,NULL,NULL,NULL) \"\n                \"ON CONFLICT(guild_id,user_id) DO UPDATE SET adv_count=0,last_adv_at=NULL,next_adv_at=NULL,source_week_start=NULL,ticket_channel_id=NULL\",\n                (guild.id, user_id),\n            )\n            con.execute(\n                \"INSERT INTO adv_events(guild_id,user_id,actor_id,adv_count,event_type,note,created_at) VALUES(?,?,?,?,?,?,?)\",\n                (guild.id, user_id, staff.id, 0, \"regularizado\", \"Comprovante de meta entregue ou pagamento de 300k validado\", utc_now()),\n            )\n            con.execute(\"UPDATE rooms SET status='closed' WHERE channel_id=?\", (channel.id,))\n            con.execute(\n                \"UPDATE goal_obligations SET status='regularizada' WHERE guild_id=? AND user_id=? AND status IN ('pendente','em_adv')\",\n                (guild.id, user_id),\n            )\n        member = guild.get_member(user_id)\n        if member:\n            try:\n                await channel.set_permissions(member, view_channel=True, read_message_history=True, send_messages=False)\n                await member.send(\"✅ Sua regularização foi aprovada! Todas as suas ADVs foram zeradas (0/3). Você continua na FAC e deve manter suas metas normalmente.\")\n            except discord.Forbidden:\n                pass\n        for child in self.children:\n            child.disabled = True\n        await interaction.response.send_message(\n            f\"✅ Regularização aprovada por {staff.mention}. Todas as advertências do membro foram zeradas (0/3).\",\n            ephemeral=False,\n        )\n        try:\n            await interaction.message.edit(view=self)\n        except discord.HTTPException:\n            pass\n\n    @discord.ui.button(label=\"Confirmar regularização\", emoji=\"✅\", style=discord.ButtonStyle.success, custom_id=\"caos:adv:approve\")\n    async def approve(self, interaction: discord.Interaction, button: discord.ui.Button):\n        await self._decide(interaction, True)\n\n    @discord.ui.button(label=\"Recusar comprovante\", emoji=\"❌\", style=discord.ButtonStyle.danger, custom_id=\"caos:adv:reject\")\n    async def reject(self, interaction: discord.Interaction, button: discord.ui.Button):\n        await self._decide(interaction, False)\n\n\nasync def create_adv_ticket(\n    guild: discord.Guild, member: discord.Member, *, final_stage: bool = False\n) -> Optional[discord.TextChannel]:\n    \"\"\"Abre o ticket na ADV 1 e atualiza as instruções/validação na ADV 3.\"\"\"\n    with db() as con:\n        existing = con.execute(\n            \"SELECT channel_id FROM rooms WHERE guild_id=? AND user_id=? AND kind='adv' AND status='open'\",\n            (guild.id, member.id),\n        ).fetchone()\n    channel = None\n    if existing:\n        old_channel = guild.get_channel(int(existing[\"channel_id\"]))\n        if isinstance(old_channel, discord.TextChannel):\n            channel = old_channel\n    created_new = channel is None\n    if created_new:\n        try:\n            channel = await create_private_room(\n                guild, member, \"adv\", \"ticket_category_id\", \"regularizar-meta\", \"Acompanhamento de meta/ADV\"\n            )\n        except (discord.Forbidden, discord.HTTPException):\n            logger.exception(\"Não foi possível abrir ticket de ADV para %s\", member.id)\n            return None\n\n    staff = await staff_role(guild)\n    if final_stage:\n        embed = discord.Embed(\n            title=\"🚨 Regularização de advertências — ADV 3 de 3\",\n            description=(\n                f\"Olá, {member.mention}. Para continuar na FAC, envie neste ticket **uma** das comprovações abaixo:\\n\\n\"\n                \"**Opção 1 — Entregar a meta:** faça 20, coloque no baú e envie uma foto/print que permita conferir a entrega.\\n\\n\"\n                \"**Opção 2 — Pagamento:** pague **300k** pelo painel da FAC e envie o print do pagamento.\\n\\n\"\n                \"Um superior verificará o comprovante. Só depois da aprovação o bot zerará todas as ADVs (0/3).\"\n            ),\n            colour=discord.Colour.red(), timestamp=discord.utils.utcnow(),\n        )\n        await channel.send(\n            content=f\"{member.mention} • {staff.mention if staff else 'Equipe responsável'}\",\n            embed=embed, view=ADVRegularizationView(),\n        )\n        with db() as con:\n            con.execute(\n                \"UPDATE adv_state SET ticket_channel_id=? WHERE guild_id=? AND user_id=?\",\n                (channel.id, guild.id, member.id),\n            )\n    elif created_new:\n        embed = discord.Embed(\n            title=\"🎯 Acompanhamento da meta — ADV 1 de 3\",\n            description=(\n                f\"Olá, {member.mention}. Este ticket foi aberto para acompanhar a regularização da sua meta.\\n\\n\"\n                \"Informe à equipe que você está regularizando a meta e envie aqui a comprovação quando concluir: \"\n                \"faça 20, coloque no baú e mande uma foto. A equipe poderá orientar você por este canal.\\n\\n\"\n                \"Se a pendência continuar, o sistema poderá avançar para as próximas advertências em intervalos de 5 dias.\"\n            ),\n            colour=discord.Colour.orange(), timestamp=discord.utils.utcnow(),\n        )\n        await channel.send(\n            content=f\"{member.mention} • {staff.mention if staff else 'Equipe responsável'}\",\n            embed=embed, view=CloseRoomView(),\n        )\n        with db() as con:\n            con.execute(\n                \"UPDATE adv_state SET ticket_channel_id=? WHERE guild_id=? AND user_id=?\",\n                (channel.id, guild.id, member.id),\n            )\n    return channel\n\n\nasync def apply_adv(guild: discord.Guild, member: discord.Member, count: int, note: str = \"Meta semanal não regularizada\") -> None:\n    now = utc_now()\n    next_at = (datetime.now(timezone.utc) + timedelta(days=ADV_GRACE_DAYS)).isoformat() if count < 3 else None\n    with db() as con:\n        con.execute(\n            \"INSERT INTO adv_state(guild_id,user_id,adv_count,last_adv_at,next_adv_at,source_week_start,ticket_channel_id) VALUES(?,?,?,?,?,?,NULL) \"\n            \"ON CONFLICT(guild_id,user_id) DO UPDATE SET adv_count=excluded.adv_count,last_adv_at=excluded.last_adv_at,next_adv_at=excluded.next_adv_at\",\n            (guild.id, member.id, count, now, next_at, None),\n        )\n        con.execute(\n            \"INSERT INTO adv_events(guild_id,user_id,actor_id,adv_count,event_type,note,created_at) VALUES(?,?,?,?,?,?,?)\",\n            (guild.id, member.id, None, count, \"advertencia\", note, now),\n        )\n    if count == 1:\n        message = (\n            \"🚨 **Advertência 1 de 3**\\n\\nPô, você não está cumprindo suas metas e está tomando ADV. \"\n            \"Cuidado para não ser expulso. Comece a pagar suas metas e regularize sua situação.\"\n        )\n    elif count == 2:\n        message = (\n            \"🚨 **Advertência 2 de 3 — ÚLTIMO AVISO**\\n\\nEste é seu último aviso. Você não está cumprindo a meta \"\n            \"e corre o risco de ser expulso da FAC. Regularize sua situação imediatamente.\"\n        )\n    else:\n        message = (\n            \"🚨 **Advertência 3 de 3**\\n\\nMeu amigo, será que é muito difícil cumprir as metas que nós pedimos? \"\n            \"É só fazer 20, colocar no baú e mandar uma foto.\\n\\nPara continuar na FAC, você também pode pagar **300k** pelo painel da FAC, \"\n            \"tirar um print e enviar neste ticket. Um superior vai conferir. Após a validação da entrega da meta ou do pagamento, \"\n            \"todas as suas ADVs serão zeradas e você continua cumprindo as metas normalmente.\"\n        )\n    try:\n        await member.send(message)\n    except discord.Forbidden:\n        await notify_staff(guild, f\"⚠️ Não consegui enviar a ADV {count}/3 no PV de {member.mention}; mensagens privadas estão fechadas.\")\n    await notify_staff(guild, f\"🚨 {member.mention} recebeu **ADV {count}/3**. Motivo: {note}.\")\n    if count in {1, 3}:\n        channel = await create_adv_ticket(guild, member, final_stage=(count == 3))\n        if channel:\n            try:\n                if count == 1:\n                    await member.send(f\"🎫 Abri um ticket para você informar que está regularizando a meta: {channel.mention}\")\n                else:\n                    await member.send(f\"🎫 Seu ticket foi atualizado para a regularização final. Envie o comprovante da meta ou do pagamento de 300k: {channel.mention}\")\n            except discord.Forbidden:\n                pass\n\n\nasync def process_weekly_promotions(client: commands.Bot) -> None:\n    current_start, _ = current_week_bounds()\n    previous_start = current_start - timedelta(days=7)\n    previous_end = current_start\n    week_key = previous_start.isoformat()\n    for guild in client.guilds:        fac_role = configured_role(guild, \"fac_member_role_id\")\n        role_ids = [config_get(guild.id, key) for key in PROMOTION_ROLE_KEYS]\n        if not fac_role or not all(role_ids):\n            continue\n        roles = [guild.get_role(int(role_id)) if role_id and str(role_id).isdigit() else None for role_id in role_ids]\n        if any(role is None for role in roles):\n            continue\n        for member in list(fac_role.members):\n            if member.bot:\n                continue\n            with db() as con:\n                done = con.execute(\n                    \"SELECT 1 FROM weekly_promotion_runs WHERE guild_id=? AND user_id=? AND week_start=?\",\n                    (guild.id, member.id, week_key),\n                ).fetchone()\n            if done:\n                continue\n            worked = seconds_worked_in_window(guild.id, member.id, previous_start, previous_end)\n            if worked < WEEKLY_POINT_GOAL_SECONDS:\n                continue\n            current_index = max((i for i, role in enumerate(roles) if role in member.roles), default=-1)\n            target_index = current_index + 1\n            if target_index >= len(roles):\n                with db() as con:\n                    con.execute(\n                        \"INSERT OR IGNORE INTO weekly_promotion_runs(guild_id,user_id,week_start,role_id,created_at) VALUES(?,?,?,?,?)\",\n                        (guild.id, member.id, week_key, roles[-1].id, utc_now()),\n                    )\n                continue\n            target = roles[target_index]\n            me = guild.me\n            if not me or not me.guild_permissions.manage_roles or me.top_role <= target:\n                logger.warning(\"Não foi possível promover %s: cargo %s acima do bot ou falta Gerenciar cargos\", member.id, target.name)\n                continue\n            old_roles = [role for role in roles if role in member.roles]\n            try:\n                # Adiciona o novo cargo antes de remover o anterior para nunca deixar o membro sem patente.\n                await member.add_roles(target, reason=\"Promoção automática: 5 horas cumpridas na semana anterior\")\n                if old_roles:\n                    await member.remove_roles(*old_roles, reason=\"Atualização de cargo por meta semanal de ponto\")\n            except discord.Forbidden:\n                logger.exception(\"Falha ao atribuir promoção de %s\", member.id)\n                continue\n            with db() as con:\n                con.execute(\n                    \"INSERT OR IGNORE INTO weekly_promotion_runs(guild_id,user_id,week_start,role_id,created_at) VALUES(?,?,?,?,?)\",\n                    (guild.id, member.id, week_key, target.id, utc_now()),\n                )\n                con.execute(\n                    \"INSERT INTO promotions(guild_id,user_id,role_id,week_start,hours_seconds,created_at) VALUES(?,?,?,?,?,?)\",\n                    (guild.id, member.id, target.id, week_key, worked, utc_now()),\n                )\n            try:\n                await member.send(\n                    embed=discord.Embed(\n                        title=\"🏆 Parabéns pela promoção!\",\n                        description=f\"Você cumpriu a meta semanal de 5 horas e foi promovido!\\n\\nSeu novo cargo é:\\n**{target.name}**\\n\\nContinue assim e mantenha suas metas semanais.\",\n                        colour=discord.Colour.gold(), timestamp=discord.utils.utcnow(),\n                    )\n                )\n            except discord.Forbidden:\n                await notify_staff(guild, f\"⚠️ {member.mention} foi promovido para {target.mention}, mas não recebe mensagens privadas.\")\n            await notify_staff(guild, f\"🏆 {member.mention} foi promovido para {target.mention} após cumprir 5 horas na semana anterior.\")\n\n\nasync def process_weekly_advs(client: commands.Bot) -> None:\n    \"\"\"Aplica ADV apenas para metas cobradas explicitamente por um superior.\n\n    O prazo inicial é de 5 dias; se a pendência continuar aberta, ADV 2 e ADV 3\n    avançam em intervalos adicionais de 5 dias. A meta de 5h do bate-ponto não\n    é confundida com a entrega de meta/baú.\n    \"\"\"\n    now = datetime.now(timezone.utc)\n    for guild in client.guilds:\n        with db() as con:\n            due = con.execute(\n                \"SELECT * FROM goal_obligations WHERE guild_id=? AND status='pendente' AND deadline_at<=?\",\n                (guild.id, now.isoformat()),\n            ).fetchall()\n        for obligation in due:\n            member = guild.get_member(int(obligation[\"user_id\"]))\n            if member is None:\n                try:\n                    member = await guild.fetch_member(int(obligation[\"user_id\"]))\n                except discord.NotFound:\n                    continue\n            with db() as con:\n                state = con.execute(\n                    \"SELECT adv_count FROM adv_state WHERE guild_id=? AND user_id=?\",\n                    (guild.id, member.id),\n                ).fetchone()\n            if not state or int(state[\"adv_count\"]) == 0:\n                await apply_adv(\n                    guild, member, 1,\n                    f\"Prazo de 5 dias expirou sem entrega da meta: {obligation['description']}\",\n                )\n            with db() as con:\n                con.execute(\"UPDATE goal_obligations SET status='em_adv' WHERE id=? AND status='pendente'\", (int(obligation[\"id\"]),))\n\n        # Enquanto a cobrança continuar sem regularização, a próxima ADV chega após mais 5 dias.\n        with db() as con:\n            due_rows = con.execute(\n                \"SELECT a.user_id, a.adv_count, a.next_adv_at FROM adv_state a \"\n                \"WHERE a.guild_id=? AND a.adv_count IN (1,2) AND a.next_adv_at IS NOT NULL \"\n                \"AND NOT EXISTS (SELECT 1 FROM goal_obligations o WHERE o.guild_id=a.guild_id AND o.user_id=a.user_id AND o.status='em_analise')\",\n                (guild.id,),\n            ).fetchall()\n        for row in due_rows:\n            if _aware_utc(row[\"next_adv_at\"]) > now:\n                continue\n            member = guild.get_member(int(row[\"user_id\"]))\n            if member is None:\n                try:\n                    member = await guild.fetch_member(int(row[\"user_id\"]))\n                except discord.NotFound:\n                    continue\n            await apply_adv(guild, member, int(row[\"adv_count\"]) + 1, \"Meta ainda não regularizada após mais 5 dias\")\n\n\nasync def point_monitor_loop(client: commands.Bot) -> None:\n    \"\"\"Monitora a call configurada, lembretes de 3h e prazo de 3 minutos.\"\"\"\n    await client.wait_until_ready()\n    last_maintenance = 0.0\n    loop = asyncio.get_running_loop()\n    while not client.is_closed():\n        try:\n            now = datetime.now(timezone.utc)\n            for guild in client.guilds:\n                channel_id = config_get(guild.id, \"point_voice_channel_id\")\n                if not channel_id or not str(channel_id).isdigit():\n                    continue\n                voice_channel = guild.get_channel(int(channel_id))\n                if not isinstance(voice_channel, (discord.VoiceChannel, discord.StageChannel)):\n                    continue\n                # Recupera automaticamente usuários que já estavam na call quando o bot voltou.\n                for member in list(voice_channel.members):\n                    if not member.bot:\n                        await start_point_for_member(guild, member, voice_channel.id, reason=\"Reconciliação da call monitorada\")\n                with db() as con:\n                    active_rows = con.execute(\n                        \"SELECT ap.user_id, ap.started_at, pp.last_confirmed_at, pp.pending_since, pp.channel_id \"\n                        \"FROM active_points ap LEFT JOIN point_presence pp ON pp.guild_id=ap.guild_id AND pp.user_id=ap.user_id \"\n                        \"WHERE ap.guild_id=?\",\n                        (guild.id,),\n                    ).fetchall()\n                for row in active_rows:\n                    member = guild.get_member(int(row[\"user_id\"]))\n                    if member is None:\n                        try:\n                            member = await guild.fetch_member(int(row[\"user_id\"]))\n                        except discord.NotFound:\n                            continue\n                    if not member.voice or not member.voice.channel or member.voice.channel.id != voice_channel.id:\n                        await stop_point_for_member(guild, member, reason=\"Saiu da call monitorada\")\n                        continue\n                    if not row[\"last_confirmed_at\"]:\n                        with db() as con:\n                            con.execute(\n                                \"INSERT OR REPLACE INTO point_presence(guild_id,user_id,channel_id,last_confirmed_at,pending_since) VALUES(?,?,?,?,NULL)\",\n                                (guild.id, member.id, voice_channel.id, row[\"started_at\"]),\n                            )\n                        row_last_confirmed = row[\"started_at\"]\n                    else:\n                        row_last_confirmed = row[\"last_confirmed_at\"]\n                    if row[\"pending_since\"]:\n                        pending = _aware_utc(row[\"pending_since\"])\n                        if (now - pending).total_seconds() >= POINT_CONFIRM_GRACE_SECONDS:\n                            try:\n                                await member.move_to(None, reason=\"Não confirmou presença no bate-ponto em 3 minutos\")\n                            except discord.Forbidden:\n                                await notify_staff(guild, f\"⚠️ Não consegui retirar {member.mention} da call: falta permissão **Mover membros**.\")\n                            except discord.HTTPException:\n                                logger.exception(\"Falha ao desconectar membro após falta de confirmação\")\n                            await stop_point_for_member(guild, member, reason=\"Não confirmou presença em 3 minutos\")\n                        continue\n                    last_confirmed = _aware_utc(row_last_confirmed)\n                    if (now - last_confirmed).total_seconds() >= POINT_REMINDER_SECONDS:\n                        with db() as con:\n                            con.execute(\n                                \"UPDATE point_presence SET pending_since=? WHERE guild_id=? AND user_id=? AND pending_since IS NULL\",\n                                (now.isoformat(), guild.id, member.id),\n                            )\n                        try:\n                            await member.send(\n                                embed=discord.Embed(\n                                    title=\"⏰ Você ainda está com o ponto ligado!\",\n                                    description=(\"Você continua presente na call? Clique no botão abaixo para confirmar.\\n\\n\"\n                                                 \"Você tem **3 minutos** para confirmar. Se não confirmar, o bot encerrará seu ponto e tentará desconectar você da call.\"),\n                                    colour=discord.Colour.orange(), timestamp=discord.utils.utcnow(),\n                                ),\n                                view=PointPresenceConfirmView(),\n                            )\n                        except discord.Forbidden:\n                            # Não aplica expulsão baseada em DM que não pôde ser entregue; tenta novamente em 15 min.\n                            retry_at = (now - timedelta(hours=2, minutes=45)).isoformat()\n                            with db() as con:\n                                con.execute(\n                                    \"UPDATE point_presence SET pending_since=NULL,last_confirmed_at=? WHERE guild_id=? AND user_id=?\",\n                                    (retry_at, guild.id, member.id),\n                                )\n                            await notify_staff(guild, f\"⚠️ Não consegui enviar lembrete de presença para {member.mention}; DM fechada. Não desconectei o membro.\")\n            if loop.time() - last_maintenance >= 300:\n                await process_weekly_promotions(client)\n                await process_weekly_advs(client)\n                last_maintenance = loop.time()\n        except asyncio.CancelledError:\n            raise\n        except Exception:\n            logger.exception(\"Erro no monitor automático de ponto/promoções/ADV\")\n        await asyncio.sleep(20)\n\n\n# ---------------------------------------------------------------------------\n# Brincadeira opcional: trilha de terror a cada 5 horas por 20 minutos\n# ---------------------------------------------------------------------------\n\nHORROR_INTERVAL_SECONDS = 5 * 60 * 60\nHORROR_DURATION_SECONDS = 20 * 60\nHORROR_TASKS: dict[int, asyncio.Task] = {}\n\n\ndef ensure_original_horror_audio() -> Path:\n    \"\"\"Usa assets/terror.mp3 se fornecido; senão gera uma trilha ambiente original em WAV.\"\"\"\n    assets = ROOT / \"assets\"\n    assets.mkdir(parents=True, exist_ok=True)\n    for filename in (\"terror.mp3\", \"terror.ogg\", \"terror.wav\"):\n        candidate = assets / filename\n        if candidate.is_file() and candidate.stat().st_size > 1024:\n            return candidate\n\n    output = assets / \"terror_ambiente.wav\"\n    if output.is_file() and output.stat().st_size > 1024:\n        return output\n\n    sample_rate = 22050\n    duration = 60\n    sample_count = sample_rate * duration\n    pcm = array(\"h\")\n    tau = 2.0 * math.pi\n    for index in range(sample_count):\n        t = index / sample_rate\n        fade = min(1.0, t / 1.5, (duration - t) / 1.5)\n        swell = 0.78 + 0.22 * math.sin(tau * 0.035 * t)\n        drone = (\n            0.19 * math.sin(tau * 47.0 * t)\n            + 0.12 * math.sin(tau * 50.7 * t)\n            + 0.07 * math.sin(tau * 95.0 * t)\n            + 0.045 * math.sin(tau * 143.2 * t)\n        ) * swell\n        wind = 0.035 * math.sin(tau * 0.22 * t) * math.sin(tau * 17.0 * t)\n        bell = 0.0\n        for center, frequency in ((8.0, 392.0), (21.0, 311.0), (36.0, 466.0), (49.0, 349.0)):\n            dt = t - center\n            if 0.0 <= dt <= 5.0:\n                bell += 0.12 * math.exp(-dt * 1.05) * math.sin(tau * frequency * dt)\n        sample = max(-0.92, min(0.92, (drone + wind + bell) * fade))\n        pcm.append(int(sample * 32767))\n\n    with wave.open(str(output), \"wb\") as wav_file:\n        wav_file.setnchannels(1)\n        wav_file.setsampwidth(2)\n        wav_file.setframerate(sample_rate)\n        wav_file.writeframes(pcm.tobytes())\n    return output\n\n\nasync def run_horror_prank(guild: discord.Guild, voice_channel: discord.VoiceChannel, target: discord.Member) -> None:\n    \"\"\"Toca 20 minutos; só desconecta no final se esta rotina conectou o CAOS.\"\"\"\n    voice = None\n    source = None\n    try:\n        existing_voice = guild.voice_client\n        if existing_voice and existing_voice.is_connected():\n            if existing_voice.channel != voice_channel or existing_voice.is_playing() or existing_voice.is_paused():\n                logger.info(\"Brincadeira de terror ignorada: o CAOS já está ocupado em outra call ou reproduzindo áudio.\")\n                return\n            voice = existing_voice  # reutiliza conexão ociosa na call monitorada\n        else:\n            me = guild.me\n            permissions = voice_channel.permissions_for(me) if me else None\n            if not permissions or not permissions.connect or not permissions.speak:\n                await notify_staff(guild, f\"⚠️ Não consegui iniciar a brincadeira de terror em {voice_channel.mention}: faltam permissões Conectar/Falar.\")\n                return\n            voice = await voice_channel.connect(self_mute=False, self_deaf=False)\n            await _set_voice_mode_normal(guild, voice_channel)\n\n        audio_path = await asyncio.to_thread(ensure_original_horror_audio)\n        ffmpeg_path = _resolve_ffmpeg_executable()\n        source = discord.FFmpegOpusAudio(\n            str(audio_path),\n            executable=ffmpeg_path,\n            before_options=\"-stream_loop -1\",\n            options=f\"-t {HORROR_DURATION_SECONDS} -vn -af volume=0.70\",\n        )\n        voice.play(source)\n        source = None  # o player assume a fonte e faz a limpeza ao terminar\n        await notify_staff(guild, f\"👻 Brincadeira de terror iniciada na call {voice_channel.mention}; alvo sorteado: {target.mention}. Duração máxima: 20 minutos.\")\n\n        deadline = asyncio.get_running_loop().time() + HORROR_DURATION_SECONDS\n        while asyncio.get_running_loop().time() < deadline:\n            if not voice.is_connected() or not voice.is_playing():\n                break\n            await asyncio.sleep(5)\n    except asyncio.CancelledError:\n        raise\n    except (discord.Forbidden, discord.HTTPException, RuntimeError, OSError) as exc:\n        logger.exception(\"Falha na brincadeira automática de terror\")\n        await notify_staff(guild, f\"⚠️ A brincadeira de terror não pôde ser executada: {type(exc).__name__}: {str(exc)[:180]}\")\n    except Exception:\n        logger.exception(\"Erro inesperado na brincadeira de terror\")\n        await notify_staff(guild, \"⚠️ Ocorreu um erro inesperado na brincadeira de terror. Consulte o log do CAOS.\")\n    finally:\n        if source is not None:\n            try:\n                source.cleanup()\n            except Exception:\n                pass\n        if voice and voice.is_connected():\n            try:\n                if voice.is_playing() or voice.is_paused():\n                    voice.stop()\n                await voice.disconnect(force=True)\n            except (discord.Forbidden, discord.HTTPException):\n                logger.exception(\"Não consegui desconectar após a brincadeira de terror\")\n        current = HORROR_TASKS.get(guild.id)\n        if current is asyncio.current_task():\n            HORROR_TASKS.pop(guild.id, None)\n\n\nasync def horror_prank_loop(client: commands.Bot) -> None:\n    \"\"\"Executa a brincadeira a cada cinco horas quando ativada por administrador.\"\"\"\n    await client.wait_until_ready()\n    while not client.is_closed():\n        try:\n            now = datetime.now(timezone.utc)\n            for guild in client.guilds:\n                if config_get(guild.id, \"horror_prank_enabled\") != \"1\":\n                    continue\n                next_run = config_get(guild.id, \"horror_prank_next_run\")\n                if not next_run:\n                    config_set(guild.id, \"horror_prank_next_run\", (now + timedelta(seconds=HORROR_INTERVAL_SECONDS)).isoformat())\n                    continue\n                try:\n                    scheduled = _aware_utc(next_run)\n                except (TypeError, ValueError):\n                    scheduled = now + timedelta(seconds=HORROR_INTERVAL_SECONDS)\n                    config_set(guild.id, \"horror_prank_next_run\", scheduled.isoformat())\n                    continue\n                if now < scheduled:\n                    continue\n\n                # Agenda o próximo ciclo antes de iniciar a reprodução, evitando duplicidade.\n                config_set(guild.id, \"horror_prank_next_run\", (now + timedelta(seconds=HORROR_INTERVAL_SECONDS)).isoformat())\n                channel_id = config_get(guild.id, \"point_voice_channel_id\")\n                channel = guild.get_channel(int(channel_id)) if channel_id and str(channel_id).isdigit() else None\n                if not isinstance(channel, discord.VoiceChannel):\n                    await notify_staff(guild, \"⚠️ A brincadeira de terror venceu o horário, mas não há uma call monitorada configurada.\")\n                    continue\n                existing_voice = guild.voice_client\n                if existing_voice and existing_voice.is_connected():\n                    if existing_voice.channel != channel or existing_voice.is_playing() or existing_voice.is_paused():\n                        await notify_staff(guild, \"ℹ️ Brincadeira de terror pulada: o CAOS já estava ocupado em outra call ou reproduzindo áudio.\")\n                        continue\n                with db() as con:\n                    active_ids = {\n                        int(row[\"user_id\"])\n                        for row in con.execute(\n                            \"SELECT user_id FROM active_points WHERE guild_id=?\", (guild.id,)\n                        ).fetchall()\n                    }\n                candidates = [m for m in channel.members if not m.bot and m.id in active_ids]\n                if not candidates:\n                    await notify_staff(guild, \"ℹ️ Brincadeira de terror pulada: não havia membro com ponto ativo na call monitorada.\")\n                    continue\n                target = random.choice(candidates)\n                if guild.id not in HORROR_TASKS or HORROR_TASKS[guild.id].done():\n                    HORROR_TASKS[guild.id] = asyncio.create_task(run_horror_prank(guild, channel, target))\n        except asyncio.CancelledError:\n            raise\n        except Exception:\n            logger.exception(\"Erro no agendador da brincadeira de terror\")\n        await asyncio.sleep(30)\n\n\n# ---------------------------------------------------------------------------\n# Bot e eventos\n# ---------------------------------------------------------------------------\n\nintents = discord.Intents.default()\nintents.members = True\nintents.message_content = True\nintents.voice_states = True\n\n\nclass CaosBot(commands.Bot):\n    async def setup_hook(self):\n        init_db()\n        self.add_view(TicketPanelView())\n        self.add_view(CloseRoomView())\n        self.add_view(PointControlView())\n        self.add_view(PointPresenceConfirmView())\n        self.add_view(RecruitmentReviewView())\n        self.add_view(ADVRegularizationView())\n        self.add_view(GoalSubmissionReviewView())\n        self.add_view(GoalPanelView())\n        self.add_view(RecruitmentPanelView())\n        self.add_view(RequestPanelView())\n        self.add_view(RulesPanelView(\"discord\"))\n        self.add_view(RulesPanelView(\"equipe\"))\n        self.add_view(RulesPanelView(\"rp\"))\n        self.add_view(MusicPanelView())\n        apply_module_filter(self.tree)\n        if any(module_enabled(key) for key in (\"attendance\", \"goals\", \"warnings\", \"team\")):\n            if not getattr(self, \"point_monitor_task\", None) or self.point_monitor_task.done():\n                self.point_monitor_task = asyncio.create_task(point_monitor_loop(self))\n        if module_enabled(\"horror\") and (not getattr(self, \"horror_prank_task\", None) or self.horror_prank_task.done()):\n            self.horror_prank_task = asyncio.create_task(horror_prank_loop(self))\n        if TEST_GUILD_ID.isdigit():\n            guild_obj = discord.Object(id=int(TEST_GUILD_ID))\n            self.tree.copy_global_to(guild=guild_obj)\n            synced = await self.tree.sync(guild=guild_obj)\n            print(f\"Comandos sincronizados no servidor de teste {TEST_GUILD_ID}: {len(synced)} comando(s).\")\n        else:\n            synced = await self.tree.sync()\n            print(f\"Comandos globais sincronizados: {len(synced)} comando(s).\")\n\n\nbot = CaosBot(command_prefix=\"!\", intents=intents, help_command=None)\n\n\ndef ai_panel_embed(guild: discord.Guild) -> discord.Embed:\n    enabled = config_get(guild.id, \"ai_enabled\") == \"1\"\n    embed = discord.Embed(\n        title=\"🤖・PAINEL DE INTELIGÊNCIA ARTIFICIAL\",\n        description=(\"Configure os canais de perguntas, criação de imagens e monitoramento automático.\\n\"\n                     + (\"🟢 IA ativada\" if enabled else \"🔴 IA desativada\")),\n        colour=discord.Colour.from_rgb(38, 112, 190),\n    )\n    fields = [\n        (\"Canal de perguntas\", \"ai_questions_channel_id\"),\n        (\"Canal de criação de imagens\", \"ai_images_channel_id\"),\n        (\"Canal monitorado (REC/formulário)\", \"ai_monitor_channel_id\"),\n    ]\n    for title, key in fields:\n        value = config_get(guild.id, key)\n        mention = f\"<#{value}>\" if value and str(value).isdigit() else \"Não configurado\"\n        embed.add_field(name=title, value=mention, inline=False)\n    embed.set_footer(text=\"As regras automáticas de recrutamento são fixas; a IA geral responde no canal escolhido.\")\n    return embed\n\n\ndef can_configure_ai(interaction: discord.Interaction) -> bool:\n    \"\"\"Permite ao dono do servidor ou a quem tenha Administrador/Gerenciar servidor configurar a IA.\"\"\"\n    guild = interaction.guild\n    if guild is None:\n        return False\n    if interaction.user.id == guild.owner_id:\n        return True\n    permissions = getattr(interaction.user, \"guild_permissions\", None)\n    return bool(permissions and (permissions.administrator or permissions.manage_guild))\n\n\nasync def reply_ai_panel_error(interaction: discord.Interaction, exc: Exception, context: str) -> None:\n    logger.exception(\"Falha %s no painel IA (guild=%s)\", context, getattr(interaction.guild, \"id\", None))\n    message = (\n        f\"⚠️ Não consegui {context} do painel de IA. \"\n        f\"Falha técnica: **{type(exc).__name__}**. \"\n        \"O erro foi registrado no log do CAOS para diagnóstico.\"\n    )\n    try:\n        if interaction.response.is_done():\n            await interaction.followup.send(message, ephemeral=True)\n        else:\n            await interaction.response.send_message(message, ephemeral=True)\n    except discord.HTTPException:\n        logger.exception(\"Também falhou ao informar o erro do painel IA ao usuário.\")\n\n\nclass AIChannelSelect(discord.ui.ChannelSelect):\n    def __init__(self, label: str, config_key: str, row: int):\n        super().__init__(\n            placeholder=label, min_values=1, max_values=1, row=row,\n            channel_types=[discord.ChannelType.text],\n        )\n        self.config_key = config_key\n\n    async def callback(self, interaction: discord.Interaction):\n        view = self.view\n        if not interaction.guild:\n            return await interaction.response.send_message(\"Use o painel dentro de um servidor.\", ephemeral=True)\n        if not isinstance(view, AIConfigView) or interaction.user.id != view.owner_id:\n            return await interaction.response.send_message(\"Somente quem abriu este painel pode configurar os canais.\", ephemeral=True)\n        if not can_configure_ai(interaction):\n            return await interaction.response.send_message(\"Você precisa ser dono do servidor, administrador ou ter **Gerenciar servidor** para configurar a IA.\", ephemeral=True)\n        channel = self.values[0]\n        if not isinstance(channel, discord.TextChannel) or channel.guild.id != interaction.guild.id:\n            return await interaction.response.send_message(\"Selecione um canal de texto deste servidor.\", ephemeral=True)\n        try:\n            config_set(interaction.guild.id, self.config_key, channel.id)\n            await interaction.response.edit_message(embed=ai_panel_embed(interaction.guild), view=view)\n        except Exception as exc:\n            await reply_ai_panel_error(interaction, exc, \"salvar a configuração\")\n\n\nclass AIToggleButton(discord.ui.Button):\n    def __init__(self, enabled: bool):\n        super().__init__(\n            label=\"Desativar IA\" if enabled else \"Ativar IA\",\n            style=discord.ButtonStyle.danger if enabled else discord.ButtonStyle.success,\n            emoji=\"⏻\", row=3,\n        )\n\n    async def callback(self, interaction: discord.Interaction):\n        view = self.view\n        if not interaction.guild:\n            return await interaction.response.send_message(\"Use o painel dentro de um servidor.\", ephemeral=True)\n        if not isinstance(view, AIConfigView) or interaction.user.id != view.owner_id:\n            return await interaction.response.send_message(\"Somente quem abriu este painel pode alterar a IA.\", ephemeral=True)\n        if not can_configure_ai(interaction):\n            return await interaction.response.send_message(\"Você precisa ser dono do servidor, administrador ou ter **Gerenciar servidor** para configurar a IA.\", ephemeral=True)\n        try:\n            enabled = config_get(interaction.guild.id, \"ai_enabled\") == \"1\"\n            config_set(interaction.guild.id, \"ai_enabled\", 0 if enabled else 1)\n            await interaction.response.edit_message(\n                embed=ai_panel_embed(interaction.guild),\n                view=AIConfigView(interaction.guild, view.owner_id),\n            )\n        except Exception as exc:\n            await reply_ai_panel_error(interaction, exc, \"alternar a IA\")\n\n\nclass AIConfigView(discord.ui.View):\n    def __init__(self, guild: discord.Guild, owner_id: int):\n        super().__init__(timeout=600)\n        self.owner_id = owner_id\n        self.add_item(AIChannelSelect(\"Escolher canal de perguntas\", \"ai_questions_channel_id\", 0))\n        self.add_item(AIChannelSelect(\"Escolher canal de criação de imagens\", \"ai_images_channel_id\", 1))\n        self.add_item(AIChannelSelect(\"Escolher canal para monitorar REC/formulários\", \"ai_monitor_channel_id\", 2))\n        self.add_item(AIToggleButton(config_get(guild.id, \"ai_enabled\") == \"1\"))\n\n    async def interaction_check(self, interaction: discord.Interaction) -> bool:\n        if interaction.user.id != self.owner_id:\n            await interaction.response.send_message(\"Somente quem abriu este painel pode usar estes controles.\", ephemeral=True)\n            return False\n        if not can_configure_ai(interaction):\n            await interaction.response.send_message(\"Você precisa ser dono do servidor, administrador ou ter **Gerenciar servidor** para configurar a IA.\", ephemeral=True)\n            return False\n        return True\n\n\n@bot.tree.command(name=\"painel_ia\", description=\"Configura os canais e ativa a inteligência artificial do CAOS.\")\nasync def painel_ia(interaction: discord.Interaction):\n    if not interaction.guild:\n        return await interaction.response.send_message(\"Use este comando dentro de um servidor.\", ephemeral=True)\n    if not can_configure_ai(interaction):\n        return await interaction.response.send_message(\n            \"🔒 Este painel é exclusivo do dono do servidor, administradores ou pessoas com **Gerenciar servidor**.\",\n            ephemeral=True,\n        )\n    try:\n        embed = ai_panel_embed(interaction.guild)\n        view = AIConfigView(interaction.guild, interaction.user.id)\n        await interaction.response.send_message(embed=embed, view=view, ephemeral=True)\n    except Exception as exc:\n        await reply_ai_panel_error(interaction, exc, \"abrir\")\n\n\n@bot.tree.command(name=\"perguntar\", description=\"Faz uma pergunta diretamente para a IA do CAOS.\")\n@app_commands.describe(pergunta=\"O que você gostaria de perguntar para a IA?\")\nasync def perguntar(interaction: discord.Interaction, pergunta: str):\n    if not interaction.guild:\n        return await interaction.response.send_message(\"Use este comando dentro de um servidor.\", ephemeral=True)\n    if config_get(interaction.guild.id, \"ai_enabled\") != \"1\":\n        return await interaction.response.send_message(\"A IA está desativada neste servidor.\", ephemeral=True)\n    questions_id = config_get(interaction.guild.id, \"ai_questions_channel_id\")\n    if questions_id and str(interaction.channel_id) != str(questions_id):\n        return await interaction.response.send_message(f\"Use o canal <#{questions_id}> para conversar com a IA.\", ephemeral=True)\n    await interaction.response.defer(thinking=True)\n    history = ai_history_get(interaction.guild.id, interaction.channel_id, interaction.user.id)\n    ai_history_add(interaction.guild.id, interaction.channel_id, interaction.user.id, \"user\", pergunta)\n    try:\n        result = await caos_ai_post({\n            \"action\": \"chat\", \"guildId\": str(interaction.guild.id), \"userId\": str(interaction.user.id),\n            \"prompt\": pergunta[:1400], \"history\": history,\n        })\n        answer = str(result.get(\"text\") or \"Não consegui gerar uma resposta.\")[:1800]\n        ai_history_add(interaction.guild.id, interaction.channel_id, interaction.user.id, \"assistant\", answer)\n        await interaction.followup.send(answer)\n    except Exception as exc:\n        await interaction.followup.send(f\"⚠️ {str(exc)[:350]}\")\n\n\n@bot.tree.command(name=\"criar_imagem\", description=\"Pede para a IA criar uma imagem e enviar no Discord.\")\n@app_commands.describe(descricao=\"Descreva a imagem que você quer criar.\")\nasync def criar_imagem(interaction: discord.Interaction, descricao: str):\n    if not interaction.guild:\n        return await interaction.response.send_message(\"Use este comando dentro de um servidor.\", ephemeral=True)\n    if config_get(interaction.guild.id, \"ai_enabled\") != \"1\":\n        return await interaction.response.send_message(\"A IA está desativada neste servidor.\", ephemeral=True)\n    images_id = config_get(interaction.guild.id, \"ai_images_channel_id\")\n    if images_id and str(interaction.channel_id) != str(images_id):\n        return await interaction.response.send_message(f\"Use o canal <#{images_id}> para criar imagens.\", ephemeral=True)\n    await interaction.response.defer(thinking=True)\n    try:\n        result = await caos_ai_post({\n            \"action\": \"image\", \"guildId\": str(interaction.guild.id),\n            \"userId\": str(interaction.user.id), \"prompt\": descricao[:1000],\n        })\n        image_data = _ai_image_bytes(result)\n        file = discord.File(io.BytesIO(image_data), filename=\"caos-ia.png\")\n        await interaction.followup.send(content=f\"🎨 Imagem criada para {interaction.user.mention}.\", file=file)\n    except Exception as exc:\n        await interaction.followup.send(f\"⚠️ Não consegui criar a imagem: {str(exc)[:300]}\")\n\n\nasync def restore_open_recruitment_chat_permissions():\n    \"\"\"Garante que inscrições abertas continuem permitindo conversa normal.\"\"\"\n    for guild in bot.guilds:\n        with db() as con:\n            rows = con.execute(\n                \"SELECT channel_id, user_id FROM rooms \"\n                \"WHERE guild_id=? AND kind='recruit' AND status='open'\",\n                (guild.id,),\n            ).fetchall()\n        for row in rows:\n            channel = guild.get_channel(int(row[\"channel_id\"]))\n            if not isinstance(channel, discord.TextChannel):\n                continue\n            member = guild.get_member(int(row[\"user_id\"]))\n            if member is None:\n                try:\n                    member = await guild.fetch_member(int(row[\"user_id\"]))\n                except (discord.NotFound, discord.Forbidden, discord.HTTPException):\n                    continue\n            try:\n                await channel.set_permissions(\n                    member,\n                    view_channel=True,\n                    read_message_history=True,\n                    send_messages=True,\n                    attach_files=True,\n                    embed_links=True,\n                    add_reactions=True,\n                    reason=\"CAOS: conversa do recrutamento mantida aberta\",\n                )\n                # Também aplica o acesso do REC-OFC em inscrições abertas criadas\n                # antes do cargo de recrutador ter sido configurado.\n                rec_role = await recruiter_role(guild)\n                if rec_role:\n                    await channel.set_permissions(\n                        rec_role,\n                        view_channel=True,\n                        read_message_history=True,\n                        send_messages=True,\n                        manage_messages=True,\n                        reason=\"CAOS: acesso do recrutador oficial ao canal existente\",\n                    )\n            except (discord.Forbidden, discord.HTTPException):\n                logger.warning(\n                    \"Não consegui restaurar todas as permissões no recrutamento %s para o membro %s\",\n                    channel.id, member.id,\n                    exc_info=True,\n                )\n\n\n# Os comandos são publicados globalmente em setup_hook (ou apenas no servidor\n# de teste quando GUILD_ID está configurado). Não copie os comandos globais para\n# cada servidor: isso cria duas entradas iguais no Discord.\nCOMMAND_CLEANED_GUILDS: set[int] = set()\n\n\n@bot.event\nasync def on_ready():\n    for guild in bot.guilds:\n        # O servidor de teste usa sincronização local em setup_hook.\n        if TEST_GUILD_ID.isdigit() and guild.id == int(TEST_GUILD_ID):\n            continue\n        if guild.id in COMMAND_CLEANED_GUILDS:\n            continue\n        guild_scope = discord.Object(id=guild.id)\n        try:\n            # Remove cópias antigas publicadas por versões anteriores do CAOS.\n            # Os comandos globais continuam disponíveis sem duplicação.\n            bot.tree.clear_commands(guild=guild_scope)\n            removed = await bot.tree.sync(guild=guild_scope)\n            COMMAND_CLEANED_GUILDS.add(guild.id)\n            print(\n                f\"Comandos locais antigos removidos de {guild.name} ({guild.id}); \"\n                f\"{len(removed)} comando(s) local(is) restante(s).\"\n            )\n        except (discord.HTTPException, discord.Forbidden):\n            logger.exception(\n                \"Falha ao limpar comandos duplicados no servidor %s (%s)\",\n                guild.name, guild.id,\n            )\n\n    await restore_open_recruitment_chat_permissions()\n    print(\"=\" * 55)\n    print(f\"CAOS conectado como {bot.user} ({bot.user.id})\")\n    print(f\"Servidores: {len(bot.guilds)}\")\n    print(f\"Servidores limpos de cópias locais: {len(COMMAND_CLEANED_GUILDS)}\")\n    print(\"Banco de dados:\", DB_PATH)\n    print(\"=\" * 55)\n\n\n@bot.event\nasync def on_voice_state_update(member: discord.Member, before: discord.VoiceState, after: discord.VoiceState):\n    if not module_enabled(\"attendance\"):\n        return\n    if member.bot:\n        return\n    configured = config_get(member.guild.id, \"point_voice_channel_id\")\n    if not configured or not str(configured).isdigit():\n        return\n    monitored_id = int(configured)\n    before_id = before.channel.id if before.channel else None\n    after_id = after.channel.id if after.channel else None\n    if before_id == monitored_id and after_id != monitored_id:\n        await stop_point_for_member(member.guild, member, reason=\"Saiu da call monitorada\")\n    elif after_id == monitored_id and before_id != monitored_id:\n        await start_point_for_member(member.guild, member, monitored_id, reason=\"Entrou na call monitorada\")\n\n\n@bot.event\nasync def on_message(message: discord.Message):\n    if message.author.bot or not message.guild:\n        return\n\n    # Mensagens automáticas de IA só são processadas quando o módulo está ativo.\n    if module_enabled(\"ai\") and config_get(message.guild.id, \"ai_enabled\") == \"1\":\n        monitor_id = config_get(message.guild.id, \"ai_monitor_channel_id\")\n        if monitor_id and str(message.channel.id) == str(monitor_id):\n            if _is_form_already_done(message.content):\n                await message.reply(\n                    \"📢 Se você já fez o formulário, fala por lá mesmo. Lá mesmo a gente responde você, ao invés de mandar mensagem aqui, pra não confundir os outros.\",\n                    mention_author=False, allowed_mentions=discord.AllowedMentions.none(),\n                )\n                return\n            if _is_recruitment_question(message.content):\n                await message.reply(\n                    \"📢 **RECRUTAMENTO ONLINE!**\\n\\nÉ só você entrar no canal <#1573115177057128638>.\",\n                    mention_author=False, allowed_mentions=discord.AllowedMentions.none(),\n                )\n                return\n\n        images_id = config_get(message.guild.id, \"ai_images_channel_id\")\n        if images_id and str(message.channel.id) == str(images_id) and _is_image_request(message.content):\n            await configured_ai_image(message.channel, message.guild.id, message.author.id, message.content, reply_to=message)\n            return\n\n        questions_id = config_get(message.guild.id, \"ai_questions_channel_id\")\n        if questions_id and str(message.channel.id) == str(questions_id) and message.content.strip():\n            await configured_ai_chat(message)\n            return\n\n    # Fluxos dos canais temporários (recrutamento e meta) continuam prioritários.\n    room = room_get(message.channel.id)\n    if room and room[\"status\"] == \"open\" and int(room[\"user_id\"]) == message.author.id:\n        if room[\"kind\"] == \"goal\":\n            # A foto já é obrigatória e enviada junto com o formulário/modal.\n            return\n\n        if room[\"kind\"] == \"recruit\":\n            with db() as con:\n                session = con.execute(\"SELECT * FROM recruitment_sessions WHERE channel_id=?\", (message.channel.id,)).fetchone()\n            if not session:\n                # O questionário acabou, mas o canal continua sendo um chat normal.\n                # Mensagens posteriores do candidato podem responder às perguntas extras\n                # feitas pelos recrutadores e também podem usar comandos do bot.\n                await bot.process_commands(message)\n                return\n            answers = json.loads(session[\"answers_json\"])\n            index = int(session[\"question_index\"])\n            answer = message.content.strip()\n            if not answer:\n                await message.reply(\"Envie sua resposta em texto para continuar.\")\n                return\n            answers.append({\"question\": RECRUITMENT_QUESTIONS[index], \"answer\": answer})\n            index += 1\n            if index >= len(RECRUITMENT_QUESTIONS):\n                ai_reasons = analyze_ai_signals(answers)\n                status = \"em_analise_ia\" if ai_reasons else \"enviado\"\n                with db() as con:\n                    con.execute(\"DELETE FROM recruitment_sessions WHERE channel_id=?\", (message.channel.id,))\n                    cursor = con.execute(\n                        \"INSERT INTO recruitments(guild_id,user_id,channel_id,answers_json,status,created_at,ai_flag,ai_reasons) VALUES(?,?,?,?,?,?,?,?)\",\n                        (message.guild.id, message.author.id, message.channel.id,\n                         json.dumps(answers, ensure_ascii=False), status, utc_now(), int(bool(ai_reasons)),\n                         \" | \".join(ai_reasons)),\n                    )\n                    recruitment_id = cursor.lastrowid\n                # Não bloqueia o candidato: o recrutamento continua aberto para\n                # perguntas complementares e conversa normal com o REC-OFC.\n                staff = await staff_role(message.guild)\n                recruiter = await recruiter_role(message.guild)\n                embed = discord.Embed(\n                    title=\"📝 Recrutamento concluído — análise necessária\",\n                    description=(\n                        f\"Candidato: {message.author.mention}\\nCanal: {message.channel.mention}\\n\"\n                        f\"Status: **{status.replace('_', ' ')}**\\n\"\n                        + (\"⚠️ **Sinais para revisão manual:** \" + \"; \".join(ai_reasons)\n                           if ai_reasons else \"Nenhum sinal textual básico foi encontrado; a revisão humana continua necessária.\")\n                    ),\n                    colour=discord.Colour.orange() if ai_reasons else discord.Colour.blurple(),\n                    timestamp=discord.utils.utcnow(),\n                )\n                embed.set_footer(text=f\"Recrutamento ID: {recruitment_id} • A triagem não comprova uso de IA\")\n                await message.channel.send(\n                    content=(\n                        f\"✅ **Questionário concluído!** Suas respostas foram encaminhadas para análise.\\n\\n\"\n                        \"⏳ **Agora você precisa aguardar um recrutador aprovar ou reprovar sua inscrição.** \"\n                        \"Por favor, vá até a **FAC 06** e fique aguardando lá até um recrutador chegar para conversar com você. Não é necessário entrar em nenhuma call.\\n\\n\"\n                        \"Você continua podendo conversar normalmente neste canal e responder às perguntas adicionais da equipe. \"\n                        \"Não abra outra inscrição enquanto aguarda.\\n\"\n                        f\"{staff.mention if staff else ''} {recruiter.mention if recruiter else ''}\"\n                    ),\n                    embed=embed, view=RecruitmentReviewView(),\n                )\n                # Publica respostas completas em partes para os recrutadores avaliarem.\n                answer_lines = []\n                for item in answers:\n                    answer_lines.append(f\"**{item['question']}**\\n{item['answer']}\")\n                chunk = \"\"\n                for line in answer_lines:\n                    candidate_text = (chunk + \"\\n\\n\" + line).strip()\n                    if len(candidate_text) > 1850:\n                        if chunk:\n                            await message.channel.send(chunk)\n                        chunk = line[:1850]\n                    else:\n                        chunk = candidate_text\n                if chunk:\n                    await message.channel.send(chunk)\n                if ai_reasons:\n                    try:\n                        await message.author.send(\n                            \"⚠️ Suas respostas apresentaram alguns padrões textuais que precisam de revisão. \"\n                            \"Isso **não comprova** uso de IA nem significa reprovação automática. Por favor, aguarde um superior analisar suas respostas.\"\n                        )\n                    except discord.Forbidden:\n                        pass\n                log_id = config_get(message.guild.id, \"logs_channel_id\")\n                log_channel = message.guild.get_channel(int(log_id)) if log_id and str(log_id).isdigit() else None\n                if isinstance(log_channel, discord.TextChannel) and log_channel.id != message.channel.id:\n                    await log_channel.send(\n                        f\"📝 Recrutamento concluído por {message.author.mention}: {message.channel.mention} — **{status}**. \"\n                        + (\"⚠️ Sinalização para revisão manual de texto possivelmente assistido por IA.\" if ai_reasons else \"\")\n                    )\n                return\n            with db() as con:\n                con.execute(\"UPDATE recruitment_sessions SET question_index=?, answers_json=? WHERE channel_id=?\", (index, json.dumps(answers, ensure_ascii=False), message.channel.id))\n            await message.channel.send(f\"**{RECRUITMENT_QUESTIONS[index]}**\")\n            return\n\n    await bot.process_commands(message)\n\n\n@bot.tree.command(name=\"instalar\", description=\"Configura cargos e categorias privadas do CAOS neste servidor.\")\n@app_commands.describe(cargo_equipe=\"Cargo de moderadores/superiores que poderá ver os canais privados\")\n@app_commands.checks.has_permissions(administrator=True)\nasync def instalar(interaction: discord.Interaction, cargo_equipe: discord.Role):\n    guild = interaction.guild\n    if guild is None:\n        return await interaction.response.send_message(\"Este comando deve ser usado em um servidor.\", ephemeral=True)\n    me = guild.me\n    if not me or not me.guild_permissions.manage_roles or not me.guild_permissions.manage_channels:\n        return await interaction.response.send_message(\"Preciso das permissões **Gerenciar cargos** e **Gerenciar canais**. Coloque o cargo do bot acima dos cargos que ele precisa atribuir.\", ephemeral=True)\n    await interaction.response.defer(ephemeral=True, thinking=True)\n    config_set(guild.id, \"staff_role_id\", cargo_equipe.id)\n    roles = [\n        (\"「🟢」ᴏɴʟɪɴᴇ\", \"role_online_id\", discord.Colour.from_rgb(28, 158, 76)),\n        (\"「🔴」ᴏꜰꜰʟɪɴᴇ\", \"role_offline_id\", discord.Colour.from_rgb(85, 85, 91)),\n        (\"「🎫」ᴀɢᴜᴀʀᴅᴀɴᴅᴏ ꜱᴜᴘᴏʀᴛᴇ\", \"role_support_id\", discord.Colour.from_rgb(190, 105, 28)),\n        (\"「📦」ᴘᴇᴅɪᴜ ᴇɴᴄᴏᴍᴇɴᴅᴀ\", \"role_order_id\", discord.Colour.from_rgb(165, 22, 30)),\n        (\"「🤝」ᴘᴀʀᴄᴇʀɪᴀ\", \"role_partner_id\", discord.Colour.from_rgb(104, 66, 150)),\n    ]\n    created_roles = []\n    for name, key, colour in roles:\n        role = await ensure_role(guild, name, key, colour)\n        created_roles.append(role.name)\n    categories = [\n        (\"「🎫」ᴛɪᴄᴋᴇᴛꜱ\", \"ticket_category_id\"),\n        (\"「📦」ᴇɴᴄᴏᴍᴇɴᴅᴀꜱ・ᴘᴀʀᴄᴇʀɪᴀꜱ\", \"order_category_id\"),\n        (\"「📝」ʀᴇᴄʀᴜᴛᴀᴍᴇɴᴛᴏ\", \"recruitment_category_id\"),\n        (\"「🎯」ᴍᴇᴛᴀꜱ\", \"goals_category_id\"),\n    ]\n    created_categories = []\n    for name, key in categories:\n        category = await ensure_category(guild, name, key, cargo_equipe)\n        config_set(guild.id, key, category.id)\n        created_categories.append(category.name)\n    await interaction.followup.send(\n        \"✅ **CAOS configurado neste servidor!**\\n\\n\"\n        \"**Cargos criados/verificados:**\\n\" + \"\\n\".join(f\"• {name}\" for name in created_roles) +\n        \"\\n\\n**Categorias privadas criadas/verificadas:**\\n\" + \"\\n\".join(f\"• {name}\" for name in created_categories) +\n        \"\\n\\nAgora publique cada painel separadamente usando seu próprio comando de barra. Use `/configurar_logs` para escolher o canal de registros.\",\n        ephemeral=True,\n    )\n\n\n@bot.tree.command(name=\"configurar_logs\", description=\"Define o canal de registros e transcrições antes de apagar canais.\")\n@app_commands.checks.has_permissions(administrator=True)\nasync def configurar_logs(interaction: discord.Interaction, canal: discord.TextChannel):\n    if not interaction.guild:\n        return await interaction.response.send_message(\"Use em um servidor.\", ephemeral=True)\n    config_set(interaction.guild.id, \"logs_channel_id\", canal.id)\n    await interaction.response.send_message(f\"✅ Canal de registros definido: {canal.mention}.\", ephemeral=True)\n\n\nasync def publish_individual_panel(\n    interaction: discord.Interaction,\n    canal: discord.TextChannel,\n    title: str,\n    description: str,\n    view: discord.ui.View,\n    panel_art: str,\n):\n    if not interaction.guild:\n        return await interaction.response.send_message(\"Use este comando dentro de um servidor.\", ephemeral=True)\n    enabled_panel = (module_enabled(\"orders\") or module_enabled(\"partnerships\")) if panel_art == \"requests\" else panel_module_enabled(panel_art)\n    if not enabled_panel:\n        return await interaction.response.send_message(\"Este painel está desativado nas opções do Bot Pronto.\", ephemeral=True)\n    if not config_get(interaction.guild.id, \"staff_role_id\"):\n        return await interaction.response.send_message(\n            \"Antes de publicar os painéis, um administrador precisa executar `/instalar`.\",\n            ephemeral=True,\n        )\n    embed = discord.Embed(\n        title=title,\n        description=description,\n        colour=discord.Colour.from_rgb(22, 126, 220),\n    )\n    embed.set_author(name=\"♛ ᴄᴀᴏꜱ  •  ᴜʀʙᴀɴ ᴅɪᴠɪꜱɪᴏɴ\")\n    embed.set_footer(text=\"「 CAOS 」 • ᴘᴀɪɴᴇʟ ɪɴᴅᴇᴘᴇɴᴅᴇɴᴛᴇ  •  ʀᴇᴅ / ʙʟᴀᴄᴋ\")\n    await interaction.response.defer(ephemeral=True, thinking=True)\n    await send_artifact(canal, embed=embed, view=view, panel=panel_art)\n    await interaction.followup.send(f\"✅ Painel **{title}** publicado em {canal.mention}.\", ephemeral=True)\n\n\n@bot.tree.command(name=\"painel_ticket\", description=\"Publica somente o painel de abertura de tickets.\")\n@app_commands.checks.has_permissions(administrator=True)\n@app_commands.describe(canal=\"Canal onde o painel de tickets será publicado\")\nasync def painel_ticket(interaction: discord.Interaction, canal: discord.TextChannel):\n    await publish_individual_panel(\n        interaction, canal, \"「🎫」ᴄᴇɴᴛʀᴀʟ ᴅᴇ ꜱᴜᴘᴏʀᴛᴇ\",\n        \"ᴜᴍ ᴇꜱᴘᴀçᴏ ᴘʀɪᴠᴀᴅᴏ ᴘᴀʀᴀ ᴀᴛᴇɴᴅɪᴍᴇɴᴛᴏ. ᴄʟɪǫᴜᴇ ᴀʙᴀɪxᴏ ᴘᴀʀᴀ ᴄʜᴀᴍᴀʀ ᴀ ᴇǫᴜɪᴘᴇ.\",\n        TicketPanelView(), \"ticket\",\n    )\n\n\n@bot.tree.command(name=\"painel_ponto\", description=\"Publica somente o painel de bater ponto e ranking.\")\n@app_commands.checks.has_permissions(administrator=True)\n@app_commands.describe(canal=\"Canal onde o painel de ponto será publicado\")\nasync def painel_ponto(interaction: discord.Interaction, canal: discord.TextChannel):\n    await publish_individual_panel(\n        interaction, canal, \"「⏱」ᴄᴏɴᴛʀᴏʟᴇ ᴅᴇ ᴘᴏɴᴛᴏ\",\n        \"O ponto inicia ao entrar na call monitorada configurada, encerra ao sair e envia lembretes privados a cada 3 horas.\",\n        PointControlView(), \"point\",\n    )\n\n\n@bot.tree.command(name=\"painel_metas\", description=\"Publica somente o painel de entrega de metas.\")\n@app_commands.checks.has_permissions(administrator=True)\n@app_commands.describe(canal=\"Canal onde o painel de metas será publicado\")\nasync def painel_metas(interaction: discord.Interaction, canal: discord.TextChannel):\n    await publish_individual_panel(\n        interaction, canal, \"「🎯」ᴇɴᴛʀᴇɢᴀ ᴅᴇ ᴍᴇᴛᴀꜱ\",\n        \"ɪɴғᴏʀᴍᴇ ɪᴅ, ɴᴏᴍᴇ, ᴍᴇᴛᴀ ᴇ ǫᴜᴀɴᴛɪᴅᴀᴅᴇ. ᴇɴᴠɪᴇ ᴏ ᴄᴏᴍᴘʀᴏᴠᴀɴᴛᴇ ɴᴏ ᴄᴀɴᴀʟ ᴘʀɪᴠᴀᴅᴏ.\",\n        GoalPanelView(), \"goals\",\n    )\n\n\n@bot.tree.command(name=\"painel_recrutamento\", description=\"Publica somente o painel de recrutamento.\")\n@app_commands.checks.has_permissions(administrator=True)\n@app_commands.describe(canal=\"Canal onde o painel de recrutamento será publicado\")\nasync def painel_recrutamento(interaction: discord.Interaction, canal: discord.TextChannel):\n    await publish_individual_panel(\n        interaction, canal, \"「📝」ʀᴇᴄʀᴜᴛᴀᴍᴇɴᴛᴏ ᴄᴀᴏꜱ\",\n        \"ᴘʀᴇᴇɴᴄʜᴀ ᴀ ɪɴꜱᴄʀɪçãᴏ ᴘʀɪᴠᴀᴅᴀ ᴇ ʀᴇꜱᴘᴏɴᴅᴀ ᴀᴏ ǫᴜᴇꜱᴛɪᴏɴáʀɪᴏ ᴅᴀ ᴇǫᴜɪᴘᴇ.\",\n        RecruitmentPanelView(), \"recruitment\",\n    )\n\n\n@bot.tree.command(name=\"painel_encomendas\", description=\"Publica somente o painel de encomendas e parcerias.\")\n@app_commands.checks.has_permissions(administrator=True)\n@app_commands.describe(canal=\"Canal onde o painel de encomendas e parcerias será publicado\")\nasync def painel_encomendas(interaction: discord.Interaction, canal: discord.TextChannel):\n    if not (module_enabled(\"orders\") or module_enabled(\"partnerships\")):\n        return await interaction.response.send_message(\"Encomendas e parcerias estão desativadas neste bot.\", ephemeral=True)\n    await publish_individual_panel(\n        interaction, canal, \"「📦」ᴇɴᴄᴏᴍᴇɴᴅᴀꜱ & ᴘᴀʀᴄᴇʀɪᴀꜱ\",\n        \"ᴇꜱᴄᴏʟʜᴀ ᴇɴᴄᴏᴍᴇɴᴅᴀ ᴏᴜ ᴘᴀʀᴄᴇʀɪᴀ. ᴏ ᴄᴀᴏꜱ ᴄʀɪᴀʀá ᴜᴍ ᴄᴀɴᴀʟ ᴘʀɪᴠᴀᴅᴏ ᴇ ᴀᴘʟɪᴄᴀʀá ᴏ ᴄᴀʀɢᴏ.\",\n        RequestPanelView(), \"requests\",\n    )\n\n\n@bot.tree.command(name=\"painel_regras_discord\", description=\"Publica somente o painel das regras do Discord.\")\n@app_commands.checks.has_permissions(administrator=True)\n@app_commands.describe(canal=\"Canal onde o painel das regras do Discord será publicado\")\nasync def painel_regras_discord(interaction: discord.Interaction, canal: discord.TextChannel):    await publish_individual_panel(\n        interaction, canal, \"「📜」ʀᴇɢʀᴀꜱ ᴅᴏ ᴅɪꜱᴄᴏʀᴅ\",\n        \"ʀᴇᴄᴇʙᴀ ᴏ ʀᴇɢᴜʟᴀᴍᴇɴᴛᴏ ᴄᴏᴍᴘʟᴇᴛᴏ ᴅɪʀᴇᴛᴀᴍᴇɴᴛᴇ ɴᴏ ᴘᴠ.\",\n        RulesPanelView(\"discord\"), \"rules_discord\",\n    )\n\n\n@bot.tree.command(name=\"painel_regras_equipe\", description=\"Publica somente o painel das regras da equipe.\")\n@app_commands.checks.has_permissions(administrator=True)\n@app_commands.describe(canal=\"Canal onde o painel das regras da equipe será publicado\")\nasync def painel_regras_equipe(interaction: discord.Interaction, canal: discord.TextChannel):\n    await publish_individual_panel(\n        interaction, canal, \"「👥」ʀᴇɢʀᴀꜱ ᴅᴀ ᴇǫᴜɪᴘᴇ\",\n        \"ᴅɪꜱᴄɪᴘʟɪɴᴀ, ʜɪᴇʀᴀʀǫᴜɪᴀ ᴇ ʀᴇꜱᴘᴏɴꜱᴀʙɪʟɪᴅᴀᴅᴇ. ʀᴇᴄᴇʙᴀ ᴏ ᴛᴇxᴛᴏ ɴᴏ ᴘᴠ.\",\n        RulesPanelView(\"equipe\"), \"rules_team\",\n    )\n\n\n@bot.tree.command(name=\"painel_regras_rp\", description=\"Publica somente o painel das regras de RP.\")\n@app_commands.checks.has_permissions(administrator=True)\n@app_commands.describe(canal=\"Canal onde o painel das regras de RP será publicado\")\nasync def painel_regras_rp(interaction: discord.Interaction, canal: discord.TextChannel):\n    await publish_individual_panel(\n        interaction, canal, \"「🚔」ʀᴇɢʀᴀꜱ ᴅᴇ ʀᴘ\",\n        \"ʀᴘ, ᴀçõᴇꜱ ᴇ ʟᴏᴊɪɴʜᴀꜱ ᴇᴍ ᴜᴍ ꜱó ʟᴜɢᴀʀ. ʀᴇᴄᴇʙᴀ ᴏ ʀᴇꜱᴜᴍᴏ ɴᴏ ᴘᴠ.\",\n        RulesPanelView(\"rp\"), \"rules_rp\",\n    )\n\n\n\n# ---------------------------------------------------------------------------\n# Painel privado para copiar o histórico de um canal para outro servidor\n# ---------------------------------------------------------------------------\n\nCOPY_PANEL_PAGE_SIZE = 25\n\n\ndef _copy_split_text(value: str, limit: int = 1850) -> list[str]:\n    \"\"\"Divide conteúdo em partes seguras para o limite de mensagens do Discord.\"\"\"\n    text = str(value or \"\").strip()\n    if not text:\n        return []\n    parts: list[str] = []\n    while len(text) > limit:\n        cut = text.rfind(\"\\n\", 0, limit)\n        if cut < limit // 2:\n            cut = text.rfind(\" \", 0, limit)\n        if cut < limit // 2:\n            cut = limit\n        parts.append(text[:cut].rstrip())\n        text = text[cut:].lstrip()\n    if text:\n        parts.append(text)\n    return parts\n\n\nasync def _copy_get_member(guild: discord.Guild, user_id: int) -> Optional[discord.Member]:\n    member = guild.get_member(user_id)\n    if member is not None:\n        return member\n    try:\n        return await guild.fetch_member(user_id)\n    except (discord.NotFound, discord.Forbidden, discord.HTTPException):\n        return None\n\n\ndef _copy_bot_member(guild: discord.Guild) -> Optional[discord.Member]:\n    if bot.user is None:\n        return None\n    return guild.me or guild.get_member(bot.user.id)\n\n\ndef _copy_source_channels(guild: discord.Guild, user: discord.Member) -> list[discord.TextChannel]:\n    bot_member = _copy_bot_member(guild)\n    if bot_member is None:\n        return []\n    channels = []\n    for channel in guild.text_channels:\n        bot_perms = channel.permissions_for(bot_member)\n        user_perms = channel.permissions_for(user)\n        if (bot_perms.view_channel and bot_perms.read_message_history\n                and user_perms.view_channel and user_perms.read_message_history):\n            channels.append(channel)\n    return sorted(channels, key=lambda item: (item.position, item.name.casefold()))\n\n\ndef _copy_target_channels(guild: discord.Guild, user: discord.Member) -> list[discord.TextChannel]:\n    bot_member = _copy_bot_member(guild)\n    if bot_member is None:\n        return []\n    channels = []\n    for channel in guild.text_channels:\n        bot_perms = channel.permissions_for(bot_member)\n        user_perms = channel.permissions_for(user)\n        if (bot_perms.view_channel and bot_perms.send_messages\n                and user_perms.view_channel and user_perms.send_messages):\n            channels.append(channel)\n    return sorted(channels, key=lambda item: (item.position, item.name.casefold()))\n\n\nasync def _copy_one_message(\n    source_message: discord.Message,\n    destination: discord.TextChannel,\n) -> tuple[bool, int, int, bool, bool]:\n    \"\"\"Copia texto, embeds e anexos sem impersonar o autor original.\n\n    Retorna: (copiou algo, anexos enviados, anexos como link, erro fatal, falha parcial).\n    \"\"\"\n    source_author = discord.utils.escape_markdown(\n        getattr(source_message.author, \"display_name\", None)\n        or getattr(source_message.author, \"name\", \"Usuário\")\n    )[:90]\n    created = source_message.created_at.strftime(\"%d/%m/%Y %H:%M UTC\")\n    header = f\"📩 **{source_author}** · `{created}`\\n\"\n    body = (source_message.content or \"\").strip()\n\n    # Quando um serviço gera apenas uma prévia incorporada, preserva título,\n    # descrição e URL como texto copiável no destino.\n    if not body and source_message.embeds:\n        embed_parts = []\n        for item in source_message.embeds:\n            if item.title:\n                embed_parts.append(f\"**{item.title[:250]}**\")\n            if item.description:\n                embed_parts.append(item.description[:1500])\n            if item.url:\n                embed_parts.append(item.url)\n        body = \"\\n\".join(embed_parts).strip()\n\n    text_parts = _copy_split_text(body, max(500, 1950 - len(header)))\n    sent_any = False\n    uploaded_files = 0\n    fallback_files = 0\n    error_occurred = False\n    bot_member = _copy_bot_member(destination.guild)\n    bot_perms = destination.permissions_for(bot_member) if bot_member else None\n    can_attach = bool(bot_perms and bot_perms.attach_files)\n    max_file_size = getattr(destination.guild, \"filesize_limit\", 8 * 1024 * 1024)\n\n    # Primeiro preserva o texto original e os links existentes na mensagem.\n    for index, part in enumerate(text_parts):\n        prefix = header if index == 0 else f\"↪ Continuação de {source_author}:\\n\"\n        try:\n            await destination.send(\n                content=(prefix + part)[:2000],\n                allowed_mentions=discord.AllowedMentions.none(),\n            )\n            sent_any = True\n        except discord.Forbidden:\n            return sent_any, uploaded_files, fallback_files, True, True\n        except discord.HTTPException:\n            error_occurred = True\n\n    # Envia cada arquivo individualmente para não carregar dezenas de vídeos\n    # grandes na memória ao mesmo tempo. Quando o limite do destino impede o\n    # upload, preserva o URL original no canal de destino.\n    fallback_urls: list[str] = []\n    for attachment in source_message.attachments:\n        file_label = discord.utils.escape_markdown(attachment.filename or \"arquivo\")[:140]\n        if not can_attach or attachment.size > max_file_size:\n            fallback_urls.append(f\"📎 **{file_label}** — {attachment.url}\")\n            fallback_files += 1\n            continue\n        try:\n            raw = await attachment.read()\n            upload = discord.File(\n                io.BytesIO(raw),\n                filename=attachment.filename or \"anexo\",\n                spoiler=attachment.is_spoiler(),\n            )\n            try:\n                await destination.send(\n                    content=(f\"📎 **{file_label}**\\n{header.strip()}\" if not sent_any else f\"📎 **{file_label}** · de {source_author}\"),\n                    file=upload,\n                    allowed_mentions=discord.AllowedMentions.none(),\n                )\n                sent_any = True\n                uploaded_files += 1\n            except discord.Forbidden:\n                return sent_any, uploaded_files, fallback_files, True, True\n            except discord.HTTPException:\n                error_occurred = True\n                fallback_urls.append(f\"📎 **{file_label}** — {attachment.url}\")\n                fallback_files += 1\n        except (discord.HTTPException, OSError, ValueError):\n            fallback_urls.append(f\"📎 **{file_label}** — {attachment.url}\")\n            fallback_files += 1\n\n    if fallback_urls:\n        for part in _copy_split_text(\"\\n\".join(fallback_urls), 1800):\n            try:\n                await destination.send(\n                    content=f\"🔗 **Anexos disponíveis no link original**\\n{part}\"[:2000],\n                    allowed_mentions=discord.AllowedMentions.none(),\n                )\n                sent_any = True\n            except discord.Forbidden:\n                return sent_any, uploaded_files, fallback_files, True, True\n            except discord.HTTPException:\n                error_occurred = True\n\n    # Mensagens com stickers sem texto/anexo também deixam uma referência.\n    if not sent_any and source_message.stickers:\n        sticker_lines = [f\"🎟️ Figurinha: {sticker.name} — {sticker.url}\" for sticker in source_message.stickers]\n        try:\n            await destination.send(\n                content=(header + \"\\n\".join(sticker_lines))[:2000],\n                allowed_mentions=discord.AllowedMentions.none(),\n            )\n            sent_any = True\n        except discord.Forbidden:\n            return sent_any, uploaded_files, fallback_files, True, True\n        except discord.HTTPException:\n            error_occurred = True\n\n    return sent_any, uploaded_files, fallback_files, False, error_occurred\n\n\nasync def _copy_channel_history(\n    source: discord.TextChannel,\n    destination: discord.TextChannel,\n    interaction: discord.Interaction,\n) -> dict:\n    scanned = copied = failed = uploaded = fallback = skipped = 0\n    last_update = asyncio.get_running_loop().time()\n    try:\n        async for original in source.history(limit=None, oldest_first=True):\n            scanned += 1\n            try:\n                did_copy, files_ok, files_as_links, fatal, had_error = await _copy_one_message(original, destination)\n                uploaded += files_ok\n                fallback += files_as_links\n                if did_copy:\n                    copied += 1\n                if had_error:\n                    failed += 1\n                elif not did_copy:\n                    if not original.content and not original.attachments and not original.embeds and not original.stickers:\n                        skipped += 1\n                    else:\n                        failed += 1\n                if fatal:\n                    if not had_error:\n                        failed += 1\n                    break\n            except (discord.HTTPException, OSError, ValueError) as exc:\n                failed += 1\n                logger.warning(\"Falha ao copiar mensagem %s do canal %s: %s\", original.id, source.id, str(exc)[:200])\n\n            now = asyncio.get_running_loop().time()\n            if scanned % 20 == 0 or now - last_update >= 20:\n                try:\n                    await interaction.edit_original_response(\n                        content=(\n                            \"📦 **Cópia em andamento**\\n\"\n                            f\"Origem: **{source.guild.name} / #{source.name}**\\n\"\n                            f\"Destino: **{destination.guild.name} / #{destination.name}**\\n\"\n                            f\"Mensagens verificadas: **{scanned}** · copiadas: **{copied}** · falhas: **{failed}**\\n\"\n                            f\"Arquivos enviados: **{uploaded}** · mantidos como link: **{fallback}**\"\n                        ),\n                        view=None,\n                    )\n                except (discord.HTTPException, discord.NotFound):\n                    # A cópia continua mesmo se a resposta efêmera expirar.\n                    pass\n                last_update = now\n    except (discord.Forbidden, discord.HTTPException) as exc:\n        logger.warning(\"Falha ao ler histórico do canal %s: %s\", source.id, str(exc)[:250])\n        failed += 1\n\n    return {\n        \"scanned\": scanned, \"copied\": copied, \"failed\": failed,\n        \"uploaded\": uploaded, \"fallback\": fallback, \"skipped\": skipped,\n    }\n\n\nclass CopyPanelSelect(discord.ui.Select):\n    def __init__(self, view: \"CopyPanelView\", stage: str, options: list[discord.SelectOption]):\n        placeholder = {\n            \"source_guild\": \"1. Escolha o servidor de origem\",\n            \"source_channel\": \"2. Escolha o canal que será copiado\",\n            \"target_guild\": \"3. Escolha o servidor de destino\",\n            \"target_channel\": \"4. Escolha o canal que receberá a cópia\",\n        }.get(stage, \"Escolha uma opção\")\n        super().__init__(placeholder=placeholder, min_values=1, max_values=1, options=options[:COPY_PANEL_PAGE_SIZE], row=0)\n        self.stage = stage\n\n    async def callback(self, interaction: discord.Interaction):\n        view: CopyPanelView = self.view  # type: ignore[assignment]\n        await view.handle_selection(interaction, self.stage, int(self.values[0]))\n\n\nclass CopyPanelView(discord.ui.View):\n    def __init__(self, owner_id: int):\n        super().__init__(timeout=900)\n        self.owner_id = owner_id\n        self.stage = \"source_guild\"\n        self.page = 0\n        self.options: list[tuple[str, int, str]] = []\n        self.prompt = \"Escolha o servidor de origem onde o CAOS já está instalado.\"\n        self.source_guild: Optional[discord.Guild] = None\n        self.source_member: Optional[discord.Member] = None\n        self.source_channel: Optional[discord.TextChannel] = None\n        self.target_guild: Optional[discord.Guild] = None\n        self.target_member: Optional[discord.Member] = None\n        self.target_channel: Optional[discord.TextChannel] = None\n        self._set_guild_options(\"source_guild\")\n        self._render_components()\n\n    async def interaction_check(self, interaction: discord.Interaction) -> bool:\n        if interaction.user.id != self.owner_id:\n            await interaction.response.send_message(\"🔒 Este painel de cópia é privado e só pode ser usado por quem o abriu.\", ephemeral=True)\n            return False\n        return True\n\n    def _set_guild_options(self, stage: str) -> None:\n        self.stage = stage\n        guilds = sorted(bot.guilds, key=lambda item: item.name.casefold())\n        self.options = [(guild.name, guild.id, f\"{guild.member_count or '?'} membros\") for guild in guilds]\n        self.page = 0\n        self.prompt = (\"Escolha o servidor de origem. O CAOS precisa estar nele e ter acesso ao canal.\"\n                       if stage == \"source_guild\" else\n                       \"Escolha o servidor de destino. O CAOS também precisa estar nele para publicar a cópia.\")\n\n    def _render_components(self) -> None:\n        self.clear_items()\n        if self.stage == \"confirm\":\n            button = discord.ui.Button(label=\"Confirmar e copiar tudo\", emoji=\"📥\", style=discord.ButtonStyle.success, row=0)\n            button.callback = self.start_copy\n            self.add_item(button)\n            cancel = discord.ui.Button(label=\"Cancelar\", emoji=\"✖️\", style=discord.ButtonStyle.secondary, row=0)\n            cancel.callback = self.cancel\n            self.add_item(cancel)\n            return\n\n        page_count = max(1, (len(self.options) + COPY_PANEL_PAGE_SIZE - 1) // COPY_PANEL_PAGE_SIZE)\n        start = self.page * COPY_PANEL_PAGE_SIZE\n        current = self.options[start:start + COPY_PANEL_PAGE_SIZE]\n        select_options = [\n            discord.SelectOption(label=label[:100], value=str(value), description=(description[:100] or None))\n            for label, value, description in current\n        ]\n        if select_options:\n            self.add_item(CopyPanelSelect(self, self.stage, select_options))\n        if page_count > 1:\n            previous = discord.ui.Button(label=\"Anterior\", emoji=\"◀️\", style=discord.ButtonStyle.secondary, row=1, disabled=self.page == 0)\n            previous.callback = self.previous_page\n            self.add_item(previous)\n            following = discord.ui.Button(label=\"Próxima\", emoji=\"▶️\", style=discord.ButtonStyle.secondary, row=1, disabled=self.page >= page_count - 1)\n            following.callback = self.next_page\n            self.add_item(following)\n        cancel = discord.ui.Button(label=\"Cancelar\", emoji=\"✖️\", style=discord.ButtonStyle.secondary, row=1 if page_count > 1 else 1)\n        cancel.callback = self.cancel\n        self.add_item(cancel)\n\n    async def _edit(self, interaction: discord.Interaction):\n        self._render_components()\n        await interaction.response.edit_message(content=self.prompt, embed=self._summary_embed(), view=self)\n\n    def _summary_embed(self) -> Optional[discord.Embed]:\n        if self.stage != \"confirm\":\n            return None\n        embed = discord.Embed(\n            title=\"📦 Conferir cópia antes de iniciar\",\n            description=\"O CAOS publicará o conteúdo com o nome do autor e a data original. Ele não vai se passar pelos autores das mensagens.\",\n            colour=discord.Colour.from_rgb(38, 112, 190),\n        )\n        embed.add_field(name=\"Origem\", value=f\"**{self.source_guild.name}**\\n#{self.source_channel.name}\", inline=True)\n        embed.add_field(name=\"Destino\", value=f\"**{self.target_guild.name}**\\n#{self.target_channel.name}\", inline=True)\n        embed.add_field(name=\"O que será transferido\", value=\"Textos, links, imagens, anexos e vídeos que o bot consiga ler e reenviar. Arquivos acima do limite do destino serão mantidos como links quando possível.\", inline=False)\n        embed.set_footer(text=\"A mensagem original não será apagada nem alterada.\")\n        return embed\n\n    async def previous_page(self, interaction: discord.Interaction):\n        self.page = max(0, self.page - 1)\n        await self._edit(interaction)\n\n    async def next_page(self, interaction: discord.Interaction):\n        max_page = max(0, (len(self.options) - 1) // COPY_PANEL_PAGE_SIZE)\n        self.page = min(max_page, self.page + 1)\n        await self._edit(interaction)\n\n    async def cancel(self, interaction: discord.Interaction):\n        self.stop()\n        await interaction.response.edit_message(content=\"Cópia cancelada. Nenhuma mensagem foi alterada.\", embed=None, view=None)\n\n    async def handle_selection(self, interaction: discord.Interaction, stage: str, selected_id: int):\n        if stage == \"source_guild\":\n            guild = bot.get_guild(selected_id)\n            if guild is None:\n                return await interaction.response.send_message(\"Não encontrei esse servidor na lista do CAOS.\", ephemeral=True)\n            member = await _copy_get_member(guild, self.owner_id)\n            if member is None:\n                return await interaction.response.send_message(\"Você precisa ser membro do servidor de origem para copiar o conteúdo que consegue acessar.\", ephemeral=True)\n            channels = _copy_source_channels(guild, member)\n            if not channels:\n                return await interaction.response.send_message(\"Não encontrei canais de texto em que você e o CAOS tenham permissão de visualizar o histórico.\", ephemeral=True)\n            self.source_guild, self.source_member = guild, member\n            self.options = [(f\"#{channel.name}\", channel.id, f\"Categoria: {channel.category.name if channel.category else 'Sem categoria'}\") for channel in channels]\n            self.stage, self.page = \"source_channel\", 0\n            self.prompt = f\"Origem selecionada: **{guild.name}**. Agora escolha o canal que será copiado.\"\n            return await self._edit(interaction)\n\n        if stage == \"source_channel\":\n            channel = self.source_guild.get_channel(selected_id) if self.source_guild else None\n            if not isinstance(channel, discord.TextChannel):\n                return await interaction.response.send_message(\"O canal de origem não está mais disponível.\", ephemeral=True)\n            self.source_channel = channel\n            self._set_guild_options(\"target_guild\")\n            return await self._edit(interaction)\n\n        if stage == \"target_guild\":\n            guild = bot.get_guild(selected_id)\n            if guild is None:\n                return await interaction.response.send_message(\"Não encontrei esse servidor na lista do CAOS.\", ephemeral=True)\n            member = await _copy_get_member(guild, self.owner_id)\n            if member is None:\n                return await interaction.response.send_message(\"Você precisa ser membro do servidor de destino.\", ephemeral=True)\n            channels = _copy_target_channels(guild, member)\n            if not channels:\n                return await interaction.response.send_message(\"Não encontrei canais em que você e o CAOS possam enviar mensagens.\", ephemeral=True)\n            self.target_guild, self.target_member = guild, member\n            self.options = [(f\"#{channel.name}\", channel.id, f\"Categoria: {channel.category.name if channel.category else 'Sem categoria'}\") for channel in channels]\n            self.stage, self.page = \"target_channel\", 0\n            self.prompt = f\"Destino selecionado: **{guild.name}**. Escolha onde a cópia será publicada.\"\n            return await self._edit(interaction)\n\n        if stage == \"target_channel\":\n            channel = self.target_guild.get_channel(selected_id) if self.target_guild else None\n            if not isinstance(channel, discord.TextChannel):\n                return await interaction.response.send_message(\"O canal de destino não está mais disponível.\", ephemeral=True)\n            if self.source_channel and channel.id == self.source_channel.id:\n                return await interaction.response.send_message(\"Escolha um canal diferente do canal de origem.\", ephemeral=True)\n            self.target_channel = channel\n            self.stage = \"confirm\"\n            self.prompt = \"Confira a origem e o destino. A cópia só começa depois que você confirmar.\"\n            return await self._edit(interaction)\n\n    async def start_copy(self, interaction: discord.Interaction):\n        if not all((self.source_guild, self.source_channel, self.target_guild, self.target_channel)):\n            return await interaction.response.send_message(\"Selecione a origem e o destino antes de iniciar.\", ephemeral=True)\n        source_bot_member = _copy_bot_member(self.source_guild)\n        target_bot_member = _copy_bot_member(self.target_guild)\n        source_user = await _copy_get_member(self.source_guild, self.owner_id)\n        target_user = await _copy_get_member(self.target_guild, self.owner_id)\n        source_bot_perms = self.source_channel.permissions_for(source_bot_member) if source_bot_member else None\n        target_bot_perms = self.target_channel.permissions_for(target_bot_member) if target_bot_member else None\n        source_user_perms = self.source_channel.permissions_for(source_user) if source_user else None\n        target_user_perms = self.target_channel.permissions_for(target_user) if target_user else None\n        if not source_user_perms or not source_user_perms.view_channel or not source_user_perms.read_message_history:\n            return await interaction.response.send_message(\"Você não tem mais permissão para visualizar o histórico do canal de origem.\", ephemeral=True)\n        if not target_user_perms or not target_user_perms.view_channel or not target_user_perms.send_messages:\n            return await interaction.response.send_message(\"Você não tem mais permissão para enviar mensagens no canal de destino.\", ephemeral=True)\n        if not source_bot_perms or not source_bot_perms.view_channel or not source_bot_perms.read_message_history:\n            return await interaction.response.send_message(\"O CAOS perdeu a permissão de ler o histórico do canal de origem.\", ephemeral=True)\n        if not target_bot_perms or not target_bot_perms.view_channel or not target_bot_perms.send_messages:\n            return await interaction.response.send_message(\"O CAOS não tem permissão para enviar mensagens no canal de destino.\", ephemeral=True)\n        self.stop()\n        await interaction.response.defer(ephemeral=True, thinking=True)\n        try:\n            result = await _copy_channel_history(self.source_channel, self.target_channel, interaction)\n            summary = (\n                \"✅ **Cópia concluída**\\n\"\n                f\"Origem: **{self.source_guild.name} / #{self.source_channel.name}**\\n\"\n                f\"Destino: **{self.target_guild.name} / #{self.target_channel.name}**\\n\\n\"\n                f\"Mensagens verificadas: **{result['scanned']}**\\n\"\n                f\"Mensagens copiadas: **{result['copied']}**\\n\"\n                f\"Arquivos enviados: **{result['uploaded']}**\\n\"\n                f\"Arquivos mantidos como links: **{result['fallback']}**\\n\"\n                f\"Mensagens ignoradas: **{result['skipped']}** · falhas: **{result['failed']}**\\n\\n\"\n                \"A cópia não apagou nem alterou as mensagens originais.\"\n            )\n            await interaction.edit_original_response(content=summary, embed=None, view=None)\n        except Exception as exc:\n            logger.exception(\"Erro inesperado ao copiar o canal %s\", self.source_channel.id)\n            try:\n                await interaction.edit_original_response(\n                    content=f\"⚠️ A cópia foi interrompida por um erro: {type(exc).__name__}. Confira o log do CAOS.\",\n                    embed=None, view=None,\n                )\n            except discord.HTTPException:\n                pass\n\n\n@bot.tree.command(name=\"painel_copiar\", description=\"Abre o painel privado para copiar um canal entre servidores.\")\n@app_commands.guild_only()\nasync def painel_copiar(interaction: discord.Interaction):\n    # Bot.is_owner verifica a pessoa proprietária da aplicação do CAOS (não apenas\n    # administradores do servidor). Assim o painel não fica liberado aos membros.\n    if not await bot.is_owner(interaction.user):\n        return await interaction.response.send_message(\n            \"🔒 Este comando é exclusivo do proprietário da aplicação do CAOS.\", ephemeral=True\n        )\n    if len(bot.guilds) < 1:\n        return await interaction.response.send_message(\"O CAOS ainda não está em nenhum servidor.\", ephemeral=True)\n    view = CopyPanelView(interaction.user.id)\n    await interaction.response.send_message(\n        \"🔐 **PAINEL PRIVADO — CÓPIA ENTRE SERVIDORES**\\n\\n\"\n        \"Escolha o servidor de origem e o canal. Depois escolha o destino e confirme.\\n\"\n        \"O CAOS só mostra canais em que você e o bot têm permissão para ler ou publicar.\",\n        view=view,\n        ephemeral=True,\n    )\n\n\n# Gerenciador interativo único para publicar painéis em canais diferentes.\nPANEL_MANAGER_DEFINITIONS = {\n    \"ticket\": (\"Central de suporte\", \"Clique abaixo para abrir um atendimento privado com a equipe.\", TicketPanelView, \"ticket\"),\n    \"point\": (\"Controle de bate-ponto\", \"O ponto inicia ao entrar na call monitorada, encerra ao sair e envia lembretes a cada 3 horas.\", PointControlView, \"point\"),\n    \"goals\": (\"Entrega de metas\", \"Informe os dados da meta e anexe a foto de comprovação.\", GoalPanelView, \"goals\"),\n    \"recruitment\": (\"Recrutamento CAOS\", \"Inicie sua inscrição privada e responda às 23 perguntas do recrutamento.\", RecruitmentPanelView, \"recruitment\"),\n    \"requests\": (\"Encomendas e parcerias\", \"Escolha o tipo de solicitação para abrir um canal privado.\", RequestPanelView, \"requests\"),\n    \"rules_discord\": (\"Regras do Discord\", \"Receba o regulamento completo do Discord no privado.\", lambda: RulesPanelView(\"discord\"), \"rules_discord\"),\n    \"rules_team\": (\"Regras da equipe\", \"Receba as regras da equipe no privado.\", lambda: RulesPanelView(\"equipe\"), \"rules_team\"),\n    \"rules_rp\": (\"Regras de RP\", \"Receba o resumo das regras de RP no privado.\", lambda: RulesPanelView(\"rp\"), \"rules_rp\"),\n    \"music\": (\"CAOS Music Player\", \"Pesquise músicas e use os controles de reprodução na call.\", MusicPanelView, \"music\"),\n}\n\n\nclass PanelManagerSelect(discord.ui.Select):\n    def __init__(self):\n        options = [\n            discord.SelectOption(label=definition[0], value=key, description=f\"Publicar painel: {definition[0]}\")\n            for key, definition in PANEL_MANAGER_DEFINITIONS.items()\n            if panel_module_enabled(key)\n        ]\n        if not options:\n            options = [discord.SelectOption(label=\"Nenhum painel ativo\", value=\"none\", description=\"Ative um módulo no painel do Estúdio\")]\n        super().__init__(placeholder=\"1. Escolha qual painel deseja publicar\", min_values=1, max_values=1, options=options, row=0)\n\n    async def callback(self, interaction: discord.Interaction):\n        view: PanelManagerView = self.view  # type: ignore[assignment]\n        if interaction.user.id != view.owner_id:\n            return await interaction.response.send_message(\"Somente quem abriu o gerenciador pode configurar estes painéis.\", ephemeral=True)\n        if self.values[0] == \"none\":\n            return await interaction.response.send_message(\"Nenhum módulo de painel está ativo neste bot. Ative os recursos no Estúdio e reinicie o bot.\", ephemeral=True)\n        view.selected_panel = self.values[0]\n        title = PANEL_MANAGER_DEFINITIONS[view.selected_panel][0]\n        await interaction.response.edit_message(\n            content=f\"Painel selecionado: **{title}**. Agora escolha o canal no menu abaixo e clique em **Definir nome e publicar**.\",\n            view=view,\n        )\n\n\nclass PanelManagerChannelSelect(discord.ui.ChannelSelect):\n    def __init__(self):\n        super().__init__(\n            placeholder=\"2. Escolha o canal onde o painel será publicado\",\n            min_values=1,\n            max_values=1,\n            channel_types=[discord.ChannelType.text],\n            row=1,\n        )\n\n    async def callback(self, interaction: discord.Interaction):\n        view: PanelManagerView = self.view  # type: ignore[assignment]\n        if interaction.user.id != view.owner_id:\n            return await interaction.response.send_message(\"Somente quem abriu o gerenciador pode configurar estes painéis.\", ephemeral=True)\n        selected = self.values[0]\n        if not isinstance(selected, discord.TextChannel):\n            return await interaction.response.send_message(\"Escolha um canal de texto deste servidor.\", ephemeral=True)\n        view.target_channel = selected\n        await interaction.response.edit_message(\n            content=f\"Canal selecionado: {selected.mention}. Escolha o painel e clique em **Definir nome e publicar**.\",\n            view=view,\n        )\n\n\nclass PanelTitleModal(discord.ui.Modal):\n    def __init__(self, owner_id: int, panel_key: str, channel_id: int):\n        self.owner_id = owner_id\n        self.panel_key = panel_key\n        self.channel_id = channel_id\n        default_title = PANEL_MANAGER_DEFINITIONS[panel_key][0]\n        super().__init__(title=\"Nome do painel\")\n        self.panel_title = discord.ui.TextInput(\n            label=\"Nome/título que aparecerá no painel\",\n            default=default_title[:100],\n            max_length=100,\n            required=True,\n        )\n        self.add_item(self.panel_title)\n\n    async def on_submit(self, interaction: discord.Interaction):\n        if interaction.user.id != self.owner_id:\n            return await interaction.response.send_message(\"Somente quem abriu o gerenciador pode publicar este painel.\", ephemeral=True)\n        guild = interaction.guild\n        if guild is None:\n            return await interaction.response.send_message(\"Use este formulário dentro do servidor.\", ephemeral=True)\n        channel = guild.get_channel(self.channel_id)\n        if not isinstance(channel, discord.TextChannel):\n            return await interaction.response.send_message(\"O canal escolhido não existe mais ou não é um canal de texto.\", ephemeral=True)\n        default_title, description, view_factory, art_key = PANEL_MANAGER_DEFINITIONS[self.panel_key]\n        custom_title = self.panel_title.value.strip() or default_title\n        embed = discord.Embed(\n            title=custom_title[:256],\n            description=description,\n            colour=discord.Colour.from_rgb(22, 126, 220),\n        )\n        embed.set_author(name=\"♛ ᴄᴀᴏꜱ • ᴜʀʙᴀɴ ᴅɪᴠɪꜱɪᴏɴ\")\n        embed.set_footer(text=\"「 CAOS 」 • ᴘᴀɪɴᴇʟ ᴄᴏɴꜰɪɢᴜʀᴀᴅᴏ ᴘᴇʟᴏ ɢᴇʀᴇɴᴄɪᴀᴅᴏʀ\")\n        try:\n            await send_artifact(channel, embed=embed, view=view_factory(), panel=art_key)\n        except discord.Forbidden:\n            return await interaction.response.send_message(\"Não tenho permissão para enviar mensagens nesse canal.\", ephemeral=True)\n        except discord.HTTPException as exc:\n            return await interaction.response.send_message(f\"O Discord não aceitou a publicação: {type(exc).__name__}.\", ephemeral=True)\n        await interaction.response.send_message(\n            f\"✅ Painel **{custom_title}** publicado em {channel.mention}. Escolha outro painel abaixo para continuar ou feche a mensagem quando terminar.\",\n            view=PanelManagerView(self.owner_id),\n            ephemeral=True,\n        )\n\n\nclass PanelManagerView(discord.ui.View):\n    def __init__(self, owner_id: int):\n        super().__init__(timeout=300)\n        self.owner_id = owner_id\n        self.selected_panel: Optional[str] = None\n        self.target_channel: Optional[discord.TextChannel] = None\n        self.add_item(PanelManagerSelect())\n        self.add_item(PanelManagerChannelSelect())\n        button = discord.ui.Button(label=\"Definir nome e publicar\", emoji=\"📌\", style=discord.ButtonStyle.success, row=2)\n        button.callback = self.open_title_modal\n        self.add_item(button)\n\n    async def interaction_check(self, interaction: discord.Interaction) -> bool:\n        if interaction.user.id != self.owner_id:\n            await interaction.response.send_message(\"Somente quem abriu o gerenciador pode usar estes controles.\", ephemeral=True)\n            return False\n        return True\n\n    async def open_title_modal(self, interaction: discord.Interaction):\n        if not self.selected_panel:\n            return await interaction.response.send_message(\"Primeiro escolha um painel no menu superior.\", ephemeral=True)\n        if self.target_channel is None:\n            return await interaction.response.send_message(\"Agora escolha o canal de texto onde deseja publicar.\", ephemeral=True)\n        await interaction.response.send_modal(PanelTitleModal(self.owner_id, self.selected_panel, self.target_channel.id))\n\n\n@bot.tree.command(name=\"gerar_paineis\", description=\"Abre um gerenciador para escolher painel, canal e título.\")\n@app_commands.checks.has_permissions(administrator=True)\nasync def gerar_paineis(interaction: discord.Interaction):\n    await interaction.response.send_message(\n        \"**Gerenciador de painéis CAOS**\\n\\n1. Escolha o painel.\\n2. Escolha o canal de texto.\\n3. Defina o título e publique.\\n\\nRepita o comando para configurar outro painel.\",\n        view=PanelManagerView(interaction.user.id),\n        ephemeral=True,\n    )\n\n\n@bot.tree.command(name=\"c\", description=\"Apaga todas as mensagens do canal atual.\")\n@app_commands.checks.has_permissions(manage_messages=True)\nasync def c(interaction: discord.Interaction):\n    channel = interaction.channel\n    if not isinstance(channel, (discord.TextChannel, discord.Thread)):\n        return await interaction.response.send_message(\"Use `/c` em um canal de texto ou thread.\", ephemeral=True)\n    await interaction.response.defer(ephemeral=True, thinking=True)\n    try:\n        deleted = await channel.purge(limit=None, bulk=True, reason=f\"Limpeza total solicitada por {interaction.user} ({interaction.user.id})\")\n    except discord.Forbidden:\n        return await interaction.followup.send(\"Não consegui limpar o canal. Preciso da permissão **Gerenciar mensagens**.\", ephemeral=True)\n    except discord.HTTPException as exc:\n        return await interaction.followup.send(f\"A limpeza foi interrompida pelo Discord: {type(exc).__name__}.\", ephemeral=True)\n    await interaction.followup.send(\n        f\"🧹 Limpeza concluída: **{len(deleted)} mensagens** apagadas de {channel.mention}. Mensagens antigas foram excluídas individualmente quando o Discord não permitiu exclusão em lote.\",\n        ephemeral=True,\n    )\n\n\n@bot.tree.command(name=\"entrar\", description=\"Faz o CAOS entrar em um canal de voz, mesmo que esteja vazio.\")\n@app_commands.describe(canal=\"Canal de voz no qual o bot deve entrar\")\nasync def entrar(interaction: discord.Interaction, canal: discord.VoiceChannel):\n    if not interaction.guild or not isinstance(interaction.user, discord.Member):\n        return await interaction.response.send_message(\"Use este comando dentro de um servidor.\", ephemeral=True)\n    staff = await staff_role(interaction.guild)\n    if not (interaction.user.guild_permissions.manage_guild or interaction.user.guild_permissions.administrator or (staff and staff in interaction.user.roles)):\n        return await interaction.response.send_message(\"Somente a equipe autorizada pode controlar a call do CAOS.\", ephemeral=True)\n    permissions = canal.permissions_for(interaction.guild.me)\n    if not permissions.connect or not permissions.speak:\n        return await interaction.response.send_message(\"Preciso das permissões **Conectar** e **Falar** nesse canal de voz.\", ephemeral=True)\n    await interaction.response.defer(ephemeral=True, thinking=True)\n    voice = interaction.guild.voice_client\n    try:\n        if voice and voice.is_connected():\n            await voice.move_to(canal)\n        else:\n            await canal.connect(self_mute=False, self_deaf=False)\n        await _set_voice_mode_normal(interaction.guild, canal)\n        await interaction.followup.send(\n            f\"🔊 Entrei em {canal.mention} e estou pronto para reproduzir áudio. \"\n            \"Posso ficar no canal mesmo sem outros membros.\", ephemeral=True\n        )\n    except discord.Forbidden:\n        await interaction.followup.send(\"Não tenho permissão para entrar nesse canal. Verifique Conectar e Falar.\", ephemeral=True)\n    except Exception as exc:\n        await interaction.followup.send(\n            f\"Não consegui entrar no canal: `{type(exc).__name__}: {str(exc)[:220]}`.\", ephemeral=True\n        )\n\n\n@bot.tree.command(name=\"sair\", description=\"Faz o CAOS sair do canal de voz atual.\")\nasync def sair(interaction: discord.Interaction):\n    if not interaction.guild or not isinstance(interaction.user, discord.Member):\n        return await interaction.response.send_message(\"Use em um servidor.\", ephemeral=True)\n    staff = await staff_role(interaction.guild)\n    if not (interaction.user.guild_permissions.manage_guild or interaction.user.guild_permissions.administrator or (staff and staff in interaction.user.roles)):\n        return await interaction.response.send_message(\"Somente a equipe autorizada pode controlar a call do CAOS.\", ephemeral=True)\n    voice = interaction.guild.voice_client\n    if not voice or not voice.is_connected():\n        return await interaction.response.send_message(\"Não estou conectado a um canal de voz.\", ephemeral=True)\n    MUSIC_QUEUES[interaction.guild_id] = []\n    MUSIC_CURRENT.pop(interaction.guild_id, None)\n    await voice.disconnect(force=True)\n    await interaction.response.send_message(\"🔇 Saí do canal de voz e limpei a fila de músicas.\", ephemeral=True)\n\n\n@bot.tree.command(name=\"painel_musica\", description=\"Publica o painel independente de música do CAOS.\")\n@app_commands.checks.has_permissions(administrator=True)\n@app_commands.describe(canal=\"Canal onde o painel de música será publicado\")\nasync def painel_musica(interaction: discord.Interaction, canal: discord.TextChannel):\n    await publish_individual_panel(\n        interaction, canal, \"「🎧」ᴄᴀᴏꜱ • ᴍᴜꜱɪᴄ ᴘʟᴀʏᴇʀ\",\n        \"🔎 **Pesquise por nome ou artista.** O CAOS mostra até cinco resultados com capa, duração e botão próprio para tocar.\\n\\n🎧 Ao escolher **TOCAR AGORA**, o CAOS entra na call e reproduz somente o áudio diretamente no canal de voz — não compartilha tela nem transmite vídeo.\\n\\n⏯️ Use os controles abaixo para pausar, retomar, pular, ver a fila e parar.\",\n        MusicPanelView(), \"music\",\n    )\n\n\n@bot.tree.command(name=\"musica\", description=\"Pesquisa músicas e mostra resultados com capa para escolher.\")\n@app_commands.describe(busca=\"Nome da música, artista ou trecho do título\")\nasync def musica(interaction: discord.Interaction, busca: app_commands.Range[str, 2, 100]):\n    await _music_search_response(interaction, busca)\n\n\n@bot.tree.command(name=\"pausar_musica\", description=\"Pausa a música que está tocando na sua call.\")\nasync def pausar_musica(interaction: discord.Interaction):\n    voice = await _music_control_check(interaction)\n    if voice is None:\n        return\n    if not voice.is_playing():\n        return await interaction.response.send_message(\"Não há música tocando para pausar.\", ephemeral=True)\n    voice.pause()\n    await interaction.response.send_message(\"⏸️ Música pausada.\", ephemeral=True)\n\n\n@bot.tree.command(name=\"retomar_musica\", description=\"Retoma a música pausada na sua call.\")\nasync def retomar_musica(interaction: discord.Interaction):\n    voice = await _music_control_check(interaction)\n    if voice is None:\n        return\n    if not voice.is_paused():\n        return await interaction.response.send_message(\"A música não está pausada.\", ephemeral=True)\n    voice.resume()\n    await interaction.response.send_message(\"▶️ Música retomada.\", ephemeral=True)\n\n\n@bot.tree.command(name=\"pular_musica\", description=\"Pula a música atual e inicia a próxima da fila.\")\nasync def pular_musica(interaction: discord.Interaction):\n    await _skip_music(interaction)\n\n\n@bot.tree.command(name=\"parar_musica\", description=\"Para a reprodução e limpa a fila da call.\")\nasync def parar_musica(interaction: discord.Interaction):\n    await _stop_music(interaction)\n\n\n@bot.tree.command(name=\"fila_musica\", description=\"Mostra a música atual e as próximas da fila.\")\nasync def fila_musica(interaction: discord.Interaction):\n    await _show_music_queue(interaction)\n\n\n@bot.tree.command(name=\"volume_musica\", description=\"Ajusta o volume do CAOS entre 0 e 100 por cento.\")\n@app_commands.describe(porcentagem=\"Volume entre 0 e 100\")\nasync def volume_musica(interaction: discord.Interaction, porcentagem: app_commands.Range[int, 0, 100]):\n    voice = await _music_control_check(interaction)\n    if voice is None:\n        return\n    volume = porcentagem / 100\n    MUSIC_VOLUME[interaction.guild_id] = volume\n    source = voice.source\n    if source is not None:\n        detail = \"Volume salvo e aplicado à próxima faixa (o FFmpeg já iniciou a codificação Opus desta faixa).\"\n    else:\n        detail = \"Volume salvo para a próxima faixa.\"\n    await interaction.response.send_message(\n        f\"🔊 Volume ajustado para **{porcentagem}%**. {detail}\", ephemeral=True\n    )\n\n\n@bot.tree.command(name=\"teste_som\", description=\"Toca um apito curto para testar se você escuta o CAOS na call.\")\nasync def teste_som(interaction: discord.Interaction):\n    if not interaction.guild or not isinstance(interaction.user, discord.Member):\n        return await interaction.response.send_message(\"Use este comando dentro de um servidor.\", ephemeral=True)\n    if not interaction.user.voice or not interaction.user.voice.channel:\n        return await interaction.response.send_message(\"Entre em um canal de voz antes do teste.\", ephemeral=True)\n    await interaction.response.defer(ephemeral=True, thinking=True)\n    voice, error = await _ensure_music_voice(interaction)\n    if error:\n        return await interaction.followup.send(error, ephemeral=True)\n    if voice.is_playing() or voice.is_paused():\n        return await interaction.followup.send(\n            \"Já existe uma faixa tocando. Pare a música antes do teste de som.\", ephemeral=True\n        )\n    raw_source = None\n    source = None\n    try:\n        ffmpeg_path = _resolve_ffmpeg_executable()\n        # Gera Opus pronto no FFmpeg: não depende da DLL libopus do discord.py.\n        raw_source = discord.FFmpegOpusAudio(\n            \"sine=frequency=660:duration=4\",\n            executable=ffmpeg_path,\n            bitrate=96,\n            before_options=\"-f lavfi\",\n            options=\"-af volume=0.85 -loglevel warning\",\n        )\n        source = _ManagedOpusSource(raw_source)\n        test_source = source  # captura estável; `source` será limpo da variável local após voice.play()\n        raw_source = None\n\n        def after_test(error):\n            if error:\n                logger.error(\"Teste de som do CAOS terminou com erro: %s\", error, exc_info=error)\n            else:\n                logger.info(\n                    \"Teste de som terminou: %s quadros Opus, %s bytes; %s cabeçalhos Ogg descartados.\",\n                    test_source.audio_frames_read, test_source.audio_bytes_read, test_source.ogg_headers_skipped,\n                )\n\n            async def report_test_result():\n                connection = getattr(voice, \"_connection\", None)\n                dave_session = getattr(connection, \"dave_session\", None)\n                dave_protocol = getattr(connection, \"dave_protocol_version\", \"desconhecido\")\n                dave_ready = getattr(dave_session, \"ready\", None) if dave_session else False\n                can_encrypt = getattr(connection, \"can_encrypt\", None) if connection else None\n                dave_label = f\"DAVE protocolo {dave_protocol}; sessão pronta: {dave_ready}; criptografia ativa: {can_encrypt}\"\n                if error:\n                    message = (\n                        f\"❌ O teste de áudio falhou durante o envio. Erro: \"\n                        f\"`{type(error).__name__}: {str(error)[:240]}`.\\n{dave_label}\"\n                    )\n                else:\n                    message = (\n                        f\"✅ O player terminou o teste: **{test_source.audio_frames_read} quadros Opus reais** \"\n                        f\"({test_source.audio_bytes_read} bytes); descartei {test_source.ogg_headers_skipped} cabeçalhos Ogg.\\n\"\n                        f\"{dave_label}\\n\"\n                        \"Se você não ouviu o tom, essa medição indica que o FFmpeg e o player leram os quadros; \"\n                        \"o estado DAVE/conexão acima ajuda a localizar a falha restante.\"\n                    )\n                try:\n                    await interaction.followup.send(message, ephemeral=True)\n                except discord.HTTPException:\n                    logger.exception(\"Não foi possível enviar o resultado do teste de som\")\n\n            try:\n                asyncio.run_coroutine_threadsafe(report_test_result(), bot.loop)\n            except RuntimeError:\n                logger.exception(\"Loop do CAOS encerrou antes do relatório do teste de som\")\n        try:\n            voice.play(source, after=after_test)\n        except Exception:\n            source.cleanup()\n            source = None\n            raise\n        source = None  # o AudioPlayer agora é dono da fonte e faz cleanup()\n        await interaction.followup.send(\n            f\"🔊 Teste iniciado em {voice.channel.mention}. Aguarde a confirmação automática após os 4 segundos.\",\n            ephemeral=True,\n        )\n    except Exception as exc:\n        if source:\n            source.cleanup()\n        if raw_source:\n            raw_source.cleanup()\n        logger.exception(\"Falha no teste de som\")\n        detail = str(exc).replace(\"`\", \"'\")[:250]\n        await interaction.followup.send(\n            f\"❌ Não consegui iniciar o teste de som: `{type(exc).__name__}: {detail}`\", ephemeral=True\n        )\n\n\n@bot.tree.command(name=\"diagnostico_audio\", description=\"Testa DAVE, FFmpeg/Opus, dependências e a busca real de músicas do CAOS.\")\n@app_commands.checks.has_permissions(administrator=True)\nasync def diagnostico_audio(interaction: discord.Interaction):\n    await interaction.response.defer(ephemeral=True, thinking=True)\n    lines = []\n    lines.append(f\"📂 Arquivo em execução: `{Path(__file__).resolve()}`\")\n    lines.append(f\"🆔 Processo: `{os.getpid()}`\")\n    try:\n        ffmpeg_path = _resolve_ffmpeg_executable()\n        probe = subprocess.run([ffmpeg_path, \"-version\"], capture_output=True, text=True, timeout=10)\n        version_line = (probe.stdout or probe.stderr).splitlines()[0][:140] if (probe.stdout or probe.stderr) else \"sem retorno\"\n        source = \"imageio-ffmpeg\" if imageio_ffmpeg is not None else \"FFmpeg do PATH\"\n        lines.append(f\"{'✅' if probe.returncode == 0 else '❌'} FFmpeg ({source}): `{version_line}`\")\n    except Exception as exc:\n        lines.append(f\"❌ FFmpeg: `{type(exc).__name__}: {str(exc)[:260]}`\")\n    deno_path = _music_deno_path()\n    if deno_path:\n        try:\n            probe = subprocess.run([deno_path, \"--version\"], capture_output=True, text=True, timeout=10)\n            deno_version = (probe.stdout or probe.stderr).splitlines()[0][:100]\n            lines.append(f\"{'✅' if probe.returncode == 0 else '❌'} Deno: `{deno_version}`\")\n        except Exception as exc:\n            lines.append(f\"❌ Deno: `{type(exc).__name__}`\")\n    else:\n        lines.append(\"❌ Deno: não encontrado neste Python. Feche e abra INICIAR_CAOS.bat para instalar as dependências.\")\n    ytdlp_module = yt_dlp\n    if ytdlp_module is None:\n        try:\n            ytdlp_module = importlib.import_module(\"yt_dlp\")\n        except Exception:\n            ytdlp_module = None\n    lines.append(f\"🐍 Python: `{sys.executable}`\")\n    lines.append(f\"📦 discord.py: `{getattr(discord, '__version__', 'desconhecido')}`\")\n    if dave_runtime is not None:\n        lines.append(f\"🧩 Módulo davey carregado: `{getattr(dave_runtime, '__file__', 'caminho não informado')}`\")\n    try:\n        from importlib.metadata import distributions\n        dave_dist_versions = sorted({\n            dist.version for dist in distributions()\n            if (dist.metadata.get(\"Name\") or \"\").lower().replace(\"_\", \"-\") == \"davey\"\n        })\n        if dave_dist_versions:\n            lines.append(f\"📚 Distribuições davey encontradas: `{', '.join(dave_dist_versions)}`\")\n    except Exception as exc:\n        lines.append(f\"⚠️ Não consegui listar as distribuições davey: `{type(exc).__name__}`\")\n    stack_issue = _voice_stack_issue()\n    if stack_issue:\n        lines.append(f\"❌ Voz DAVE: `{stack_issue[:300]}`\")\n    else:\n        try:\n            from importlib.metadata import version as package_version\n            dave_version = package_version(\"davey\")\n        except Exception:\n            dave_version = \"instalado\"\n        lines.append(f\"✅ Voz DAVE: `davey {dave_version}` disponível\")\n    if ytdlp_module is not None:\n        lines.append(f\"✅ yt-dlp: `{ytdlp_module.version.__version__}`\")\n        try:\n            import yt_dlp_ejs  # noqa: F401\n            lines.append(\"✅ yt-dlp-ejs: instalado\")\n        except Exception:\n            lines.append(\"⚠️ yt-dlp-ejs: não importável neste Python. Feche e abra INICIAR_CAOS.bat para atualizar as dependências.\")\n        try:\n            test_results = await asyncio.wait_for(asyncio.to_thread(_youtube_search_sync, \"lofi music\"), timeout=45)\n            lines.append(f\"{'✅' if test_results else '⚠️'} Busca YouTube: {len(test_results)} resultados de teste\")\n        except Exception as exc:\n            lines.append(f\"❌ Busca YouTube: `{type(exc).__name__}: {str(exc)[:180]}`\")\n    else:\n        lines.append(\"❌ yt-dlp: não instalado\")\n    try:\n        import nacl  # noqa: F401\n        lines.append(\"✅ PyNaCl: instalado (criptografia da conexão de voz).\")\n    except Exception as exc:\n        lines.append(f\"❌ PyNaCl: `{type(exc).__name__}`. Reinstale `discord.py[voice]`.\")\n    try:\n        ffmpeg_path = _resolve_ffmpeg_executable()\n        opus_probe = discord.FFmpegOpusAudio(\n            \"sine=frequency=660:duration=1\",\n            executable=ffmpeg_path,\n            bitrate=96,\n            before_options=\"-f lavfi\",\n            options=\"-loglevel error\",\n        )\n        managed_probe = _ManagedOpusSource(opus_probe)\n        try:\n            real_frames = []\n            for _ in range(8):\n                frame = managed_probe.read()\n                if not frame:\n                    break\n                real_frames.append(frame)\n            if not real_frames:\n                probe_error = getattr(opus_probe, \"_current_error\", None)\n                raise RuntimeError(f\"FFmpeg não gerou quadros Opus de áudio: {probe_error or 'saída vazia'}\")\n            if any(frame.startswith(_ManagedOpusSource._OGG_METADATA_PREFIXES) for frame in real_frames):\n                raise RuntimeError(\"A fonte ainda está entregando metadados Ogg como áudio.\")\n            lines.append(\n                f\"✅ FFmpeg → Opus: {len(real_frames)} quadros reais lidos; \"\n                f\"{managed_probe.ogg_headers_skipped} cabeçalhos Ogg descartados; \"\n                f\"primeiro quadro: {len(real_frames[0])} bytes.\"\n            )\n        finally:\n            managed_probe.cleanup()\n        try:\n            opus_loaded = discord.opus.is_loaded()\n        except Exception:\n            opus_loaded = False\n        if opus_loaded:\n            lines.append(\"✅ Opus interno do discord.py: carregado (alternativa disponível).\")\n        else:\n            lines.append(\"ℹ️ Opus interno do discord.py: não carregado; não é necessário neste player, pois o FFmpeg envia Opus pronto.\")\n        lines.append(\"🎼 Reprodução: yt-dlp baixa temporariamente; FFmpeg codifica o arquivo em Opus; Discord transmite os pacotes prontos.\")\n    except Exception as exc:\n        lines.append(f\"❌ Teste local de Opus via FFmpeg: `{type(exc).__name__}: {str(exc)[:200]}`\")\n    voice = interaction.guild.voice_client if interaction.guild else None\n    lines.append(f\"🎧 Voz: {'conectado em ' + voice.channel.name if voice and voice.is_connected() else 'desconectado'}\")\n    if voice and voice.is_connected():\n        connection = getattr(voice, \"_connection\", None)\n        dave_session = getattr(connection, \"dave_session\", None) if connection else None\n        dave_protocol = getattr(connection, \"dave_protocol_version\", \"desconhecido\") if connection else \"desconhecido\"\n        dave_ready = getattr(dave_session, \"ready\", None) if dave_session else False        can_encrypt = getattr(connection, \"can_encrypt\", None) if connection else None\n        lines.append(\n            f\"🔐 DAVE ativo: protocolo `{dave_protocol}` | sessão pronta: `{dave_ready}` | \"\n            f\"criptografia de voz: `{can_encrypt}`\"\n        )\n        if voice.is_playing():\n            lines.append(\"▶️ Player Discord: reproduzindo áudio agora.\")\n        elif voice.is_paused():\n            lines.append(\"⏸️ Player Discord: áudio pausado.\")\n        else:\n            lines.append(\"⏹️ Player Discord: conectado, mas sem áudio ativo.\")\n        active_source = voice.source\n        if active_source is not None:\n            try:\n                opus_state = active_source.is_opus()\n            except Exception:\n                opus_state = \"não identificado\"\n            lines.append(f\"🎼 Fonte de áudio: {type(active_source).__name__} | Opus: {opus_state}\")\n    bot_member = interaction.guild.me if interaction.guild else None\n    if bot_member and bot_member.voice:\n        state = bot_member.voice\n        if state.mute:\n            lines.append(\"❌ Mute do servidor: ativo. Um administrador precisa remover o silenciamento do CAOS.\")\n        else:\n            lines.append(\"✅ Mute do servidor: desligado.\")\n        if state.self_mute:\n            lines.append(\"❌ Auto-mute: ativo. Use `/entrar canal` para tentar desligar.\")\n        else:\n            lines.append(\"✅ Auto-mute: desligado.\")\n        if state.self_deaf:\n            lines.append(\"⚠️ Auto-deafen: ativo. O CAOS será normalizado para ficar com os fones ligados.\")\n        else:\n            lines.append(\"✅ Auto-deafen: desligado.\")\n    lines.append(f\"🖼️ Arte do painel: {'✅ encontrada' if (PANEL_ART_DIR / PANEL_ART['music']).is_file() else '❌ arquivo assets/panels/music.jpg ausente'}\")\n    embed = discord.Embed(\n        title=\"「🔧」ᴅɪᴀɢɴóꜱᴛɪᴄᴏ ᴅᴇ áᴜᴅɪᴏ • ᴄᴀᴏꜱ\",\n        description=\"\\n\".join(lines),\n        colour=discord.Colour.from_rgb(22, 126, 220),\n    )\n    embed.set_footer(text=\"A voz do Discord exige DAVE. Este diagnóstico verifica davey, FFmpeg/Opus e o estado do player.\")\n    await interaction.followup.send(embed=embed, ephemeral=True)\n\n\n@bot.tree.command(name=\"meu_rank\", description=\"Mostra sua posição no ranking de tempo em ponto.\")\nasync def meu_rank(interaction: discord.Interaction):\n    await send_rank(interaction, interaction.user.id, self_only=True)\n\n\n@bot.tree.command(name=\"rank\", description=\"Consulta o ranking de tempo em ponto de outro membro.\")\n@app_commands.describe(membro=\"Membro cujo ranking deseja consultar\")\nasync def rank(interaction: discord.Interaction, membro: discord.Member):\n    await send_rank(interaction, membro.id, self_only=False)\n\n\n@bot.tree.command(name=\"configurar_call_ponto\", description=\"Define a call em que entrar inicia o bate-ponto automaticamente.\")\n@app_commands.checks.has_permissions(administrator=True)\nasync def configurar_call_ponto(interaction: discord.Interaction, canal: discord.VoiceChannel):\n    if not interaction.guild:\n        return await interaction.response.send_message(\"Use em um servidor.\", ephemeral=True)\n    config_set(interaction.guild.id, \"point_voice_channel_id\", canal.id)\n    me = interaction.guild.me\n    permissions = canal.permissions_for(me) if me else None\n    warning = \"\"\n    if not permissions or not permissions.move_members:\n        warning = \"\\n⚠️ Também dê ao bot a permissão **Mover membros** nessa call/servidor para aplicar a desconexão após 3 minutos sem confirmação.\"\n    await interaction.response.send_message(\n        f\"✅ Call monitorada configurada: {canal.mention}. Entrar inicia o ponto e sair encerra automaticamente. Lembretes a cada 3 horas e prazo de 3 minutos.{warning}\",\n        ephemeral=True,\n    )\n\n\n@bot.tree.command(name=\"configurar_susto\", description=\"Ativa ou desativa a brincadeira opcional de música de terror a cada 5 horas.\")\n@app_commands.checks.has_permissions(administrator=True)\nasync def configurar_susto(interaction: discord.Interaction, ativar: bool):\n    guild = interaction.guild\n    if guild is None:\n        return await interaction.response.send_message(\"Use em um servidor.\", ephemeral=True)\n    if ativar:\n        channel_id = config_get(guild.id, \"point_voice_channel_id\")\n        channel = guild.get_channel(int(channel_id)) if channel_id and str(channel_id).isdigit() else None\n        if not isinstance(channel, discord.VoiceChannel):\n            return await interaction.response.send_message(\n                \"Configure primeiro a call monitorada com `/configurar_call_ponto`. A brincadeira usa essa call e escolhe um membro com ponto ativo.\",\n                ephemeral=True,\n            )\n        config_set(guild.id, \"horror_prank_enabled\", \"1\")\n        config_set(guild.id, \"horror_prank_next_run\", (datetime.now(timezone.utc) + timedelta(seconds=HORROR_INTERVAL_SECONDS)).isoformat())\n        await interaction.response.send_message(\n            \"👻 Brincadeira ativada! A cada 5 horas, se houver alguém com ponto ativo na call monitorada e o CAOS estiver livre, ele entra e toca uma trilha de terror por até 20 minutos. Depois sai automaticamente.\\n\\nO CAOS não interrompe uma música ou conexão de voz que já esteja em andamento.\",\n            ephemeral=True,\n        )\n    else:\n        config_set(guild.id, \"horror_prank_enabled\", \"0\")\n        config_set(guild.id, \"horror_prank_next_run\", \"\")\n        task = HORROR_TASKS.get(guild.id)\n        if task and not task.done():\n            task.cancel()\n        await interaction.response.send_message(\"🔕 Brincadeira de terror desativada. Nenhum novo ciclo será iniciado.\", ephemeral=True)\n\n\n@bot.tree.command(name=\"configurar_cargo_fac\", description=\"Define o cargo que identifica os integrantes sujeitos às metas e ADVs.\")\n@app_commands.checks.has_permissions(administrator=True)\nasync def configurar_cargo_fac(interaction: discord.Interaction, cargo: discord.Role):\n    if not interaction.guild:\n        return await interaction.response.send_message(\"Use em um servidor.\", ephemeral=True)\n    config_set(interaction.guild.id, \"fac_member_role_id\", cargo.id)\n    await interaction.response.send_message(f\"✅ Cargo de integrantes da FAC definido: {cargo.mention}. Promoções e conferência de metas considerarão os membros com este cargo.\", ephemeral=True)\n\n\n@bot.tree.command(name=\"configurar_cargos_promocao\", description=\"Define os quatro cargos da progressão semanal de 5 horas.\")\n@app_commands.checks.has_permissions(administrator=True)\nasync def configurar_cargos_promocao(\n    interaction: discord.Interaction,\n    olheiro: discord.Role,\n    aviaozinho: discord.Role,\n    vapor: discord.Role,\n    traficante: discord.Role,\n):\n    if not interaction.guild:\n        return await interaction.response.send_message(\"Use em um servidor.\", ephemeral=True)\n    roles = [olheiro, aviaozinho, vapor, traficante]\n    if len({r.id for r in roles}) != 4:\n        return await interaction.response.send_message(\"Escolha quatro cargos diferentes.\", ephemeral=True)\n    me = interaction.guild.me\n    if not me or not me.guild_permissions.manage_roles or any(me.top_role <= role for role in roles):\n        return await interaction.response.send_message(\"O bot precisa de **Gerenciar cargos** e seu cargo mais alto deve ficar acima dos quatro cargos de promoção.\", ephemeral=True)\n    if not (olheiro.position < aviaozinho.position < vapor.position < traficante.position):\n        return await interaction.response.send_message(\"A ordem dos cargos no Discord precisa ser Olheiro, Aviãozinho, Vapor e Traficante, do mais baixo para o mais alto.\", ephemeral=True)\n    for key, role in zip(PROMOTION_ROLE_KEYS, roles):\n        config_set(interaction.guild.id, key, role.id)\n    await interaction.response.send_message(\n        \"✅ Hierarquia semanal configurada:\\n\" + \"\\n\".join(f\"{i+1}. {role.mention}\" for i, role in enumerate(roles)) +\n        \"\\nCada etapa exige 5 horas na semana anterior; a promoção é processada na semana seguinte.\",\n        ephemeral=True,\n    )\n\n\n@bot.tree.command(name=\"configurar_recrutador\", description=\"Define o cargo [REC-OFC] autorizado a analisar recrutamentos e atribuir cargos.\")\n@app_commands.checks.has_permissions(administrator=True)\nasync def configurar_recrutador(interaction: discord.Interaction, cargo: discord.Role):\n    if not interaction.guild:\n        return await interaction.response.send_message(\"Use em um servidor.\", ephemeral=True)\n    config_set(interaction.guild.id, \"recruiter_role_id\", cargo.id)\n    with db() as con:\n        open_rooms = con.execute(\n            \"SELECT channel_id FROM rooms WHERE guild_id=? AND kind='recruit' AND status='open'\",\n            (interaction.guild.id,),\n        ).fetchall()\n    updated = 0\n    for item in open_rooms:\n        channel = interaction.guild.get_channel(int(item[\"channel_id\"]))\n        if isinstance(channel, discord.TextChannel):\n            try:\n                await channel.set_permissions(cargo, view_channel=True, read_message_history=True, send_messages=True, manage_messages=True)\n                updated += 1\n            except discord.Forbidden:\n                pass\n    await interaction.response.send_message(f\"✅ Cargo de recrutador configurado: {cargo.mention}. Ele poderá aprovar/reprovar inscrições e atribuir cargos abaixo dele, respeitando a hierarquia do Discord. Acesso atualizado em {updated} recrutamento(s) aberto(s).\", ephemeral=True)\n\n\n@bot.tree.command(name=\"configurar_cargo_aprovado\", description=\"Define o cargo inicial atribuído automaticamente ao candidato aprovado.\")\n@app_commands.checks.has_permissions(administrator=True)\nasync def configurar_cargo_aprovado(interaction: discord.Interaction, cargo: discord.Role):\n    if not interaction.guild:\n        return await interaction.response.send_message(\"Use em um servidor.\", ephemeral=True)\n    me = interaction.guild.me\n    if not me or not me.guild_permissions.manage_roles or me.top_role <= cargo:\n        return await interaction.response.send_message(\"O cargo do bot precisa ficar acima do cargo que será atribuído.\", ephemeral=True)\n    config_set(interaction.guild.id, \"recruitment_approved_role_id\", cargo.id)\n    await interaction.response.send_message(f\"✅ Cargo atribuído automaticamente quando o recrutador clicar em **Aprovado**: {cargo.mention}.\", ephemeral=True)\n\n\n@bot.tree.command(name=\"recrutador_adicionar_cargo\", description=\"Permite ao REC-OFC atribuir um cargo acima na hierarquia a um membro.\")\n@app_commands.describe(membro=\"Membro que receberá o cargo\", cargo=\"Cargo que será atribuído\")\nasync def recrutador_adicionar_cargo(interaction: discord.Interaction, membro: discord.Member, cargo: discord.Role):\n    guild = interaction.guild\n    actor = interaction.user\n    if guild is None or not isinstance(actor, discord.Member):\n        return await interaction.response.send_message(\"Use em um servidor.\", ephemeral=True)\n    rec_role = await recruiter_role(guild)\n    if not (actor.guild_permissions.administrator or (rec_role and rec_role in actor.roles)):\n        return await interaction.response.send_message(\"⛔ Apenas [REC-OFC] Recrutador oficial ou administradores podem atribuir cargos por este comando.\", ephemeral=True)\n    if rec_role and not actor.guild_permissions.administrator and rec_role.position <= cargo.position:\n        return await interaction.response.send_message(\"⛔ Você só pode atribuir cargos abaixo do cargo [REC-OFC] na hierarquia.\", ephemeral=True)\n    me = guild.me\n    if not me or not me.guild_permissions.manage_roles or me.top_role <= cargo:\n        return await interaction.response.send_message(\"O bot precisa ter **Gerenciar cargos** e estar acima do cargo escolhido.\", ephemeral=True)\n    try:\n        await membro.add_roles(cargo, reason=f\"Cargo atribuído por {actor} via recrutamento CAOS\")\n    except discord.Forbidden:\n        return await interaction.response.send_message(\"O Discord bloqueou a atribuição. Confira a hierarquia do bot.\", ephemeral=True)\n    await interaction.response.send_message(f\"✅ {cargo.mention} atribuído a {membro.mention}.\", ephemeral=True)\n    await notify_staff(guild, f\"👮 {actor.mention} atribuiu {cargo.mention} a {membro.mention}.\")\n\n\n@bot.tree.command(name=\"cobrar_meta\", description=\"Abre um prazo de 5 dias para um membro entregar uma meta.\")\n@app_commands.checks.has_permissions(manage_guild=True)\n@app_commands.describe(membro=\"Membro que deverá entregar a meta\", descricao=\"O que precisa ser entregue\")\nasync def cobrar_meta(interaction: discord.Interaction, membro: discord.Member, descricao: str = \"Fazer 20, colocar no baú e enviar foto\"):\n    guild = interaction.guild\n    actor = interaction.user\n    if guild is None or not isinstance(actor, discord.Member):\n        return await interaction.response.send_message(\"Use em um servidor.\", ephemeral=True)\n    if membro.bot:\n        return await interaction.response.send_message(\"Não é possível cobrar meta de um bot.\", ephemeral=True)\n    with db() as con:\n        existing = con.execute(\n            \"SELECT id, deadline_at FROM goal_obligations WHERE guild_id=? AND user_id=? AND status IN ('pendente','em_adv') ORDER BY id DESC LIMIT 1\",\n            (guild.id, membro.id),\n        ).fetchone()\n    if existing:\n        return await interaction.response.send_message(\n            f\"Este membro já tem uma meta pendente. Prazo atual: <t:{int(_aware_utc(existing['deadline_at']).timestamp())}:F>.\",\n            ephemeral=True,\n        )\n    deadline = datetime.now(timezone.utc) + timedelta(days=ADV_GRACE_DAYS)\n    with db() as con:\n        con.execute(\n            \"INSERT INTO goal_obligations(guild_id,user_id,created_by,description,deadline_at,status,created_at) VALUES(?,?,?,?,?,'pendente',?)\",\n            (guild.id, membro.id, actor.id, descricao[:300], deadline.isoformat(), utc_now()),\n        )\n    try:\n        await membro.send(\n            embed=discord.Embed(\n                title=\"🎯 Meta pendente — prazo de 5 dias\",\n                description=(f\"A liderança registrou uma meta para você: **{descricao[:300]}**.\\n\\n\"\n                             f\"Você tem até <t:{int(deadline.timestamp())}:F> para entregar e enviar a comprovação. \"\n                             \"Se não regularizar dentro do prazo, o sistema aplicará a **ADV 1 de 3**. \"\n                             \"Se a pendência continuar, as próximas advertências serão enviadas em intervalos de 5 dias.\"),\n                colour=discord.Colour.orange(), timestamp=discord.utils.utcnow(),\n            )\n        )\n    except discord.Forbidden:\n        await notify_staff(guild, f\"⚠️ Não consegui enviar a cobrança de meta por PV para {membro.mention}.\")\n    await interaction.response.send_message(\n        f\"✅ Meta cobrada de {membro.mention}. Prazo de 5 dias: <t:{int(deadline.timestamp())}:F>. Depois disso começa a progressão de ADV se a pendência continuar aberta.\",\n        ephemeral=True,\n    )\n    await notify_staff(guild, f\"🎯 {actor.mention} cobrou meta de {membro.mention}: **{descricao[:300]}**. Prazo: <t:{int(deadline.timestamp())}:F>.\")\n\n\n@bot.tree.command(name=\"ver_adv\", description=\"Consulta a quantidade de advertências de um membro.\")\n@app_commands.checks.has_permissions(manage_guild=True)\nasync def ver_adv(interaction: discord.Interaction, membro: discord.Member):\n    if not interaction.guild:\n        return await interaction.response.send_message(\"Use em um servidor.\", ephemeral=True)\n    with db() as con:\n        row = con.execute(\"SELECT adv_count, last_adv_at, next_adv_at FROM adv_state WHERE guild_id=? AND user_id=?\", (interaction.guild.id, membro.id)).fetchone()\n        history = con.execute(\"SELECT adv_count,event_type,note,created_at FROM adv_events WHERE guild_id=? AND user_id=? ORDER BY id DESC LIMIT 8\", (interaction.guild.id, membro.id)).fetchall()\n    count = int(row[\"adv_count\"]) if row else 0\n    details = \"\\n\".join(f\"• {item['event_type']} — {item['adv_count']}/3 — {item['note']}\" for item in history) or \"Sem histórico.\"\n    await interaction.response.send_message(f\"🚨 **{membro.display_name}: {count}/3 ADVs**\\n{details}\", ephemeral=True)\n\n\n@bot.tree.command(name=\"aplicar_adv\", description=\"Aplica a próxima advertência manualmente a um membro.\")\n@app_commands.checks.has_permissions(manage_guild=True)\nasync def aplicar_adv(interaction: discord.Interaction, membro: discord.Member, motivo: str = \"Advertência aplicada pela equipe\"):\n    if not interaction.guild:\n        return await interaction.response.send_message(\"Use em um servidor.\", ephemeral=True)\n    with db() as con:\n        row = con.execute(\"SELECT adv_count FROM adv_state WHERE guild_id=? AND user_id=?\", (interaction.guild.id, membro.id)).fetchone()\n    current = int(row[\"adv_count\"]) if row else 0\n    if current >= 3:\n        return await interaction.response.send_message(\"Este membro já está em ADV 3/3. Use o ticket de regularização para validar a meta ou o pagamento de 300k.\", ephemeral=True)\n    await apply_adv(interaction.guild, membro, current + 1, motivo[:300])\n    await interaction.response.send_message(f\"✅ ADV {current + 1}/3 aplicada a {membro.mention}.\", ephemeral=True)\n\n\n@bot.tree.command(name=\"ajuda\", description=\"Mostra os comandos disponíveis do CAOS.\")\nasync def ajuda(interaction: discord.Interaction):\n    embed = discord.Embed(title=\"🤖・AJUDA DO CAOS\", colour=discord.Colour.from_rgb(22, 126, 220))\n    embed.description = (\n        \"**Administradores**\\n\"\n        \"`/instalar cargo_equipe` — prepara cargos e categorias privadas.\\n\"\n        \"`/configurar_logs canal` — define o canal de registros e transcrições.\\n\"\n        \"`/configurar_call_ponto canal` — define a call monitorada do bate-ponto automático.\\n\"\n        \"`/configurar_cargo_fac cargo` — define quem entra no controle semanal de metas/ADV.\\n\"\n        \"`/configurar_cargos_promocao olheiro aviaozinho vapor traficante` — configura a progressão.\\n\"\n        \"`/configurar_recrutador cargo` — define [REC-OFC] Recrutador oficial.\\n\"\n        \"`/configurar_cargo_aprovado cargo` — define cargo automático de aprovado; após aprovação, o apelido recebe nome e ID do jogo.\\n\"\n        \"`/recrutador_adicionar_cargo membro cargo` — atribui cargo respeitando hierarquia.\\n\"\n        \"`/configurar_susto ativar` — liga/desliga a brincadeira de terror: 5 horas, até 20 minutos.\\n\"\n        \"`/gerar_paineis` — escolhe painel, canal e título num gerenciador único.\\n\"\n        \"`/c` — apaga todas as mensagens do canal atual (permissão Gerenciar mensagens).\\n\"\n        \"O botão **FECHAR CANAL** aparece nos canais temporários e só funciona para o cargo de equipe configurado e cargos acima dele, administradores e dono.\\n\"\n        \"`/painel_ticket canal` — publica o painel de tickets.\\n\"\n        \"`/painel_ponto canal` — publica o painel de ponto e ranking.\\n\"\n        \"`/painel_metas canal` — publica o painel de entrega de metas.\\n\"\n        \"`/painel_recrutamento canal` — publica o painel de recrutamento.\\n\"\n        \"`/painel_encomendas canal` — publica o painel de encomendas e parcerias.\\n\"\n        \"`/painel_regras_discord canal` — publica as regras do Discord.\\n\"\n        \"`/painel_regras_equipe canal` — publica as regras da equipe.\\n\"\n        \"`/painel_regras_rp canal` — publica as regras de RP.\\n\"\n        \"`/painel_musica canal` — publica o painel independente de música.\\n\"\n        \"`/painel_ia` — escolhe canais de perguntas, imagens e monitoramento REC/formulário.\\n\"\n        \"`/painel_copiar` — painel privado para copiar o histórico de um canal acessível para outro servidor.\\n\"\n        \"**Membros**\\n\"\n        \"`/musica busca` — pesquisa e mostra até cinco capas com botão para tocar.\\n\"\n        \"`/entrar canal` — faz o bot entrar numa call, mesmo vazia.\\n\"\n        \"`/sair` — desconecta da call e limpa a fila.\\n\"\n        \"`/pausar_musica`, `/retomar_musica`, `/pular_musica`, `/parar_musica`.\\n\"\n        \"`/fila_musica` e `/volume_musica porcentagem` — controles de áudio.\\n\"\n        \"`/teste_som` — toca um apito curto para testar o áudio na call.\\n\"\n        \"`/diagnostico_audio` — testa FFmpeg→Opus, Deno, yt-dlp/EJS, busca e voz.\\n\"\n        \"`/perguntar pergunta` — conversa com a IA no canal configurado.\\n\"\n        \"`/criar_imagem descricao` — gera uma imagem no canal configurado.\\n\"\n        \"`/meu_rank` e `/rank membro` — consultam o ranking de ponto.\\n\"\n        \"`/cobrar_meta membro descricao` — dá 5 dias para entregar uma meta; depois inicia ADV automática.\\n\"\n        \"`/ver_adv membro` — consulta ADVs; `/aplicar_adv membro motivo` aplica ADV manual.\"\n    )\n    await interaction.response.send_message(embed=embed, ephemeral=True)\n\n\n@bot.tree.error\nasync def on_app_command_error(interaction: discord.Interaction, error: app_commands.AppCommandError):\n    command_name = interaction.command.name if interaction.command else \"desconhecido\"\n    original = getattr(error, \"original\", error)\n    logger.error(\n        \"Erro no comando /%s: %r\",\n        command_name,\n        original,\n        exc_info=(type(original), original, original.__traceback__),\n    )\n    if isinstance(error, app_commands.errors.MissingPermissions):\n        missing = set(getattr(error, \"missing_permissions\", []))\n        if \"manage_messages\" in missing:\n            message = \"Este comando exige a permissão **Gerenciar mensagens** no canal/servidor.\"\n        elif \"manage_guild\" in missing:\n            message = \"Este comando exige **Gerenciar servidor** ou Administrador.\"\n        else:\n            message = \"Este comando é exclusivo para administradores do servidor.\"\n    elif command_name == \"painel_ia\":\n        message = (\n            f\"⚠️ O painel de IA encontrou uma falha técnica (**{type(original).__name__}**). \"\n            \"O detalhe completo foi registrado no log do CAOS. Reinicie o bot com o ZIP corrigido e, se persistir, envie o trecho do log.\"\n        )\n    else:\n        message = \"Não consegui concluir o comando. Confira o log do CAOS para identificar a falha.\"\n    try:\n        if interaction.response.is_done():\n            await interaction.followup.send(message, ephemeral=True)\n        else:\n            await interaction.response.send_message(message, ephemeral=True)\n    except discord.HTTPException:\n        logger.exception(\"Não foi possível enviar a mensagem de erro do comando /%s\", command_name)\n\n\nasync def main():\n    if not TOKEN or TOKEN in {\"COLOQUE_SEU_TOKEN_AQUI\", \"SEU_TOKEN_AQUI\"}:\n        raise SystemExit(\"ERRO: preencha DISCORD_TOKEN no arquivo .env antes de iniciar o CAOS.\")\n    init_db()\n    async with bot:\n        await bot.start(TOKEN)\n\n\nif __name__ == \"__main__\":\n    try:\n        asyncio.run(main())\n    except KeyboardInterrupt:\n        print(\"CAOS encerrado pelo operador.\")";
export const BOT_PRONTO_REQUIREMENTS = "discord.py[voice]==2.7.1\ndavey==0.1.7\nPyNaCl>=1.5.0,<1.6.0\npython-dotenv>=1.0,<2.0\n# yt-dlp-ejs alinhado à versão instalada do yt-dlp.\nyt-dlp[default]>=2026.10.26\ndeno>=2.3.0\nimageio-ffmpeg>=0.8.1";
